	["Dark Mode leaves the coloured debuff borders (magic, curse, poison, disease) alone."] = "Тёмный режим не трогает цветные каймы отрицательных эффектов (магия, проклятие, яд, болезнь).", -- draft
	-- Fonts
	["Fonts"] = "Шрифты", -- draft
	["One font per role: interface text, chat and numbers, titles, damage numbers; plus size and outline."] = "Свой шрифт для каждой роли: текст интерфейса, чат и числа, заголовки, числа урона; а также размер и контур.", -- draft
	["One font for all of Azeroth. Pick it, scale it, outline it."] = "Один шрифт на весь Азерот. Выберите, масштабируйте, обведите.", -- draft
	["Font Style"] = "Стиль шрифтов", -- draft
	["A preset that sets every font and text size at once. Change any font afterwards and the style shows Custom.\nFredoka: MelloUI's own round letters, made to fit its icons. The default.\nScriptorium: Carved capitals over a warm book face.\nChronicle: Small capitals over the most readable book face.\nOld Tome: Aged print, like an old book.\nWarband: Bold blackletter: the boldest look.\nClarity: Plain letters: the easiest to read at small sizes.\nGothic: Gothic titles over a book face."] = "Набор, задающий все шрифты и размеры текста сразу. Измените потом любой шрифт — стиль покажет «Вручную».\nFredoka: круглые буквы MelloUI, подобранные к его значкам. По умолчанию.\nScriptorium: высеченные заглавные над тёплым книжным шрифтом.\nChronicle: капитель над самым читаемым книжным шрифтом.\nOld Tome: состаренная печать, как в старой книге.\nWarband: жирный готический шрифт: самый смелый вид.\nClarity: простые буквы: легче всего читать мелким кеглем.\nGothic: готические заголовки над книжным шрифтом.", -- draft
	["preset: changes every font at once"] = "набор: меняет все шрифты сразу", -- draft
	["Custom"] = "Свой", -- draft
