	["Execute Range"] = "Зона добивания", -- draft
	["An enemy's health bar turns purple below the Execute Below health, on frames and nameplates."] = "Полоса здоровья противника становится фиолетовой ниже порога «Казнь», на рамках и индикаторах здоровья.", -- draft
