	["Show Tenths Below 5s"] = "Десятые меньше 5 с", -- draft
	["Shows 4.3 instead of 5 in a cooldown's last seconds."] = "Показывает 4,3 вместо 5 в последние секунды восстановления.", -- draft
	["Colour And Size By Time Left"] = "Цвет и размер по оставшемуся времени", -- draft
	["Timers turn red and larger under 5 seconds, yellow under a minute, and smaller for minutes and hours. Off: all white."] = "Таймеры краснеют и крупнеют меньше 5 секунд, желтеют меньше минуты и мельчают для минут и часов. Выкл.: все белые.", -- draft
	-- Tweaks
	["Tweaks"] = "Доработки", -- draft
	["Hide the micro menu and bag bar, and scale the floating combat text."] = "Скрывает микроменю и панель сумок и масштабирует всплывающий текст боя.", -- draft
	["Small knobs with a big effect. Hide what you never click, scale what you never see."] = "Маленькие ручки с большим эффектом. Скройте то, что никогда не нажимаете, увеличьте то, чего никогда не видите.", -- draft
	["Hide Frames"] = "Скрыть рамки", -- draft
	["Hide Micro Menu"] = "Скрыть микроменю", -- draft
	["Hides the micro menu. It shows in Edit Mode."] = "Скрывает микроменю. В режиме редактирования оно видно.", -- draft
	["Hide Bag Bar"] = "Скрыть панель сумок", -- draft
	["Hides the bag bar. Your bag keys still work; it shows in Edit Mode."] = "Скрывает панель сумок. Клавиши сумок работают; в режиме редактирования она видна.", -- draft
	["Hide Minimap Coordinates"] = "Скрыть координаты мини-карты", -- draft
	["Hides the coordinates under the minimap."] = "Скрывает координаты под мини-картой.", -- draft
	["Bag Slots On Bag Window"] = "Ячейки сумок в окне сумок", -- draft
	["With the bag bar hidden, the bag slots show under the bag window, so you can still swap bags."] = "При скрытой панели сумок ячейки сумок показываются под окном сумок, чтобы их можно было менять.", -- draft
	["Collapse Arrow"] = "Стрелка сворачивания", -- draft
	["An arrow beside the backpack folds the bag slots away."] = "Стрелка у рюкзака сворачивает ячейки сумок.", -- draft
	["Chat"] = "Чат", -- draft
	["Chat Notices"] = "Оповещения в чате", -- draft
	["MelloUI's own lines in the chat, like hints and learned entrances. Replies to commands always show."] = "Собственные строки MelloUI в чате, например советы и изученные входы. Ответы на команды показываются всегда.", -- draft
	["Notices"] = "Оповещения", -- draft
	["On-screen Notices"] = "Оповещения на экране", -- draft
	["A short line near the top of the screen when MelloUI has news, like a route set or finished. Move it in Edit Layout."] = "Короткая строка вверху экрана, когда у MelloUI есть новости, например маршрут задан или пройден. Перемещается в «Изменить раскладку».", -- draft
	["Send To Chat Instead"] = "Отправлять в чат", -- draft
	["The notices go to the chat instead of the screen."] = "Уведомления идут в чат, а не на экран.", -- draft
	["Notice Sounds"] = "Звуки оповещений", -- draft
	["A short chime with each notice."] = "Короткий звонок с каждым уведомлением.", -- draft
	["Text Shade"] = "Тень текста", -- draft
	["A soft dark shadow behind on-screen text (zone names, messages, names on unit frames and nameplates, chat tags on parchment), so it stays readable on bright ground."] = "Мягкая тёмная тень за текстом на экране (названия зон, сообщения, имена на рамках юнитов и индикаторах здоровья, метки чата на пергаменте), чтобы он читался на светлом фоне.", -- draft
	["Outlined Text"] = "Текст с контуром", -- draft
	["An outline on MelloUI's on-screen text: notices, Combat Text and Gains. Off: soft text on a dark shadow."] = "Контур у экранного текста MelloUI: уведомлений, текста боя и находок. Выкл.: мягкий текст на тёмной тени.", -- draft
	["Combat Text"] = "Текст боя", -- draft
	["Numbers Over Enemies"] = "Числа над врагами", -- draft
	["The size of the game's damage numbers over enemies."] = "Размер чисел урона игры над противниками.", -- draft
	["Bar Layout"] = "Раскладка панелей", -- draft
	["Which Bar"] = "Какая панель", -- draft
	["The bar the rows below set: its rows, icons, icon size and padding. MelloUI's own action bars change at once; the stance and pet bars (and the game's bars with UI Modifications off) are saved into your active Edit Mode layout once you let a slider go, and show after a /reload."] = "Панель, которую настраивают строки ниже: её ряды, значки, размер и отступы. Собственные панели действий MelloUI меняются сразу; панели стоек и питомца (и панели игры без изменений интерфейса) сохраняются в активную раскладку режима редактирования, когда вы отпускаете ползунок, и видны после /reload.", -- draft
