	["Sells grey items at a merchant."] = "Продаёт серые предметы у торговца.", -- draft
	["Report In Chat"] = "Отчёт в чат", -- draft
	["Writes the repair cost and the gold from junk in the chat."] = "Пишет в чат стоимость ремонта и золото за хлам.", -- draft
	-- Services
	["Services"] = "Услуги", -- draft
	["Buttons under the minimap that route you to the nearest repair, mailbox, inn, flight master, bank or trainer."] = "Кнопки под мини-картой, ведущие к ближайшему ремонту, почтовому ящику, таверне, распорядителю полётов, банку или учителю.", -- draft
	["Repair, mailbox, innkeeper, bank... the nearest one is a click under the minimap."] = "Ремонт, почта, хозяин таверны, банк... ближайший — в один щелчок под мини-картой.", -- draft
	["Icon Bar Under The Minimap"] = "Панель значков под мини-картой", -- draft
	["Buttons for nearby services (repair, trainers, flights...) under the minimap. Click one to get a route there; right-click stops it."] = "Кнопки ближайших услуг (ремонт, учителя, полёты...) под мини-картой. Щелчок прокладывает маршрут; правый щелчок останавливает.", -- draft
	["Button Layout"] = "Раскладка кнопок", -- draft
	["Groups: one row of group buttons, each opening a list of services with distances. All Buttons: two rows, one icon per service."] = "Группы: ряд кнопок групп, каждая открывает список услуг с расстояниями. Все кнопки: два ряда, по значку на услугу.", -- draft
	["Groups"] = "Группы", -- draft
	["All Buttons"] = "Все кнопки", -- draft
	["AddOns Group"] = "Группа «Модификации»", -- draft
	["Gathers other addons' minimap buttons into an AddOns group on the Services bar. Off: they go back on the minimap."] = "Собирает кнопки мини-карты других модификаций в группу «Модификации» на панели Услуг. Выкл.: они возвращаются на мини-карту.", -- draft
	["Bar Distance From The Minimap"] = "Расстояние панели от мини-карты", -- draft
	["How far below the minimap the Services bar sits."] = "Насколько ниже мини-карты стоит панель Услуг.", -- draft
	["Round Icons"] = "Круглые значки", -- draft
	["Service icons as round medallions instead of squares."] = "Значки услуг круглыми медальонами вместо квадратов.", -- draft
	["Trays Slide Out"] = "Выезжающие лотки", -- draft
	["A group's list slides out like a drawer."] = "Список группы выдвигается, как ящик.", -- draft
	["Minimap Button"] = "Кнопка на мини-карте", -- draft
	["A round button on the minimap's edge that opens the list of the nearest services. /services does the same."] = "Круглая кнопка на краю мини-карты, открывающая список ближайших услуг. /services делает то же.", -- draft
	-- Reminders
	["Reminders"] = "Напоминания", -- draft
	["A round button by your portrait for errands: restock, mail, repairs and trainers. Click it for a route there."] = "Круглая кнопка у портрета для дел: пополнение, почта, ремонт и учителя. Щелчок прокладывает маршрут.", -- draft
	["Supplies, mail, repairs and training: a gentle nudge beside your portrait, never a nag."] = "Припасы, почта, ремонт и обучение: мягкий намёк у портрета, никогда не нытьё.", -- draft
	["New Mail"] = "Новая почта", -- draft
	["Reminds you when mail is waiting."] = "Напоминает, когда ждёт почта.", -- draft
	["Repair Gear"] = "Ремонт снаряжения", -- draft
	["Reminds you when your gear is wearing out."] = "Напоминает, когда снаряжение изнашивается.", -- draft
	["Remind At"] = "Напоминать при", -- draft
	["Reminds you when your most worn item is down to this durability."] = "Напоминает, когда самый изношенный предмет доходит до этой прочности.", -- draft
	["Trainer"] = "Наставник", -- draft
	["Reminds you when a trainer has something new for you."] = "Напоминает, когда у учителя есть что-то новое.", -- draft
	["Class Spells"] = "Заклинания класса", -- draft
	["New class spells to learn."] = "Новые заклинания класса для изучения.", -- draft
	["Profession Ranks"] = "Ранги профессий", -- draft
	["A new profession rank to learn."] = "Новый ранг профессии для изучения.", -- draft
	["Stay Up In Rest Areas"] = "Оставлять в зонах отдыха", -- draft
	["In inns, cities and towns, reminders stay until done or until you leave."] = "В тавернах, городах и посёлках напоминания остаются, пока дело не сделано или вы не уйдёте.", -- draft
	["Widget"] = "Виджет", -- draft
	["Place"] = "Место", -- draft
	["Which side of your portrait the reminder button sits on. Without a player frame, move it in Edit Layout."] = "С какой стороны портрета стоит кнопка напоминаний. Без рамки игрока перемещайте её в «Изменить раскладку».", -- draft
	["Left of the portrait"] = "Слева от портрета", -- draft
	["Above the portrait"] = "Над портретом", -- draft
	["Right of the portrait"] = "Справа от портрета", -- draft
	["Glow"] = "Свечение", -- draft
	["The soft glow around the reminder button: steady, or none."] = "Мягкое свечение кнопки напоминаний: постоянное или нет.", -- draft
	["Steady"] = "Ровно", -- draft
	["Show For"] = "Показывать", -- draft
	["How long a new reminder stays before tucking itself away."] = "Сколько новое напоминание держится, прежде чем свернуться.", -- draft
	["Lock The Widgets"] = "Закрепить виджеты", -- draft
	["Locks the widget column in place, also in Edit Layout."] = "Закрепляет колонку виджетов, также в «Изменить раскладку».", -- draft
	["Most Widgets Shown"] = "Не больше виджетов", -- draft
	["How many widgets show at once; the rest wait in a \"+ more\" row. Loot rolls, summons and ready checks always show."] = "Сколько виджетов видно сразу; остальные ждут в строке «+ ещё». Розыгрыши добычи, призывы и проверки готовности видны всегда.", -- draft
	-- Restock
	["Restock"] = "Пополнение", -- draft
	["Keeps food, drink, ammo and reagents stocked: a reminder when low, and a shopping list at merchants."] = "Держит запас еды, питья, боеприпасов и реагентов: напоминание при нехватке и список покупок у торговцев.", -- draft
	["Water, bread and arrows, topped up before they run out."] = "Вода, хлеб и стрелы, пополненные до того, как кончатся.", -- draft
	["Remind Below"] = "Напоминать ниже", -- draft
	["Reminds you when an item drops below this share of its amount."] = "Напоминает, когда предмета становится меньше этой доли от количества.", -- draft
	["Shopping List At The Shop"] = "Список покупок у торговца", -- draft
	["At a merchant, a shopping list of what you are low on. Nothing is bought until you click Buy."] = "У торговца — список покупок того, чего не хватает. Ничего не покупается, пока не нажмёте «Купить».", -- draft
	["Restock List"] = "Список пополнения", -- draft
	["What to keep in your bags, and how many. Each character has its own list. /restock opens it too."] = "Что держать в сумках и сколько. У каждого персонажа свой список. /restock тоже открывает его.", -- draft
	["Edit"] = "Изменить", -- draft
	-- Widgets
	["Widgets"] = "Виджеты", -- draft
	["Small live widgets in one column (loot rolls, summons, ready checks, whispers and more), and reminders by your portrait."] = "Маленькие живые виджеты в колонке (розыгрыши добычи, призывы, проверки готовности, шёпот и др.) и напоминания у портрета.", -- draft
	["What needs you now, in one small column."] = "То, что нужно вам прямо сейчас, в одной небольшой колонке.", -- draft
	["In The Column"] = "В колонке", -- draft
	["Loot Rolls"] = "Розыгрыш добычи", -- draft
	["Group loot rolls, with Need, Greed and Pass."] = "Розыгрыши добычи в группе: «Мне это нужно», «Не откажусь» и «Пас».", -- draft
	["Corpse Run"] = "Путь к телу", -- draft
	["As a ghost: how far your body is. Click for the way there."] = "В виде духа: как далеко ваше тело. Щелчок показывает путь.", -- draft
	["Timed Quests"] = "Задания на время", -- draft
	["Timed quests and the time left."] = "Задания на время и оставшееся время.", -- draft
	["Summons"] = "Призывы", -- draft
	["Summons, with Accept and Decline."] = "Призывы с кнопками «Принять» и «Отказаться».", -- draft
	["Resurrect Offers"] = "Предложения воскрешения", -- draft
	["Resurrect offers, with Accept and Decline."] = "Предложения воскрешения с кнопками «Принять» и «Отказаться».", -- draft
	["Ready Checks"] = "Проверки готовности", -- draft
	["Ready checks, with Ready and Not Ready."] = "Проверки готовности с кнопками «Готов» и «Не готов».", -- draft
	["Threat"] = "Угроза", -- draft
	["In group fights, a warning when you are close to pulling or have aggro."] = "В групповом бою — предупреждение, когда вы близки к перехвату угрозы или она уже на вас.", -- draft
	["Whispers"] = "Шёпот", -- draft
	["New whispers. Reply opens the whisper window. Needs the Whisper Popup Window."] = "Новый шёпот. «Ответить» открывает окно шёпота. Нужно всплывающее окно шёпота.", -- draft
	["Hunter Pet"] = "Питомец охотника", -- draft
	["Your hunter pet is unhappy, with Feed Pet."] = "Ваш питомец охотника несчастен — с кнопкой «Покормить питомца».", -- draft
	["Auction House"] = "Аукционный дом", -- draft
	["Outbid, sold, won and expired auctions."] = "Перебитые, проданные, выигранные и истёкшие лоты аукциона.", -- draft
	["Crafting"] = "Изготовление", -- draft
	["Crafting progress, with Stop."] = "Ход изготовления с кнопкой «Стоп».", -- draft
	["Profession Cooldowns"] = "Время восстановления профессий", -- draft
	["A profession cooldown is ready again."] = "Восстановление профессии снова готово.", -- draft
	["Quest Items"] = "Предметы для заданий", -- draft
	["In a quest's area, the quest's item. Click to use it."] = "В области задания — предмет задания. Щелчок использует его.", -- draft
	["Healer Drinking"] = "Пьющий лекарь", -- draft
	["When you tank: a healer is drinking, so wait before the next pull."] = "Когда вы танкуете: лекарь пьёт, подождите с пуллом.", -- draft
	["Rare Alert"] = "Оповещение о редких", -- draft
	["A rare nearby, with its distance. Click to target it."] = "Редкий противник поблизости с расстоянием. Щелчок берёт его в цель.", -- draft
	["Rare Alert Sound"] = "Звук оповещения о редких", -- draft
	["A sound when a rare is spotted."] = "Звук при обнаружении редкого противника.", -- draft
	["By The Portrait"] = "У портрета", -- draft
	["Bags Almost Full"] = "Сумки почти полны", -- draft
	["Your bags are almost full. Click for the way to the nearest vendor."] = "Сумки почти полны. Щелчок показывает путь к ближайшему торговцу.", -- draft
	["Free Slots"] = "Свободные ячейки", -- draft
	["Reminds you when this many free bag slots or fewer are left."] = "Напоминает, когда свободных ячеек остаётся столько или меньше.", -- draft
	["Talent Points"] = "Очки талантов", -- draft
	["You have talent points to spend."] = "У вас есть очки талантов.", -- draft
	["Well Fed Ending"] = "Конец «Сытости»", -- draft
	["Well Fed has two minutes left."] = "«Сытости» осталось две минуты.", -- draft
	["Weapon Poisons & Oils"] = "Яды и масла для оружия", -- draft
	["A poison, oil or sharpening stone on your weapon has run out or is ending. Click to put it back on."] = "Яд, масло или точильный камень на оружии закончились или заканчиваются. Щелчок наносит снова.", -- draft
	["Your Buffs"] = "Ваши положительные эффекты", -- draft
	["One of your own buffs is missing on you. Click to cast it."] = "На вас нет одного из ваших эффектов. Щелчок применяет его.", -- draft
	["Your Buffs On The Group"] = "Ваши эффекты на группе", -- draft
	["Group members are missing a buff you can cast. Click to cast it on them."] = "У членов группы нет эффекта, который вы можете дать. Щелчок применяет его на них.", -- draft
	-- Discard
	["Discard"] = "Выбросить", -- draft
	["A button on the bag and loot windows that throws away your cheapest grey or white junk to free a slot (sells it at a vendor)."] = "Кнопка на окнах сумок и добычи, которая выбрасывает ваш самый дешёвый серый или белый хлам, чтобы освободить ячейку (у торговца продаёт его).", -- draft
	["Full bags? The cheapest junk makes room, never anything worth keeping."] = "Сумки полны? Место освобождает самый дешёвый хлам, а не то, что стоит хранить.", -- draft
	["Discard Button"] = "Кнопка «Выбросить»", -- draft
	["A button on the bag window that throws away your cheapest junk item (sells it at a vendor). Never consumables, materials, quest items or your Restock list. A white item asks first."] = "Кнопка в окне сумок, выбрасывающая самый дешёвый хлам (у торговца — продающая). Никогда не трогает расходники, материалы, предметы заданий и список пополнения. Белый предмет — с вопросом.", -- draft
	["Discard Button On Loot"] = "Кнопка «Выбросить» на добыче", -- draft
	["The same button on the loot window. It only throws something away for loot worth more."] = "Та же кнопка в окне добычи. Выбрасывает, только если добыча дороже.", -- draft
	["Never Throw Away Items Worth"] = "Не выбрасывать дороже", -- draft
	["Stacks worth this many silver or more are never thrown away (they can still be sold)."] = "Стопки дороже стольких серебряных никогда не выбрасываются (продать можно).", -- draft
	-- Gains
	["Gains"] = "Получения", -- draft
	["Short lines beside your character for what you just gained: skill ups, items and money. Move them in Edit Layout."] = "Короткие строки рядом с персонажем о том, что вы только что получили: навыки, предметы и деньги. Перемещаются в «Изменить раскладку».", -- draft
	["Every skill point and every new item, told softly beside your character, then gone."] = "Каждое очко навыка и каждый новый предмет, тихо сказанные рядом с персонажем, а потом исчезнувшие.", -- draft
	["Show"] = "Показывать", -- draft
	["Skill Ups"] = "Рост навыков", -- draft
	["A line when a skill goes up: weapons, Defense, professions and languages."] = "Строка при росте навыка: оружие, защита, профессии и языки.", -- draft
	["Show Skill Values"] = "Показывать значения навыков", -- draft
	["The skill's new value and its cap, such as 57 / 80."] = "Новое значение навыка и его предел, например 57 / 80.", -- draft
	["Looted & Received Items"] = "Добытые и полученные предметы", -- draft
	["A line for each item you get: loot, quest rewards, crafts, mail and trades."] = "Строка для каждого полученного предмета: добыча, награды за задания, изделия, почта и обмен.", -- draft
	["Bought Items"] = "Купленные предметы", -- draft
	["A line for what you buy from a merchant."] = "Строка для покупок у торговца.", -- draft
	["Junk Items"] = "Хлам", -- draft
	["Also shows junk items."] = "Показывает и хлам.", -- draft
	["Money"] = "Деньги", -- draft
	["A line when you gain money. Gains in a row add up on one line."] = "Строка, когда вы получаете деньги. Получения подряд складываются в одну строку.", -- draft
	["Currencies"] = "Валюты", -- draft
	["A line for other currencies you gain: honor, tokens and marks."] = "Строка для других валют: честь, знаки и метки.", -- draft
	["Item Names In Quality Colour"] = "Названия предметов в цвете качества", -- draft
	["Item names in their quality colour. Off: in the text colour, easier to read on bright ground."] = "Названия предметов цветом качества. Выкл.: цветом текста, легче читать на светлом фоне.", -- draft
	["Lines"] = "Строки", -- draft
	["How long each line stays before it fades."] = "Сколько держится каждая строка перед исчезновением.", -- draft
	-- Meter
	["Damage Meter"] = "Счетчик урона", -- draft
	["MelloUI's damage meter: numbers on your frames, a race bar in fights, a summary after, and a fight history. Replaces the game's meter."] = "Счётчик урона MelloUI: числа на ваших рамках, полоса гонки в бою, итог после него и история боёв. Заменяет счётчик игры.", -- draft
	["How the fight went, where you already look."] = "Как прошёл бой, там, куда вы и так смотрите.", -- draft
	["Your Values"] = "Ваши значения", -- draft
	["Your damage per second, run total and healing per second beside your player frame."] = "Ваш урон в секунду, итог похода и исцеление в секунду рядом с вашей рамкой игрока.", -- draft
	["Party Values"] = "Значения группы", -- draft
	["The same numbers beside each party frame, and beside your own when it shows in your party."] = "Те же числа рядом с каждой рамкой группы и рядом с вашей, когда она показана в группе.", -- draft
	["On Raid-Style Frames"] = "На рамках в стиле рейда", -- draft
	["A damage or healing number on each raid-style frame. Point at a frame for all three."] = "Число урона или исцеления на каждой рамке в стиле рейда. Наведите на рамку, чтобы увидеть все три.", -- draft
	["Race Bar"] = "Полоса гонки", -- draft
	["In a fight, a race bar of your group's damage, with you highlighted. Point at it for everyone's numbers."] = "В бою — полоса гонки урона группы, вы выделены. Наведите, чтобы увидеть числа всех.", -- draft
	["Race Bar Shows"] = "Полоса гонки показывает", -- draft
	["What the race bar compares. Auto: healing as a healer, damage otherwise."] = "Что сравнивает полоса гонки. Авто: исцеление у лекаря, иначе урон.", -- draft
	["Auto"] = "Авто", -- draft
	["Damage"] = "Урон", -- draft
	["Healing"] = "Исцеление", -- draft
	["Race Bar Pins"] = "Метки полосы гонки", -- draft
	["How many players the race bar shows. You are always on it."] = "Сколько игроков на полосе гонки. Вы на ней всегда.", -- draft
	["Race Bar Width"] = "Ширина полосы гонки", -- draft
	["How wide the race bar is."] = "Ширина полосы гонки.", -- draft
	["Race Bar Thickness"] = "Толщина полосы гонки", -- draft
	["How thick the race bar's line is."] = "Толщина линии полосы гонки.", -- draft
	["Fight Summary"] = "Итог боя", -- draft
	["After a fight, a short summary in the widget column: your damage, DPS and rank. Click it for the full fight."] = "После боя — краткий итог в колонке виджетов: ваш урон, DPS и место. Щелчок показывает весь бой.", -- draft
	["Fight History"] = "История боёв", -- draft
	["A window with every fight of this session: damage, healing and your spells. Opens from the chat's buttons."] = "Окно со всеми боями этой сессии: урон, исцеление и ваши заклинания. Открывается кнопками чата.", -- draft
	["Fights Kept"] = "Хранить боёв", -- draft
	["How many fights the history keeps. It starts empty at each login."] = "Сколько боёв хранит история. При каждом входе начинается пустой.", -- draft
	-- SwingTimers
	["Swing Timers"] = "Таймеры удара", -- draft
	["Your swing timer as a badge on your target's nameplate. Replaces the game's swing timers."] = "Таймер ударов в виде значка на индикаторе здоровья цели. Заменяет таймеры ударов игры.", -- draft
	["Every swing and shot at a glance."] = "Каждый удар и выстрел с одного взгляда.", -- draft
	["Shots"] = "Выстрелы", -- draft
	["Your Auto Shot on the swing badge: reload, then aim."] = "Ваш «Автоматический выстрел» на значке ударов: перезарядка, затем прицеливание.", -- draft
	["Melee Swings"] = "Удары ближнего боя", -- draft
	["Your main hand's swings on the swing badge. Wand shots too."] = "Удары правой руки на значке ударов. И выстрелы жезлом.", -- draft
	["Off Hand"] = "Левая рука", -- draft
	["Your off hand's swings on a smaller badge."] = "Удары левой руки на значке поменьше.", -- draft
	-- PartyMarkers
	["Party Markers"] = "Метки группы", -- draft
	["A class medallion over your party members' nameplates, ringed in their role's colour. Open world only."] = "Медальон класса над индикаторами здоровья членов группы, с кольцом цвета их роли. Только в открытом мире.", -- draft
	["A class medallion over every party member's head, ringed in their role's colour: the healer, found at a glance."] = "Медальон класса над головой каждого участника группы, в кольце цвета его роли: лекаря видно с одного взгляда.", -- draft
	["Markers"] = "Метки", -- draft
	["Mark"] = "Отмечать", -- draft
	["Whose nameplate gets a class medallion."] = "Чей индикатор здоровья получает медальон класса.", -- draft
	["Party and raid members"] = "Участники группы и рейда", -- draft
	["Every friendly player"] = "Все дружественные игроки", -- draft
