	["Ore Veins"] = "Рудные жилы", -- draft
	["Golden glints over the nearest ore vein: bright when you can mine it, grey when your skill is too low."] = "Золотые отблески над ближайшей жилой: яркие, если можно добыть, серые, если навыка мало.", -- draft
