	["Every click, page, pouch and latch of the interface, re-recorded: light and clean for Modern, iron and leather for Oldschool."] = "Каждый щелчок, страница, кошель и защёлка интерфейса записаны заново: лёгкие и чистые для «Современного», железо и кожа для Oldschool.", -- draft
