	["In group fights, a thin line on an enemy's bar showing how close it is to turning on you. For tanks, it turns red when you lose a mob."] = "В групповом бою тонкая линия на полосе противника показывает, насколько он близок к тому, чтобы переключиться на вас. Для танков она краснеет, когда вы теряете противника.", -- draft
	["Combo Points"] = "Приёмы серии", -- draft
