	-- PlateImpact
	["Impact Effects"] = "Эффекты попаданий", -- draft
	["Your target's nameplate reacts to the fight: hits flash, crits glow, interrupted casts shatter."] = "Индикатор здоровья цели реагирует на бой: попадания вспыхивают, криты светятся, прерванные заклинания разлетаются.", -- draft
	["Every hit lands on the plate, not only in a number."] = "Каждый удар попадает в индикатор, а не только в число.", -- draft
	["Hit Flash"] = "Вспышка удара", -- draft
	["Your target's bar flashes when it is hit; gold for a critical hit."] = "Полоса цели вспыхивает при попадании; золотом — при крите.", -- draft
	["Damage Chunk"] = "Кусок урона", -- draft
	["The part of the bar a hit took stays lit for a moment before it drains, so you see each hit's size."] = "Часть полосы, отнятая ударом, светится миг перед тем, как уйти, — видно размер каждого удара.", -- draft
	["Crit Glow"] = "Сияние крита", -- draft
	["A gold glow bursts around your target's bar on a critical hit."] = "При крите вокруг полосы цели вспыхивает золотое свечение.", -- draft
	["Kill Flash"] = "Вспышка убийства", -- draft
	["A killing blow flashes the bar out instead of the plate just vanishing."] = "Смертельный удар гасит полосу вспышкой, а не просто убирает индикатор.", -- draft
	["Dodge And Miss"] = "Уклонение и промах", -- draft
	["Dodge, parry and miss words flick off the side of your target's plate."] = "Уклонение, парирование и промах отлетают от края индикатора цели.", -- draft
	["Cast Warning"] = "Предупреждение о заклинании", -- draft
