	["Anchor"] = "Привязка", -- draft
	["Where tooltips appear."] = "Где появляются подсказки.", -- draft
	["Default (Edit Mode position)"] = "По умолчанию", -- draft
	["At the cursor"] = "У курсора", -- draft
	["Right of the cursor"] = "Справа от курсора", -- draft
	["Scale"] = "Масштаб", -- draft
	["The size of tooltips."] = "Размер подсказок.", -- draft
	-- UnitFrames
	["Centred names, a clear name band and no combat flash for player, target and focus; the party's levels and the names' soft bands."] = "Имена по центру, чёткая полоса имени и без вспышки боя для игрока, цели и фокуса; уровни группы и мягкие полосы имён.", -- draft
	["Player, target and focus, centred and calm."] = "Игрок, цель и фокус — по центру и спокойно.", -- draft
	["MelloUI Frames"] = "Рамки MelloUI", -- draft
	["The unit frames in MelloUI's look: a gold portrait ring, a level badge and gold-lined borders. Off: the game's own art."] = "Рамки юнитов в стиле MelloUI: золотое кольцо портрета, значок уровня и рамки с золотой каймой. Выкл.: графика игры.", -- draft
	["Flip Horizontally"] = "Отразить по горизонтали", -- draft
	["Mirrors the party frames for a party on the right of the screen: portraits on the right."] = "Отражает рамки группы для группы справа на экране: портреты справа.", -- draft
	["Names"] = "Имена", -- draft
	["Name Font"] = "Шрифт имён", -- draft
	["The font of names on the unit frames and party portraits. Shared: the interface font."] = "Шрифт имён на рамках юнитов и портретах группы. Общая: шрифт интерфейса.", -- draft
	["Glows"] = "Свечения", -- draft
	["Hide Combat Flash"] = "Скрыть вспышку боя", -- draft
	["Hides the threat glow on the unit frames. Off: a soft halo round each frame's own shape while it has threat, amber when close to pulling, red while holding the enemy."] = "Скрывает свечение угрозы на рамках юнитов. Выкл.: мягкий ореол по форме каждой рамки, пока у неё есть угроза, янтарный перед агро, красный, пока она держит противника.", -- draft
	["Hide Status Glow"] = "Скрыть свечение состояния", -- draft
	["Hides the resting and combat glow around your portrait, and your pet's attack glow."] = "Скрывает свечение отдыха и боя вокруг портрета и свечение атаки питомца.", -- draft
	["Hide PvP Badge"] = "Скрыть значок PvP", -- draft
	["Hides the PvP badge beside the portraits."] = "Скрывает значок PvP рядом с портретами.", -- draft
	["Hide Heal Numbers"] = "Скрыть числа исцеления", -- draft
	["Your portrait no longer shows the green numbers of the heals you take. Damage, misses and mana gains still show."] = "Ваш портрет больше не показывает зелёные числа получаемого исцеления. Урон, промахи и восполнение маны по-прежнему видны.", -- draft
	["Frame Art"] = "Оформление рамок", -- draft
	-- Fader
	["Fader"] = "Угасание", -- draft
	["Fades parts of the interface while you don't need them: out of combat, or until you point at them."] = "Скрывает части интерфейса, пока они не нужны: вне боя или пока вы на них не наведёте.", -- draft
	["Your interface, only when you need it."] = "Ваш интерфейс, только когда он нужен.", -- draft
	["Fade Everything"] = "Гасить всё", -- draft
	["Sets every part below to In Combat: the interface fades out of combat and comes back in a fight."] = "Ставит каждую часть ниже на «В бою»: интерфейс тускнеет вне боя и возвращается в бою.", -- draft
	["Fade"] = "Гасить", -- draft
	["Fade Nothing"] = "Не гасить ничего", -- draft
	["Sets every part below to Always: nothing fades."] = "Ставит каждую часть ниже на «Всегда»: ничего не тускнеет.", -- draft
	["Reset"] = "Сброс", -- draft
	["Faded Opacity"] = "Непрозрачность при угасании", -- draft
	["How visible a faded part stays. 0%: hidden until needed."] = "Насколько видна потускневшая часть. 0%: скрыта, пока не понадобится.", -- draft
	["Fade After"] = "Гасить через", -- draft
	["How long a part waits before fading, after a fight or after your mouse leaves."] = "Сколько часть ждёт перед затуханием после боя или ухода мыши.", -- draft
	["Fade Speed"] = "Скорость угасания", -- draft
	["How long the fade takes. Coming back is always quick."] = "Сколько длится затухание. Возвращение всегда быстрое.", -- draft
	["Show With A Target"] = "Показывать при цели", -- draft
	["In Combat parts also come back while you have a target."] = "Части «В бою» возвращаются и пока у вас есть цель.", -- draft
	["Also Show On Mouseover"] = "Показывать и при наведении", -- draft
	["In Combat parts also come back while your mouse is over them."] = "Части «В бою» возвращаются и пока на них наведена мышь.", -- draft
	["Your own frame. In Combat, it also returns while you are hurt, low on mana or dead. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Ваша рамка. В бою она возвращается и пока вы ранены, мало маны или вы мертвы. Всегда: не тускнеет. В бою: тускнеет вне боя. При наведении: тускнеет, пока не наведёте.", -- draft
	["Pet Frame Too"] = "И рамка питомца", -- draft
	["Your pet's frame fades with the player frame and returns while your pet is hurt."] = "Рамка питомца тускнеет вместе с рамкой игрока и возвращается, пока питомец ранен.", -- draft
	["Your target's frame and its target. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Рамка цели и её цели. Всегда: не тускнеет. В бою: тускнеет вне боя. При наведении: тускнеет, пока не наведёте.", -- draft
	["Your focus's frame. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Рамка фокуса. Всегда: не тускнеет. В бою: тускнеет вне боя. При наведении: тускнеет, пока не наведёте.", -- draft
	["Party Frames"] = "Рамки группы", -- draft
	["The party frames. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Рамки группы. Всегда: не тускнеют. В бою: тускнеют вне боя. При наведении: тускнеют, пока не наведёте.", -- draft
	["The raid frames. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Рамки рейда. Всегда: не тускнеют. В бою: тускнеют вне боя. При наведении: тускнеют, пока не наведёте.", -- draft
	["Your buffs and debuffs. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Ваши эффекты. Всегда: не тускнеют. В бою: тускнеют вне боя. При наведении: тускнеют, пока не наведёте.", -- draft
	["The reminder buttons beside your portrait. A new reminder doesn't bring them back. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Кнопки напоминаний у портрета. Новое напоминание их не возвращает. Всегда: не тускнеют. В бою: тускнеют вне боя. При наведении: тускнеют, пока не наведёте.", -- draft
	["The Personal Display's bars. In Combat, they also return while you cast. Always: never faded. In Combat: faded out of combat."] = "Полосы Личной панели. В бою они возвращаются и пока вы произносите заклинание. Всегда: не тускнеют. В бою: тускнеют вне боя.", -- draft
	["Main Action Bar"] = "Главная панель команд", -- draft
	["The main action bar. Its keys still work while faded. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Главная панель команд. Её клавиши работают и когда она потускнела. Всегда: не тускнеет. В бою: тускнеет вне боя. При наведении: тускнеет, пока не наведёте.", -- draft
	["Its keys still work while faded. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Её клавиши работают и когда она потускнела. Всегда: не тускнеет. В бою: тускнеет вне боя. При наведении: тускнеет, пока не наведёте.", -- draft
	["Stance & Pet Bar"] = "Панель стоек и питомца", -- draft
	["The stance, form and pet bars. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Панели стоек, обликов и питомца. Всегда: не тускнеют. В бою: тускнеют вне боя. При наведении: тускнеют, пока не наведёте.", -- draft
	["Micro Menu"] = "Микроменю", -- draft
	["The micro menu. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Микроменю. Всегда: не тускнеет. В бою: тускнеет вне боя. При наведении: тускнеет, пока не наведёте.", -- draft
	["Bag Bar"] = "Панель сумок", -- draft
	["The bag bar. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Панель сумок. Всегда: не тускнеет. В бою: тускнеет вне боя. При наведении: тускнеет, пока не наведёте.", -- draft
	["The experience and reputation bars. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Полосы опыта и репутации. Всегда: не тускнеют. В бою: тускнеют вне боя. При наведении: тускнеют, пока не наведёте.", -- draft
	["The chat windows, tabs and buttons. They return while you type. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Окна чата, вкладки и кнопки. Они возвращаются, пока вы печатаете. Всегда: не тускнеют. В бою: тускнеют вне боя. При наведении: тускнеют, пока не наведёте.", -- draft
	["The minimap and the Services bar. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Мини-карта и панель Услуг. Всегда: не тускнеют. В бою: тускнеют вне боя. При наведении: тускнеют, пока не наведёте.", -- draft
	["Quest Tracker"] = "Отслеживание заданий", -- draft
	["MelloUI's Quest Tracker. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Отслеживание заданий MelloUI. Всегда: не тускнеет. В бою: тускнеет вне боя. При наведении: тускнеет, пока не наведёте.", -- draft
	["Objective Tracker"] = "Отслеживание задач", -- draft
	["The game's objective tracker. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Отслеживание задач игры. Всегда: не тускнеет. В бою: тускнеет вне боя. При наведении: тускнеет, пока не наведёте.", -- draft
	["Widget Column"] = "Колонка виджетов", -- draft
	["The widget column. A new widget doesn't bring it back. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Колонка виджетов. Новый виджет её не возвращает. Всегда: не тускнеет. В бою: тускнеет вне боя. При наведении: тускнеет, пока не наведёте.", -- draft
	["World Marker"] = "Мировой маркер", -- draft
	["Route's World Marker. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Маркер мира Route. Всегда: не тускнеет. В бою: тускнеет вне боя. При наведении: тускнеет, пока не наведёте.", -- draft
	["The FPS and latency readout. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Показатель FPS и задержки. Всегда: не тускнеет. В бою: тускнеет вне боя. При наведении: тускнеет, пока не наведёте.", -- draft
	-- QuestAuto
	["Auto Accept & Hand In"] = "Автопринятие и сдача", -- draft
	["Accepts quests and hands them in as you talk to their givers, off until you switch it on."] = "Принимает задания и сдаёт их, когда вы говорите с теми, кто их даёт; выключено, пока вы не включите.", -- draft
	["Talk, and the quest is yours. Hold Shift to read it first."] = "Поговорите — и задание ваше. Удерживайте Shift, чтобы сначала прочитать.", -- draft
	["Auto Accept Quests"] = "Автопринятие заданий", -- draft
	["Accepts quests as soon as a giver offers them. Repeatable, daily and shared quests are left to you."] = "Принимает задания, как только их предлагают. Повторяемые, ежедневные и общие задания остаются вам.", -- draft
	["Auto Hand In"] = "Автосдача", -- draft
	["Hands in finished quests as soon as you talk to the NPC. A choice of rewards waits for you."] = "Сдаёт выполненные задания, как только вы заговорите с НИП. Выбор награды ждёт вас.", -- draft
	["Take The Upgrade"] = "Брать улучшение", -- draft
	["With a choice of rewards, takes the best upgrade you can use, or the one that sells for the most."] = "При выборе награды берёт лучшее улучшение, которое вы можете использовать, или самое дорогое.", -- draft
	["Skip Key"] = "Клавиша пропуска", -- draft
	["Hold this key while talking to an NPC to stop the automatic accept and hand-in."] = "Удерживайте эту клавишу при разговоре с НИП, чтобы не принимать и не сдавать автоматически.", -- draft
	["Shift"] = "Shift", -- draft
	["Ctrl"] = "Ctrl", -- draft
	["Alt"] = "Alt", -- draft
	-- HealerFrames
	["Healer Frames"] = "Рамки лекаря", -- draft
	["Incoming heals on the unit frames, and a glow in a debuff's colour round any frame whose unit has a debuff to remove."] = "Входящее исцеление на рамках и свечение цвета отрицательного эффекта вокруг любой рамки, у чьего юнита есть эффект, который нужно снять.", -- draft
	["See the heals coming in, and who needs a cleanse."] = "Видите, как идёт исцеление и кому нужно очищение.", -- draft
	["Incoming Heals"] = "Входящее исцеление", -- draft
	["Incoming heals and shields shown on the player, target and focus health bars."] = "Входящее исцеление и щиты на полосах здоровья игрока, цели и фокуса.", -- draft
	["Debuff Glow"] = "Свечение отрицательного эффекта", -- draft
	["A glow in the debuff's colour around a friend's frame while they have a debuff that can be removed."] = "Свечение цвета эффекта вокруг рамки союзника, пока на нём снимаемый отрицательный эффект.", -- draft
	["Debuff Glow Shows"] = "Свечение показывает", -- draft
	["Which debuffs light a frame: any that can be removed, the ones your group can remove, or only yours."] = "Какие эффекты подсвечивают рамку: любые снимаемые, снимаемые вашей группой или только вами.", -- draft
	["Every Dispellable Debuff"] = "Все рассеиваемые эффекты", -- draft
	["Ones The Group Can Dispel"] = "Рассеиваемые группой", -- draft
	["Ones I Can Dispel"] = "Рассеиваемые мной", -- draft
	-- ActionBars
	["The backdrops round the action bars, the micro menu, the bag bar and the experience bars, and the main bar's page arrows and bar art hidden, whatever their look."] = "Подложки вокруг панелей команд, микроменю, панели сумок и индикаторов опыта, а также скрытые стрелки страниц и оформление главной панели, каким бы ни был их облик.", -- draft
	["The experience and reputation bars in MelloUI's look. Off: the game's own frame."] = "Полосы опыта и репутации в стиле MelloUI. Выкл.: рамка игры.", -- draft
	["Hide Page Arrows"] = "Скрыть стрелки страниц", -- draft
	["Hides the main bar's page number and arrows. Paging keys still work."] = "Скрывает номер страницы и стрелки главной панели. Клавиши страниц работают.", -- draft
	["Hide Bar Art"] = "Скрыть оформление панели", -- draft
	["Hides the main bar's art, like the other bars. With UI Modifications off: only on your own Edit Mode layouts, after a /reload."] = "Скрывает оформление главной панели, как у остальных. Без изменений интерфейса: только в ваших собственных раскладках режима редактирования, после /reload.", -- draft
	["A backdrop around Action Bar 1. Neighbours with a backdrop share one."] = "Подложка вокруг панели команд 1. Соседи с подложкой делят одну.", -- draft
	["A backdrop around Action Bar 2. Neighbours with a backdrop share one."] = "Подложка вокруг панели команд 2. Соседи с подложкой делят одну.", -- draft
	["A backdrop around Action Bar 3. Neighbours with a backdrop share one."] = "Подложка вокруг панели команд 3. Соседи с подложкой делят одну.", -- draft
	["A backdrop around Action Bar 4. Neighbours with a backdrop share one."] = "Подложка вокруг панели команд 4. Соседи с подложкой делят одну.", -- draft
	["A backdrop around Action Bar 5. Neighbours with a backdrop share one."] = "Подложка вокруг панели команд 5. Соседи с подложкой делят одну.", -- draft
	["A backdrop around Action Bar 6. Neighbours with a backdrop share one."] = "Подложка вокруг панели команд 6. Соседи с подложкой делят одну.", -- draft
	["A backdrop around Action Bar 7. Neighbours with a backdrop share one."] = "Подложка вокруг панели команд 7. Соседи с подложкой делят одну.", -- draft
	["A backdrop around Action Bar 8. Neighbours with a backdrop share one."] = "Подложка вокруг панели команд 8. Соседи с подложкой делят одну.", -- draft
	["A backdrop around the stance bar. Neighbours with a backdrop share one."] = "Подложка вокруг панели стоек. Соседи с подложкой делят одну.", -- draft
	["A backdrop around the pet bar. Neighbours with a backdrop share one."] = "Подложка вокруг панели питомца. Соседи с подложкой делят одну.", -- draft
	["Possess Bar"] = "Панель контроля разума", -- draft
	["A backdrop around the possess bar. Neighbours with a backdrop share one."] = "Подложка вокруг панели подчинения. Соседи с подложкой делят одну.", -- draft
	["Totem Bar"] = "Панель тотемов", -- draft
	["A backdrop around the totem bar. Neighbours with a backdrop share one."] = "Подложка вокруг панели тотемов. Соседи с подложкой делят одну.", -- draft
	["A backdrop around the micro menu. Neighbours with a backdrop share one."] = "Подложка вокруг микроменю. Соседи с подложкой делят одну.", -- draft
	["A backdrop around the bag bar. Neighbours with a backdrop share one."] = "Подложка вокруг панели сумок. Соседи с подложкой делят одну.", -- draft
	["Experience Bar"] = "Индикатор опыта", -- draft
	["A backdrop around the experience bar (the reputation bar in its place at the top level). Neighbours with a backdrop share one."] = "Подложка вокруг полосы опыта (на максимальном уровне на её месте полоса репутации). Соседи с подложкой делят одну.", -- draft
	["Reputation Bar"] = "Индикатор репутации", -- draft
	["A backdrop around the second status bar (a watched reputation while you level). Neighbours with a backdrop share one."] = "Подложка вокруг второй полосы состояния (отслеживаемая репутация во время прокачки). Соседи с подложкой делят одну.", -- draft
	-- ActionButtons
	["Action Buttons"] = "Кнопки действий", -- draft
	["Lights an action button while its key is held, and colours its icon by range and resources."] = "Подсвечивает кнопку действия, пока зажата её клавиша, и окрашивает значок по дальности и ресурсам.", -- draft
	["See which button you press, and which spell cannot reach its target."] = "Видно, какую кнопку вы нажимаете и какое заклинание не достаёт до цели.", -- draft
	["Action buttons in MelloUI's frame: gold when active, red out of range. Off: the game's own frames."] = "Кнопки команд в рамке MelloUI: золотые, когда активны, красные вне досягаемости. Выкл.: рамки игры.", -- draft
	["Cooldown Ready Flash"] = "Вспышка готовности", -- draft
	["A gold light runs around a button when its cooldown ends."] = "Золотой свет обегает кнопку, когда её восстановление заканчивается.", -- draft
	["Light While Pressed"] = "Свет при нажатии", -- draft
	["A button lights up while you press it."] = "Кнопка светится, пока вы её нажимаете.", -- draft
	["Range And Resource Colours"] = "Цвета дальности и ресурса", -- draft
	["Icons turn red out of range, blue without enough mana, and grey when unusable."] = "Значки краснеют вне досягаемости, синеют без маны и сереют, когда недоступны.", -- draft
	-- CooldownTweaks
	["Cooldown Manager Tweaks"] = "Доработки менеджера восстановления", -- draft
	["Centred rows, key bindings, a light while pressed and the count size on the game's Cooldown Manager."] = "Ряды по центру, назначения клавиш, свет при нажатии и размер чисел в менеджере восстановления игры.", -- draft
	["Your cooldowns, in the middle, with their keys on them."] = "Ваши способности посередине, с клавишами на них.", -- draft
	["Centre Rows"] = "Ряды по центру", -- draft
	["A shorter row of cooldown icons sits centred under the others."] = "Короткий ряд значков восстановления стоит по центру под остальными.", -- draft
	["Key Bindings"] = "Назначение клавиш", -- draft
	["The key bound to a cooldown's spell, on the icon's corner."] = "Клавиша заклинания восстановления в углу значка.", -- draft
	["A cooldown's icon lights up while you press its action button."] = "Значок восстановления светится, пока вы нажимаете его кнопку команды.", -- draft
	["Count Size"] = "Размер чисел", -- draft
	["The size of the charges and stacks numbers on the icons."] = "Размер чисел зарядов и стаков на значках.", -- draft
	-- BagWindow
	["Bags by Kind"] = "Сумки по видам", -- draft
	["Your bags in one window, sorted by kind: new items, gear, quest items, consumables, junk and more."] = "Сумки в одном окне, по видам: новые предметы, снаряжение, предметы заданий, расходники, хлам и другое.", -- draft
	["A place for everything, and everything under its heading."] = "Всему своё место, и всё под своим заголовком.", -- draft
	["Kinds"] = "Виды", -- draft
	["The kinds your bag window sorts items into, top first. Drag to reorder, untick to hide, Add kind to make your own; double-click a name to rename it, its cog opens its settings."] = "Виды, по которым окно сумок сортирует предметы, сверху вниз. Перетаскивайте для порядка, снимите флажок, чтобы скрыть, «Добавить вид» — для своих; двойной щелчок по названию переименовывает, шестерёнка открывает настройки.", -- draft
	["Items You Placed"] = "Размещённые вами предметы", -- draft
	["While you hold an item, drop it on a kind's + to always sort it there. Forget puts every placed item back."] = "Держа предмет, бросьте его на «+» вида, чтобы он всегда попадал туда. «Забыть» возвращает все размещённые предметы.", -- draft
	["Forget"] = "Забыть", -- draft
	["Bank by Kind"] = "Банк по видам", -- draft
	["Your bank sorted by the same kinds as your bags. Off: the game's grid."] = "Банк по тем же видам, что и сумки. Выкл.: сетка игры.", -- draft
	["Recent Lasts"] = "Срок «Недавнего»", -- draft
	["How long new items stay under Recent: until you close your bags, until you point at them, or 5 minutes."] = "Сколько новые предметы остаются в «Недавних»: до закрытия сумок, пока не наведёте, или 5 минут.", -- draft
	["Until The Bags Close"] = "Пока сумки не закрыты", -- draft
	["Until Hovered"] = "Пока не наведёте", -- draft
	["For 5 Minutes"] = "5 минут", -- draft
	["Columns"] = "Столбцы", -- draft
	["How many slots wide the bag window is."] = "Сколько ячеек в ширину окно сумок.", -- draft
	["Item Size"] = "Размер предметов", -- draft
	["The size of the item slots. 37 is the game's size."] = "Размер ячеек предметов. 37 — размер игры.", -- draft
	["Fold Empty Slots"] = "Сворачивать пустые ячейки", -- draft
	["All empty slots shown as one, with their count."] = "Все пустые ячейки показаны одной, с числом.", -- draft
	["Sort Items By"] = "Сортировать предметы по", -- draft
	["How items are ordered inside each kind."] = "Как упорядочены предметы внутри вида.", -- draft
	["Quality"] = "Качество", -- draft
	["Name"] = "Название", -- draft
	["Newest First"] = "Сначала новые", -- draft
	["Item Level"] = "Уровень предмета", -- draft
	["Loot Flight"] = "Полёт добычи", -- draft
	["Looted items fly into your bag window; the rarer the item, the bigger the effect."] = "Добытые предметы влетают в окно сумок; чем реже предмет, тем ярче эффект.", -- draft
	["Items Glide"] = "Плавное перемещение", -- draft
	["Items glide to their new slots instead of jumping."] = "Предметы скользят на новые места, а не прыгают.", -- draft
	["Rolling Money"] = "Бегущие деньги", -- draft
	["Your money counts up or down to its new amount."] = "Деньги отсчитываются до новой суммы вверх или вниз.", -- draft
	["Bags Full Warning"] = "Предупреждение о полных сумках", -- draft
	["The bag window shakes and flashes red when your bags are full."] = "Окно сумок вздрагивает и вспыхивает красным, когда сумки полны.", -- draft
	-- MinimapPanel
	["MelloUI's minimap: its size, square shape and the Services bar under it. Off: the game's own minimap."] = "Мини-карта MelloUI: размер, квадратная форма и панель Услуг под ней. Выкл.: мини-карта игры.", -- draft
	["Shape"] = "Форма", -- draft
	["The painted minimap's shape: round in its ring, or square in the Square Border."] = "Форма рисованной мини-карты: круглая в своём кольце или квадратная в квадратной кайме.", -- draft
	["Round"] = "Круглая", -- draft
	["Square"] = "Квадратная", -- draft
	["Square Border"] = "Квадратная рамка", -- draft
	["The border around the square minimap. Painted borders need Oldschool's painted Minimap."] = "Кайма квадратной мини-карты. Рисованным каймам нужна рисованная мини-карта Oldschool.", -- draft
	["Window frame"] = "Рамка окна", -- draft
	["Chat panel"] = "Панель чата", -- draft
	["Heavy, red gems"] = "Тяжёлая, красные самоцветы", -- draft
	["Heavy, iron gems"] = "Тяжёлая, железные самоцветы", -- draft
	["Merge With Services"] = "Слить с услугами", -- draft
	["The square minimap, its zone name and the Services bar share one frame."] = "Квадратная мини-карта, её название зоны и панель Услуг в одной рамке.", -- draft
	["Width"] = "Ширина", -- draft
	["How wide the minimap is. The Quest Tracker under it follows its width."] = "Ширина мини-карты. Отслеживание заданий под ней следует её ширине.", -- draft
	["Height"] = "Высота", -- draft
	["How tall the square minimap is."] = "Высота квадратной мини-карты.", -- draft
	-- QuestTracker
	["MelloUI's quest tracker in the game's tracker's place. It scrolls, so every quest fits."] = "Отслеживание заданий MelloUI на месте игрового. Оно прокручивается, чтобы поместилось любое задание.", -- draft
	["Every watched quest within reach: the tracker scrolls when the list runs long."] = "Каждое отслеживаемое задание в досягаемости: отслеживание прокручивается, когда список становится длинным.", -- draft
	["Tracker"] = "Отслеживание", -- draft
	["How tall the tracker grows before it scrolls. You can also drag its corner."] = "До какой высоты растёт отслеживание, прежде чем прокручиваться. Можно и тянуть за угол.", -- draft
	["Match The Minimap's Width"] = "По ширине мини-карты", -- draft
	["The tracker is as wide as the minimap and sits right under it, following it. Off: use Width below."] = "Отслеживание шириной с мини-карту, прямо под ней и следует за ней. Выкл.: используйте «Ширина» ниже.", -- draft
	["How wide the tracker is when it doesn't match the minimap. You can also drag its corner."] = "Ширина отслеживания, когда оно не равняется мини-карте. Можно и тянуть за угол.", -- draft
	["The size of quest titles and section headers. Objectives are one size smaller."] = "Размер названий заданий и заголовков разделов. Задачи на размер меньше.", -- draft
	["Header Text Size"] = "Размер текста заголовка", -- draft
	["The size of the tracker's title."] = "Размер заголовка отслеживания.", -- draft
	["Background Opacity"] = "Непрозрачность фона", -- draft
	["How solid the tracker's background is. At 0% its lines stand on the world, as the game's tracker's do."] = "Насколько плотный фон у отслеживания заданий. При 0% его строки лежат прямо на мире, как у отслеживания игры.", -- draft
	["Scroll Step"] = "Шаг прокрутки", -- draft
	["How far one turn of the mouse wheel scrolls."] = "Насколько прокручивает один щелчок колёсика мыши.", -- draft
	["A quest's usable item beside it. Click to use it out of combat."] = "Используемый предмет задания рядом с ним. Щелчок использует его вне боя.", -- draft
	["Progress Motion"] = "Анимация хода", -- draft
	["Counts roll to their new number, finished objectives get a tick, and a finished quest lights up."] = "Счётчики прокручиваются к новому числу, выполненные задачи получают галочку, выполненное задание вспыхивает.", -- draft
	["Nearest First"] = "Сначала ближайшие", -- draft
	["Nearest Quest First"] = "Ближайшее задание первым", -- draft
	["The nearest quest on top, after the one you follow. Needs Route."] = "Ближайшее задание сверху, после того, за которым вы следуете. Нужен Route.", -- draft
	["Distances"] = "Расстояния", -- draft
	["How far each quest is, beside its name. Needs Route."] = "Расстояние до каждого задания рядом с названием. Нужен Route.", -- draft
	["Turn-in Line"] = "Строка сдачи", -- draft
	["A finished quest says who takes it and where."] = "Выполненное задание показывает, кто его принимает и где.", -- draft
	["Reset Position"] = "Сброс позиции", -- draft
	["Puts the tracker back in its starting place."] = "Возвращает отслеживание на исходное место.", -- draft
	["back under the minimap (or on the game's tracker's place)"] = "обратно под мини-карту (или на место отслеживания игры)", -- draft
	-- ErrorFilter
	["Hide the red error messages you choose, such as \"Not enough energy\" or \"Spell is not ready yet\", from the middle of the screen."] = "Скрывает из центра экрана выбранные вами красные сообщения об ошибках, например «Недостаточно энергии» или «Заклинание пока недоступно.».", -- draft
	["Quiet, please. The red shouts in the middle of the screen, a kind at a time."] = "Потише, пожалуйста. Красные крики в центре экрана, по одному виду за раз.", -- draft
	["Hide"] = "Скрыть", -- draft
	["Not Enough Resources"] = "Не хватает ресурса", -- draft
	["Not enough energy, rage, mana or combo points."] = "Не хватает энергии, ярости, маны или приёмов серии.", -- draft
	["Not Ready Yet"] = "Ещё не готово", -- draft
	["An ability, spell or item is not ready yet."] = "Способность, заклинание или предмет ещё не готовы.", -- draft
	["Out Of Range"] = "Вне досягаемости", -- draft
	["Out of range, too far or too close."] = "Вне досягаемости, слишком далеко или слишком близко.", -- draft
	["Facing And Target"] = "Направление и цель", -- draft
	["Wrong facing, no target, invalid target or out of sight."] = "Неверное направление, нет цели, неверная цель или вне поля зрения.", -- draft
	["Busy Or Moving"] = "Заняты или в движении", -- draft
	["Busy, moving, stunned or mounted."] = "Заняты, движетесь, оглушены или верхом.", -- draft
	-- Auras
	["Your own buff and debuff rows on the target frame, enemy nameplates and at your buffs, drawn by the game so they keep working in combat."] = "Собственные ряды положительных и отрицательных эффектов на рамке цели, индикаторах здоровья врагов и у ваших эффектов, нарисованные игрой, чтобы работать и в бою.", -- draft
	["Buffs and debuffs in rows of your own, drawn by the game itself, so they never go dark in a fight."] = "Положительные и отрицательные эффекты в своих рядах, нарисованных самой игрой, так что в бою они никогда не гаснут.", -- draft
	["MelloUI's own rows of buffs and debuffs: yours in place of the game's buff bar, the target's under its frame, your debuffs on enemy nameplates."] = "Собственные ряды эффектов MelloUI: ваши вместо панели эффектов игры, цели — под её рамкой, ваши отрицательные эффекты — на индикаторах здоровья врагов.", -- draft
	["Your Buffs And Debuffs"] = "Ваши положительные и отрицательные эффекты", -- draft
	["MelloUI's rows for your buffs and debuffs, beside the minimap or where the game's buff bar is. Right-click a buff to cancel it."] = "Ряды MelloUI для ваших эффектов — у мини-карты или на месте игровой панели. Правый щелчок по эффекту отменяет его.", -- draft
	["Attach To The Minimap Column"] = "Прикрепить к колонке мини-карты", -- draft
	["Your buffs line up beside the minimap and follow it. Off: they stand where the game's buff bar is."] = "Эффекты выстраиваются у мини-карты и следуют за ней. Выкл.: стоят на месте игровой панели.", -- draft
	["Attach To The Player Frame"] = "Прикрепить к рамке игрока", -- draft
	["Your buffs and debuffs under your player frame, like the target's. They move with the frame."] = "Ваши эффекты под рамкой игрока, как у цели. Двигаются вместе с рамкой.", -- draft
	["Direction"] = "Направление", -- draft
	["Which way your icons run under the player frame."] = "В какую сторону идут значки под рамкой игрока.", -- draft
	["Left To Right"] = "Слева направо", -- draft
	["Right To Left"] = "Справа налево", -- draft
	["Icon Size On The Frame"] = "Размер значков на рамке", -- draft
	["The size of your buff and debuff icons under the player frame."] = "Размер значков эффектов под рамкой игрока.", -- draft
	["Target"] = "Цель", -- draft
	["Your target's debuffs and buffs under the target frame, in MelloUI's look."] = "Отрицательные и положительные эффекты цели под её рамкой, в стиле MelloUI.", -- draft
	["The size of your target's buff and debuff icons."] = "Размер значков эффектов цели.", -- draft
	["Only My Debuffs"] = "Только мои эффекты", -- draft
	["Only the debuffs you put on your target."] = "Только эффекты, наложенные вами на цель.", -- draft
	["Enemy Nameplates"] = "Индикаторы здоровья врагов", -- draft
