	["A quest log page listing a zone's quests, your progress and where each one starts, with quest givers on the map."] = "Страница журнала заданий со списком заданий зоны, вашим прогрессом и местом начала каждого, с дающими задания на карте.", -- draft
	["Every quest of the zone in the map's quest log: who gives it, where, and what is left to do."] = "Каждое задание зоны в журнале заданий карты: кто даёт, где и что осталось сделать.", -- draft
