	["Objective Marks"] = "Метки целей", -- draft
	["Marks where your quests' objectives are on the zone map, with their progress. Click a mark for a waypoint."] = "Отмечает на карте зоны, где цели ваших заданий, с прогрессом. Щелчок по метке ставит точку маршрута.", -- draft
	["Only The Tracked Quests"] = "Только отслеживаемые задания", -- draft
	["Marks only the quests you track."] = "Отмечает только отслеживаемые задания.", -- draft
	["Hide The Game's Quest Areas"] = "Скрыть области заданий игры", -- draft
	["Hides the game's blue quest areas while MelloUI's marks are on."] = "Скрывает синие области заданий игры, пока включены метки MelloUI.", -- draft
	["On The Minimap"] = "На мини-карте", -- draft
	["The same marks on the minimap, with an arrow for nearby ones off its edge. Needs Route."] = "Те же метки на мини-карте, со стрелкой для ближних за её краем. Нужен Route.", -- draft
	["Quest Check When Entering An Instance"] = "Проверка заданий при входе в подземелье", -- draft
	["Entering a dungeon or raid lists in the chat its quests you have not picked up."] = "При входе в подземелье или рейд чат перечисляет его задания, которые вы не взяли.", -- draft
	["Quest Progress On Items"] = "Ход заданий на предметах", -- draft
	["Item tooltips show the quest that needs the item and your progress."] = "Подсказки предметов показывают задание, которому он нужен, и ваш прогресс.", -- draft
	["Turn-In NPCs"] = "NPC для сдачи", -- draft
	["NPC tooltips show where you can turn in a quest."] = "Подсказки НИП показывают, где можно сдать задание.", -- draft
	["Your Other Characters On Quests"] = "Ваши другие персонажи в заданиях", -- draft
