	-- Route
	["Route"] = "Маршрут", -- draft
	["Draws the way to your waypoint on the world map and the minimap, along real roads."] = "Прокладывает путь к точке маршрута на карте мира и мини-карте по настоящим дорогам.", -- draft
	["A trail of gems from here to there, along the roads you have walked before."] = "След из самоцветов отсюда туда, по дорогам, где вы уже ходили.", -- draft
	["Drawing"] = "Отрисовка", -- draft
	["Route On The World Map"] = "Маршрут на карте мира", -- draft
	["Draws the route and its destination flag on the world map."] = "Рисует маршрут и флаг назначения на карте мира.", -- draft
	["Route On The Minimap"] = "Маршрут на мини-карте", -- draft
	["Draws the nearby part of the route on the minimap."] = "Рисует ближнюю часть маршрута на мини-карте.", -- draft
	["Trail Look"] = "Вид следа", -- draft
	["How the route is drawn: red beads, a gold line, or gold dashes."] = "Как рисуется маршрут: красные бусины, золотая линия или золотой пунктир.", -- draft
	["Red Beads"] = "Красные бусины", -- draft
	["Gilded Line"] = "Золочёная линия", -- draft
	["Waymarks"] = "Вехи", -- draft
	["Trail Size"] = "Размер следа", -- draft
	["How big the route's trail is."] = "Размер следа маршрута.", -- draft
	["Route To The Tracked Quest"] = "Маршрут к отслеживаемому заданию", -- draft
	["Without a map pin, routes to the quest you track: its next objective, then its turn-in."] = "Без метки на карте ведёт к отслеживаемому заданию: его следующей цели, затем к сдаче.", -- draft
	["Fall Back To The First Tracked Quest"] = "Брать первое отслеживаемое задание", -- draft
	["When no quest is followed, routes to the first quest on the game's watch list."] = "Если вы ни за каким заданием не следуете, ведёт к первому в списке отслеживания игры.", -- draft
	["Distance Under The Minimap"] = "Расстояние под мини-картой", -- draft
	["The distance left and the destination under the minimap."] = "Оставшееся расстояние и цель под мини-картой.", -- draft
	["Travel Time"] = "Время в пути", -- draft
	["About how long the rest of the way takes, beside the distance."] = "Примерное время оставшегося пути рядом с расстоянием.", -- draft
	["A mark over the destination in the world with its distance; an arrow points the way when it is off screen."] = "Метка над целью в мире с расстоянием; стрелка показывает путь, если цель за экраном.", -- draft
	["Light Beam"] = "Луч света", -- draft
	["A slim beam of light over the destination, seen from far away."] = "Тонкий луч света над целью, видный издалека.", -- draft
	["Wisp"] = "Огонёк", -- draft
	["A small light flies from you to a new destination and lights it."] = "Маленький огонёк летит от вас к новой цели и зажигает её.", -- draft
	["Firefly"] = "Светлячок", -- draft
	["Embers"] = "Угольки", -- draft
	["Route Draws In"] = "Прорисовка маршрута", -- draft
	["A new route grows from you to the destination instead of appearing all at once."] = "Новый маршрут вырастает от вас к цели, а не появляется целиком.", -- draft
	["Arrival Light"] = "Свет прибытия", -- draft
	["The mark sinks into a ring of light when you arrive."] = "Метка опускается в кольцо света, когда вы прибываете.", -- draft
	["Marker Sounds"] = "Звуки маркера", -- draft
	["A soft sound when the World Marker appears or changes."] = "Тихий звук, когда маркер мира появляется или меняется.", -- draft
	["Arrival"] = "Прибытие", -- draft
	["Arrived Within (yards)"] = "Прибытие в пределах (м)", -- draft
	["How close you must get for the route to end."] = "Насколько близко нужно подойти, чтобы маршрут завершился.", -- draft
	["Flights"] = "Полёты", -- draft
	["Flight Map Help"] = "Помощь на карте полётов", -- draft
	["At a flight master, shows where your route flies to and how long the flight takes."] = "У распорядителя полётов показывает, куда летит маршрут и сколько длится полёт.", -- draft
	["Learning"] = "Обучение", -- draft
	["Learn Paths While Playing"] = "Запоминать пути во время игры", -- draft
	["Remembers where you walk and fly, so routes follow real roads."] = "Запоминает, где вы ходите и летаете, чтобы маршруты шли по настоящим дорогам.", -- draft
	-- Chat
	["Clean chat: hidden background and input art, short coloured channel tags, class coloured names."] = "Чистый чат: скрытые фон и оформление поля ввода, короткие цветные метки каналов, имена в цвете класса.", -- draft
	["Less frame, more talk. Short channel tags and class colours keep the log readable."] = "Меньше рамки, больше разговора. Короткие метки каналов и цвета классов держат журнал читаемым.", -- draft
	["Chat View"] = "Вид чата", -- draft
	["How the chat looks. Game Windows: the game's windows and tabs. Minimal: one panel with round tabs, each message under its sender, and buttons to pick a channel."] = "Как выглядит чат. Окна игры: окна и вкладки игры. Минимальные: одна панель с круглыми вкладками, каждое сообщение под отправителем, и кнопки выбора канала.", -- draft
	["Game Windows"] = "Окна игры", -- draft
	["Minimal"] = "Минимальный", -- draft
	["The chat's background: Dark, the game's own, or none."] = "Фон чата: Тёмный, игровой или никакого.", -- draft
	["Set The Background Opacity"] = "Задать непрозрачность фона", -- draft
	["Every chat window uses the same background opacity. Off: each keeps its own."] = "Все окна чата с одинаковой прозрачностью фона. Выкл.: у каждого своя.", -- draft
	["How solid the chat windows' background is."] = "Непрозрачность фона окон чата.", -- draft
	["Border Opacity"] = "Непрозрачность рамки", -- draft
	["How solid the painted border around the chat is."] = "Непрозрачность рисованной каймы чата.", -- draft
	["Hide Input Box Art"] = "Скрыть оформление поля ввода", -- draft
	["Hides the border and background of the chat's input line."] = "Скрывает кайму и фон строки ввода чата.", -- draft
	["Hide Tab Background"] = "Скрыть фон вкладок", -- draft
	["Hides the background behind the chat tabs. Their names stay."] = "Скрывает фон за вкладками чата. Названия остаются.", -- draft
	["Tabs Only On Mouseover"] = "Вкладки только при наведении", -- draft
	["The chat tab names show only while your mouse is over the chat. Flashing tabs stay visible."] = "Названия вкладок чата видны только при наведении мыши на чат. Мигающие вкладки видны всегда.", -- draft
	["Input Box On Top"] = "Поле ввода сверху", -- draft
	["The input line sits above the chat instead of below it."] = "Строка ввода над чатом, а не под ним.", -- draft
	["Input Box Only While Typing"] = "Поле ввода только при наборе", -- draft
	["The input line shows only while you type."] = "Строка ввода видна только во время набора.", -- draft
	["Chat Buttons"] = "Кнопки чата", -- draft
	["The column of chat buttons beside the chat: Friends, Channels and the chat menu."] = "Колонка кнопок рядом с чатом: Друзья, Каналы и меню чата.", -- draft
	["Smooth Scrolling"] = "Плавная прокрутка", -- draft
	["The mouse wheel scrolls the chat smoothly instead of a line at a time."] = "Колесо мыши прокручивает чат плавно, а не по строке.", -- draft
	["Channels"] = "Каналы", -- draft
	["Short Channel Tags"] = "Короткие метки каналов", -- draft
	["Short coloured tags instead of [Guild], [Party], [1. General] and so on."] = "Короткие цветные метки вместо [Гильдия], [Группа], [1. Общий] и т. д.", -- draft
	["Hide Brackets"] = "Скрыть скобки", -- draft
	["Removes the brackets around the short tags."] = "Убирает скобки вокруг коротких меток.", -- draft
	["Whisper Popup Window"] = "Всплывающее окно шёпота", -- draft
	["Each whisper opens a small window for that person, with a box to answer in. Whispers still show in the chat."] = "Каждый шёпот открывает маленькое окно для этого человека с полем ответа. Шёпот по-прежнему виден в чате.", -- draft
	-- CombatText
	["The text around your character in a fight (damage taken, heals, procs) in MelloUI's look, or the game's own."] = "Текст вокруг персонажа в бою (полученный урон, исцеление, срабатывания) в стиле MelloUI или игры.", -- draft
	["Your hits taken, heals and procs in MelloUI's soft look, or the game's own text."] = "Полученные удары, исцеление и срабатывания в мягком облике MelloUI или текст игры.", -- draft
	["Combat Text Style"] = "Стиль текста боя", -- draft
	["How the text around your character is shown. Game: the game's own. Lanes: damage taken left, healing right. Feed: one column over your portrait. Classic: one stream over your head."] = "Как показан текст вокруг персонажа. Игра: игровой. Дорожки: полученный урон слева, исцеление справа. Лента: колонка над портретом. Классика: поток над головой.", -- draft
