	-- DungeonInfo
	["Dungeon Info"] = "Сведения о подземельях", -- draft
	["Every dungeon and raid: its bosses, what they drop, and your own list of items to watch for."] = "Каждое подземелье и рейд: боссы, их добыча и ваш список желанных предметов.", -- draft
	["Every dungeon's bosses and their loot beside the map; star the items you want and a loot roll tells you when one drops."] = "Боссы каждого подземелья и их добыча рядом с картой; отметьте звёздочкой нужные предметы — розыгрыш сообщит, когда выпадет.", -- draft
	["Open Dungeon Info"] = "Открыть сведения о подземельях", -- draft
