	["Your swing timer as a small badge on your target's nameplate."] = "Ваш таймер ударов маленьким значком на индикаторе здоровья цели.", -- draft
	["Big Cooldowns"] = "Крупные способности", -- draft
	["Your big defensive cooldowns (Shield Wall, Evasion, Ice Block...) as icons above the health bar."] = "Ваши большие защитные восстановления («Глухая оборона», «Ускользание», «Ледяная глыба»...) значками над полосой здоровья.", -- draft
	["Percent And Spell Text"] = "Процент и текст заклинания", -- draft
	["Health and power percent, spell names and times."] = "Процент здоровья и энергии, названия и время заклинаний.", -- draft
	["Text Font"] = "Шрифт текста", -- draft
	["The font of the display's text. Shared: the interface font."] = "Шрифт текста панели. Общая: шрифт интерфейса.", -- draft
	["Class Colours"] = "Цвета классов", -- draft
	["The health bar in your class colour instead of green."] = "Полоса здоровья цветом вашего класса вместо зелёного.", -- draft
	["How wide the bars are."] = "Ширина полос.", -- draft
	["How tall the health bar is; the others follow."] = "Высота полосы здоровья; остальные следуют.", -- draft
	["Big Cooldown Size"] = "Размер крупных способностей", -- draft
	["The size of the Big Cooldowns' icons."] = "Размер значков больших восстановлений.", -- draft
	["Follow Camera Zoom"] = "Следовать зуму камеры", -- draft
	["The display stays by your character as you zoom the camera."] = "Панель остаётся у персонажа при приближении и отдалении камеры.", -- draft
	["Cast Motion"] = "Движение заклинания", -- draft
	["The cast bar opens, flashes on a landed cast and drops when interrupted."] = "Полоса заклинания раскрывается, вспыхивает при успехе и падает при прерывании.", -- draft
	["The health a hit took stays lit for a moment before it drains."] = "Здоровье, отнятое ударом, миг светится перед тем, как уйти.", -- draft
	["Heal Lead"] = "Опережение исцеления", -- draft
	["A heal lights the health it gives at once; the bar then fills into it."] = "Исцеление сразу подсвечивает возвращаемое здоровье; затем полоса заполняется до него.", -- draft
	["Heavy Hit"] = "Тяжёлый удар", -- draft
	["A critical or crushing blow on you flashes the bars red."] = "Критический или сокрушительный удар по вам вспыхивает на полосах красным.", -- draft
	["Power Spent"] = "Потраченный ресурс", -- draft
	["The power an ability costs stays lit for a moment, so you see the cost."] = "Ресурс, который стоит способность, миг светится — видно стоимость.", -- draft
	["Power Gained"] = "Полученный ресурс", -- draft
	["New power lights up ahead of the bar before it fills."] = "Новый ресурс подсвечивается впереди полосы перед заполнением.", -- draft
	["Dodge, Parry, Block"] = "Уклонение, парирование, блок", -- draft
	["Your dodge, parry or block flicks its word off the health bar."] = "Ваше уклонение, парирование или блок отлетает от полосы здоровья.", -- draft
	["Low Health"] = "Низкое здоровье", -- draft
	["The health bar turns ember under 35% health."] = "Полоса здоровья становится цвета углей ниже 35% здоровья.", -- draft
	["Loss Of Control"] = "Потеря контроля", -- draft
	["While you are stunned, feared or silenced, the bars turn red and a line counts down its time. Replaces the game's own banner."] = "Пока вы оглушены, напуганы или безмолвны, полосы краснеют и линия отсчитывает время. Заменяет игровой баннер.", -- draft
	["Combat Settle"] = "Посадка в бою", -- draft
	["The bars rise into place when a fight starts and settle lower and slimmer after it. (To fade them out of combat: the Fader.)"] = "В начале боя полосы поднимаются на место, а после опускаются ниже и тоньше. (Чтобы скрывать их вне боя: «Затухание».)", -- draft
	["Plays a short sample fight on the display."] = "Проигрывает короткий пример боя на панели.", -- draft
	["a shield going up, hit, low and broken, casts, and the bars in the fight"] = "щит поднимается, принимает удары, слабеет и разбивается, заклинания и полосы в бою", -- draft
	-- VoiceOver
	["Voice Over"] = "Voice Over", -- draft
	["Reads NPC dialog, quests and books aloud: recorded voices from the voice pack, or text-to-speech."] = "Читает вслух диалоги НИП, задания и книги: записанные голоса из набора озвучки или синтез речи.", -- draft
	["Every quest giver speaks. Recorded voices with the pack, text-to-speech without it."] = "Говорит каждый, кто даёт задания. Записанные голоса с пакетом, синтез речи без него.", -- draft
