	["Quest Progress"] = "Ход задания", -- draft
	["What the NPC says when you return with an unfinished quest."] = "Что говорит NPC, когда вы возвращаетесь с невыполненным заданием.", -- draft
	["Quest Turn-In"] = "Сдача задания", -- draft
	["What the NPC says when you hand in a quest."] = "Что говорит НИП, когда вы сдаёте задание.", -- draft
	["Read Books And Letters Aloud"] = "Читать вслух книги и письма", -- draft
	["Books, letters, notes and signs read aloud when you open them."] = "Книги, письма, записки и таблички читаются вслух при открытии.", -- draft
	["Text-to-Speech"] = "Синтез речи", -- draft
	["Male NPCs"] = "NPC-мужчины", -- draft
	["The text-to-speech voice for male NPCs. Add voices in Windows' speech settings."] = "Голос синтеза речи для мужских НИП. Добавить голоса можно в настройках речи Windows.", -- draft
	["Automatic (by gender)"] = "По полу", -- draft
	["Female NPCs"] = "NPC-женщины", -- draft
