	["Home"] = "Главная", -- draft
	["The painted reskin and MelloUI's interface features: Vendor, Error Messages, Nameplate Tweaks, Unit Frame Tweaks, Chat, Tooltip, Fonts, Dark Mode, Bar Textures and FPS / Latency, and hiding the micro menu, bag bar and minimap coordinates. Off: all of them stop, and Edit Layout lets go of the game's windows; the palette, the UI Shade, Reduce Motion and the notices keep working."] = "Рисованный рескин и функции интерфейса MelloUI: торговец, сообщения об ошибках, доработки индикаторов здоровья и рамок юнитов, чат, подсказка, шрифты, тёмный режим, текстуры полос и FPS / задержка, а также скрытие микроменю, панели сумок и координат мини-карты. Выкл.: всё останавливается, а «Изменить раскладку» отпускает окна игры; палитра, тень интерфейса, «Меньше движения» и уведомления продолжают работать.", -- draft
	["The look of the whole interface: its skin, the soft shade, every font and texture, the colours, icons and Dark Mode. The painted reskin and its palettes are on the Oldschool page."] = "Облик всего интерфейса: его вид, мягкая тень, каждый шрифт и текстура, цвета, значки и тёмный режим. Рисованный рескин и его палитры — на странице Oldschool.", -- draft
	["The minimap and the Services bar under it: pick one, click a part, change it."] = "Мини-карта и панель «Услуги» под ней: выберите одно, щёлкните по части, измените её.", -- draft
