	["Every setting on this page back to its default: every tab, and on a page with a picker the one picked (and what every pick shares). Switches of whole modules and what belongs to your character stay as they are. It asks first."] = "Все настройки этой страницы по умолчанию: каждая вкладка, а на странице с выбором — выбранное (и то, что общее для всех вариантов). Переключатели целых модулей и то, что принадлежит персонажу, остаются как есть. Сначала спрашивает.", -- draft
