	["Reset every setting on the %s page to its default? It changes %s."] = "Сбросить все настройки страницы %s по умолчанию? Это меняет %s.", -- draft
	["Reset every setting on the %s page for %s to its default? It changes %s."] = "Сбросить все настройки страницы %s для %s по умолчанию? Это меняет %s.", -- draft
