	["Nothing to pick on it: its options are below."] = "Здесь нечего выбирать: параметры ниже.", -- draft
	["Reset part"] = "Сбросить часть", -- draft
	["This part's settings back to their defaults, and its place on the frame. Switches of whole modules and what belongs to your character stay as they are. It asks first."] = "Настройки этой части по умолчанию и её место на рамке. Переключатели целых модулей и то, что принадлежит персонажу, остаются как есть. Сначала спрашивает.", -- draft
	["Reset %s"] = "Сбросить %s", -- draft
	["Every setting of %s back to its default%s. Switches of whole modules and what belongs to your character stay as they are. It asks first."] = "Все настройки %s по умолчанию%s. Переключатели целых модулей и то, что принадлежит персонажу, остаются как есть. Сначала спрашивает.", -- draft
	[": its own and its parts' (not All frames', not the places on the frame)"] = ": свои и её частей (не «Всех рамок» и не места на рамке)", -- draft
