	["Every setting %s keeps for itself, copied from the one you choose; what they share is one setting already. It asks first."] = "Каждая собственная настройка %s, скопированная из выбранного; общее у них — уже одна настройка. Сначала спрашивает.", -- draft
	["Not in combat: this would switch painted skins."] = "Не в бою: это переключило бы рисованные облики.", -- draft
