	["Load"] = "Загрузить", -- draft
	["Go back to how MelloUI was before the installer ran ('Before install')? Your settings return to what they were then, and Edit Mode's layouts too if the installer changed them."] = "Вернуть MelloUI к состоянию до запуска установщика («Before install»)? Настройки вернутся к тогдашним, а раскладки режима редактирования тоже, если установщик их менял.", -- draft
	["Go back"] = "Вернуть", -- draft
