	["Active: %s      Default on a fresh install: %s"] = "Активный: %s      По умолчанию при новой установке: %s", -- draft
	["Set default"] = "Сделать стандартным", -- draft
	["built in"] = "встроенный", -- draft
	["A profile is a copy of every setting of every module. It leaves out your Dark Mode and what belongs to your characters: the flight points they know, game settings MelloUI borrowed, and steps done once; loading a profile never touches those. The one marked default is applied when MelloUI starts with no settings at all, such as on a fresh install. Load asks before it replaces your settings. Profiles you save here are kept with your settings; Share gives a string to pass one on, and Import as brings one in. The profiles that come with MelloUI are always here."] = "Профиль — это копия всех настроек всех модулей. В него не входят ваш тёмный режим и то, что принадлежит персонажам: известные им точки полёта, позаимствованные MelloUI настройки игры и разовые шаги; загрузка профиля этого никогда не трогает. Отмеченный как стандартный применяется, когда MelloUI запускается совсем без настроек, например при новой установке. «Загрузить» спрашивает, прежде чем заменить ваши настройки. Сохранённые здесь профили хранятся вместе с настройками; «Поделиться» даёт строку, чтобы передать профиль, а «Импортировать как» приносит его. Профили, поставляемые с MelloUI, всегда здесь.", -- draft
	["Save current as"] = "Сохранить текущие как", -- draft
	["Profile '%s' saved."] = "Профиль «%s» сохранён.", -- draft
	["Import as"] = "Импортировать как", -- draft
	["Type a name for the imported profile first, then click Import as."] = "Сначала введите имя для импортируемого профиля, затем нажмите «Импортировать как».", -- draft
	["paste a MelloUI profile string for '%s'"] = "вставьте строку профиля MelloUI для «%s»", -- draft
	["Not imported: %s."] = "Не импортировано: %s.", -- draft
	["Profile '%s' imported (%d settings). Load it from the list to use it."] = "Профиль «%s» импортирован (настроек: %d). Загрузите его из списка, чтобы использовать.", -- draft
	["No profiles yet. Type a name above and save the current settings."] = "Профилей пока нет. Введите имя выше и сохраните текущие настройки.", -- draft
	["Legends"] = "Легенды", -- draft
	["Champions"] = "Чемпионы", -- draft
	["MelloUI is free for everyone and always will be. These are the people who help keep it going. Thank you, all of you!"] = "MelloUI бесплатен для всех и всегда будет бесплатным. Это люди, которые помогают ему развиваться. Спасибо вам всем!", -- draft
	["No names here yet. They show up with each MelloUI update."] = "Здесь пока нет имён. Они появляются с каждым обновлением MelloUI.", -- draft
	["As of %s"] = "На %s", -- draft
	["Search options"] = "Поиск параметров", -- draft
	["Nothing found. Try another word."] = "Ничего не найдено. Попробуйте другое слово.", -- draft
	["%d more. Type more letters to narrow it down."] = "Ещё %d. Введите больше букв, чтобы сузить поиск.", -- draft
	["Top bar"] = "Верхняя строка", -- draft
	["unlock windows snap snapping auto position positions reset"] = "разблокировать окна привязка прилипание автопозиция позиции сброс", -- draft
	["preview simulate simulation test demo try fight combat behave behaviour"] = "предпросмотр симуляция тест демо попробовать бой сражение поведение", -- draft
	["Edit Layout"] = "Изменить раскладку", -- draft
	["Move and size MelloUI's windows and bars on the screen itself. Closes the configurator while you edit."] = "Двигайте и меняйте размер окон и панелей MelloUI прямо на экране. Закрывает конфигуратор на время правки.", -- draft
	["See how your interface behaves in a fight, with made-up numbers: resting, the fight, after it. A fight alone or in a group, or one part at a time (the fades, the reminders, the widget column, party frames, the meter, Combat Text, Gains). Out of combat only; Stop ends it."] = "Посмотрите, как интерфейс ведёт себя в бою, на выдуманных числах: в покое, в бою, после него. Бой в одиночку или в группе, или по одной части (угасание, напоминания, колонка виджетов, рамки группы, счетчик, «Текст боя», «Получения»). Только вне боя; «Стоп» завершает.", -- draft
	["Install…"] = "Установить…", -- draft
	["The installer: a setup for the whole interface in a few steps, fitted to this screen. Closes the configurator while it runs."] = "Установщик: настройка всего интерфейса за несколько шагов, подогнанная под этот экран. Закрывает конфигуратор на время работы.", -- draft
	-- Core/Installer.lua
	["MelloUI setup"] = "Настройка MelloUI", -- draft
	["Mello's layout and the window places fitted to this screen. Your other settings stay."] = "Раскладка Mello и места окон, подогнанные под этот экран. Остальные настройки остаются.", -- draft
	["MelloUI's settings are still loading; try again in a moment."] = "Настройки MelloUI ещё загружаются; попробуйте через мгновение.", -- draft
	["Install waits until you are out of combat."] = "Установка ждёт, пока вы выйдете из боя.", -- draft
	["Close Edit Mode first."] = "Сначала закройте режим редактирования.", -- draft
	["Your screen is still being fitted."] = "Экран ещё подгоняется.", -- draft
	["Your screen changed; it is being fitted again."] = "Экран изменился; он подгоняется заново.", -- draft
	["Edit Mode already keeps %d account layouts, the most it can. Delete one in Edit Mode, or keep your own layout."] = "В режиме редактирования уже %d раскладок учётной записи — максимум. Удалите одну в режиме редактирования или оставьте свою раскладку.", -- draft
	["Keep or revert the setup you just installed first."] = "Сначала оставьте или верните только что установленную настройку.", -- draft
	["There is no setup to go back to."] = "Возвращаться не к чему.", -- draft
	["Paused while you are in combat."] = "Пауза, пока вы в бою.", -- draft
	["Revert waits until you are out of combat; try again then."] = "«Вернуть» ждёт, пока вы выйдете из боя; тогда попробуйте снова.", -- draft
	["Paused while Edit Mode is open."] = "Пауза, пока открыт режим редактирования.", -- draft
	["%s installed. Keep it, or MelloUI goes back to 'Before install' when the timer runs out."] = "%s установлено. Оставьте, или MelloUI вернётся к «Before install», когда истечёт таймер.", -- draft
	["Your layout was fitted to this screen. Keep it, or MelloUI goes back to 'Before install' when the timer runs out."] = "Ваша раскладка подогнана под этот экран. Оставьте её, или MelloUI вернётся к «Before install», когда истечёт таймер.", -- draft
	["MelloUI's Edit Mode layout did not go in (%s). Your own layout stays; /mello layout check shows why."] = "Раскладка режима редактирования MelloUI не применилась (%s). Ваша раскладка остаётся; /mello layout check покажет почему.", -- draft
	["the screen was not fitted"] = "экран не был подогнан", -- draft
	["Back to 'Before install'."] = "Возврат к «Before install».", -- draft
	["Something went wrong while installing, so MelloUI went back to 'Before install'."] = "При установке что-то пошло не так, поэтому MelloUI вернулся к «Before install».", -- draft
	["Something went wrong while installing. Use Revert to go back to 'Before install'."] = "При установке что-то пошло не так. Используйте «Вернуть», чтобы вернуться к «Before install».", -- draft
	["Something went wrong while preparing the setup. Nothing was changed."] = "При подготовке настройки что-то пошло не так. Ничего не изменено.", -- draft
	["MelloUI could not go all the way back to 'Before install'. Type /reload to try again."] = "MelloUI не смог полностью вернуться к «Before install». Введите /reload, чтобы попробовать снова.", -- draft
	["This setup did not install fully, so it cannot be kept. Revert goes back to 'Before install'."] = "Эта настройка установилась не полностью, поэтому её нельзя оставить. «Вернуть» возвращает к «Before install».", -- draft
	["MelloUI was only partly put back, so this setup cannot be kept. Revert tries again to go back to 'Before install'."] = "MelloUI восстановлен лишь частично, поэтому эту настройку нельзя оставить. «Вернуть» снова пытается вернуться к «Before install».", -- draft
	["%s: %.1f ms in one frame."] = "%s: %.1f мс за один кадр.", -- draft
	["The installer opens when combat ends."] = "Установщик откроется, когда закончится бой.", -- draft
	["Close Edit Mode first, then open the installer again."] = "Сначала закройте режим редактирования, затем снова откройте установщик.", -- draft
	["Version %s. /mello shows what's new; Install... there sets MelloUI up again."] = "Версия %s. /mello показывает, что нового; «Установить...» там настраивает MelloUI заново.", -- draft
	["Use MelloUI's Edit Mode layout on this character too?\n\nYour own layouts stay in Edit Mode's list. Later: /mello layout apply."] = "Использовать раскладку режима редактирования MelloUI и на этом персонаже?\n\nВаши собственные раскладки остаются в списке режима редактирования. Позже: /mello layout apply.", -- draft
	["Use it"] = "Использовать", -- draft
	["MelloUI's Edit Mode layout is not active on this character: pick it in Edit Mode's layout list, or log in without the Gamepad UI to be asked."] = "Раскладка режима редактирования MelloUI не активна на этом персонаже: выберите её в списке раскладок режима редактирования или войдите без интерфейса контроллера, чтобы вас спросили.", -- draft
	-- Core/InstallerWindow.lua
	["Screen: %s"] = "Экран: %s", -- draft
	["Detected screen: %s"] = "Обнаружен экран: %s", -- draft
	["Fitting to your screen..."] = "Подгонка под ваш экран...", -- draft
	["Mello's layout could not be fitted on this client; your own Edit Mode layout stays."] = "Раскладку Mello не удалось подогнать на этом клиенте; ваша раскладка режима редактирования остаётся.", -- draft
	["Aspect ratio"] = "Соотношение сторон", -- draft
	["Mello's layout, as made"] = "Раскладка Mello как есть", -- draft
	["Mello's layout, fitted to your screen"] = "Раскладка Mello, подогнанная под ваш экран", -- draft
	["Being fitted to your screen"] = "Подгоняется под ваш экран", -- draft
	["Your own Edit Mode layout stays"] = "Ваша раскладка остаётся", -- draft
	["UI scale: yours stays as it is"] = "Масштаб: без изменений", -- draft
	["MelloUI never changes it"] = "MelloUI никогда его не меняет", -- draft
	["Add the '%s' Edit Mode layout (your own layouts stay)"] = "Добавить раскладку «%s» (ваши остаются)", -- draft
	["Mello's layout, fitted to this screen, as an account layout of its own, made active. Your own layouts stay in the list, and Revert puts the one you use now back."] = "Раскладка Mello, подогнанная под этот экран, как отдельная раскладка учётной записи, сделанная активной. Ваши раскладки остаются в списке, а «Вернуть» возвращает ту, которой вы пользуетесь сейчас.", -- draft
	["Pieces at an edge keep their distance to it; the centre group tightens to fit; then everything is checked for overlaps."] = "Элементы у края сохраняют расстояние до него; центральная группа сжимается, чтобы поместиться; затем всё проверяется на перекрытия.", -- draft
	["Worth a look in the game once it is in:"] = "Стоит взглянуть в игре, когда всё будет на месте:", -- draft
	["... and %d more"] = "... и ещё %d", -- draft
	["Your own Edit Mode layout suits this screen better."] = "Ваша раскладка режима редактирования лучше подходит этому экрану.", -- draft
	["Install Without The Layout"] = "Установить без раскладки", -- draft
	["Delete '%s'"] = "Удалить «%s»", -- draft
	["Delete the Edit Mode layout '%s'?\n\nIt is an older MelloUI layout, made for another screen. Your own layouts stay, and Edit Mode then has room for this screen's."] = "Удалить раскладку режима редактирования «%s»?\n\nЭто старая раскладка MelloUI для другого экрана. Ваши раскладки остаются, и в режиме редактирования появится место для раскладки этого экрана.", -- draft
	["Delete it"] = "Удалить", -- draft
	["The Edit Mode layout '%s' was not deleted: %s."] = "Раскладка режима редактирования «%s» не удалена: %s.", -- draft
	["%s: this is what changes."] = "%s: вот что изменится.", -- draft
	["Edit Mode layout '%s', fitted to %s"] = "Раскладка режима редактирования «%s», подогнанная под %s", -- draft
	["The Edit Mode layout, once your screen is fitted"] = "Раскладка режима редактирования, когда экран будет подогнан", -- draft
	["No Edit Mode change: your own layout stays"] = "Без изменений в режиме редактирования: ваша раскладка остаётся", -- draft
	["Your UI scale stays as it is"] = "Ваш масштаб интерфейса остаётся как есть", -- draft
	["Your current setup is saved as the profile 'Before install' first, so you can go back to it later from the Profiles page. After Install you have 15 seconds to keep the new setup; Keep then reloads the UI."] = "Сначала ваша текущая настройка сохраняется как профиль 'Before install', чтобы позже вернуться к ней со страницы «Профили». После «Установить» у вас 15 секунд, чтобы оставить новую настройку; «Оставить» затем перезагружает интерфейс.", -- draft
	["Keep this setup?"] = "Оставить эту настройку?", -- draft
	["If you don't answer, MelloUI goes back to 'Before install' when the timer runs out."] = "Если не ответить, MelloUI вернётся к «Before install», когда истечёт таймер.", -- draft
	["Keep reloads the UI, so everything takes the new setup."] = "«Оставить» перезагружает интерфейс, чтобы всё приняло новую настройку.", -- draft
	["Type /reload so everything takes the new setup."] = "Введите /reload, чтобы всё приняло новую настройку.", -- draft
	["Type /reload to finish: the names above characters still use the installed font."] = "Введите /reload, чтобы завершить: имена над персонажами ещё используют установленный шрифт.", -- draft
	["Back as before"] = "Как было", -- draft
	["Install... in /mello (or /mello install) sets MelloUI up any time."] = "«Установить...» в /mello (или /mello install) настраивает MelloUI в любое время.", -- draft
	["Continue keeps Mello's own choice for this step."] = "«Продолжить» сохраняет выбор Mello для этого шага.", -- draft
	["Continue"] = "Продолжить", -- draft
	["Back"] = "Назад", -- draft
	["Install"] = "Установить", -- draft
	["Keep"] = "Оставить", -- draft
	["Choose again"] = "Выбрать заново", -- draft
	["Close"] = "Закрыть", -- draft
	["How everything looks: the game's frames and MelloUI's own windows and features alike. Every step after this one shows its pictures in this skin."] = "Как выглядит всё: окна игры и окна и функции MelloUI одинаково. Каждый следующий шаг показывает картинки в этом облике.", -- draft
	["Recommended"] = "Рекомендуется", -- draft
	["Not installed"] = "Не установлено", -- draft
	["Switched off"] = "Выключено", -- draft
	["MelloUI Oldschool is an addon of its own. Get it from CurseForge, then restart the game: this card turns on."] = "MelloUI Oldschool — отдельная модификация. Скачайте её с CurseForge и перезапустите игру: эта карточка включится.", -- draft
	["MelloUI Oldschool is installed but switched off: switch it on in the game's AddOn list, then type /reload."] = "MelloUI Oldschool установлен, но выключен: включите его в списке модификаций игры и введите /reload.", -- draft
	["The game can't open web pages: the link is selected in the box, Ctrl+C copies it."] = "Игра не открывает веб-страницы: ссылка выделена в поле, Ctrl+C копирует её.", -- draft
	["Where everything stands on your %s screen."] = "Где всё стоит на вашем экране %s.", -- draft
	["Your own Edit Mode layout stays as it is."] = "Ваша раскладка режима редактирования остаётся как есть.", -- draft
	["Keep My Layout"] = "Оставить мою раскладку", -- draft
	["Pick what you want. Each one comes with Mello's settings for it; change them any time in /mello."] = "Выберите, что хотите. Каждый вариант идёт с настройками Mello; меняйте их когда угодно в /mello.", -- draft
	["Skin: %s"] = "Облик: %s", -- draft
	["Colours: the game's own"] = "Цвета: игровые", -- draft
	["Default"] = "По умолчанию", -- draft
	["The game's own look for everything, MelloUI's windows and features too."] = "Облик игры для всего, включая окна и функции MelloUI.", -- draft
	["Modern"] = "Современный", -- draft
	["MelloUI's own look for everything: slate panels, gold trim, one clean font."] = "Собственный облик MelloUI для всего: сланцевые панели, золотая отделка, один чистый шрифт.", -- draft
	["The painted RPG look for everything: parchment, iron and stone."] = "Рисованный RPG-облик для всего: пергамент, железо и камень.", -- draft
	["Mello's Layout"] = "Раскладка Mello", -- draft
	["Bars, frames, chat and the map column fitted to your screen; your own layouts stay in Edit Mode's list."] = "Панели, рамки, чат и колонка карты подогнаны к вашему экрану; ваши раскладки остаются в списке режима редактирования.", -- draft
	["Your Edit Mode layout stays exactly as it is; MelloUI only dresses it."] = "Ваша раскладка режима редактирования остаётся точно такой же; MelloUI лишь одевает её.", -- draft
	["MelloUI's own party and raid frames, the heal and cooldown effects across them."] = "Рамки группы и рейда MelloUI с эффектами исцеления и восстановлений.", -- draft
	["Portraits"] = "Портреты", -- draft
	["The game's party frames with their portraits, in your skin."] = "Рамки группы игры с портретами, в вашем облике.", -- draft
	["Your own frame on top of the group."] = "Ваша рамка сверху группы.", -- draft
	["Portraits on the right: for a party on the right side of the screen."] = "Портреты справа: для группы справа на экране.", -- draft
	["Your friends' class medallions over their heads, to find them in a crowd."] = "Медальоны классов друзей над их головами, чтобы найти их в толпе.", -- draft
	["Your quests by zone, in your skin."] = "Ваши задания по зонам, в вашем облике.", -- draft
	["Every quest near you, on the map and in a list."] = "Каждое задание рядом, на карте и в списке.", -- draft
	["The way to your next quest, over the real ground."] = "Путь к следующему заданию по настоящей земле.", -- draft
	["One seamless world map with your quests."] = "Одна цельная карта мира с вашими заданиями.", -- draft
	["Quest givers speak their text."] = "Дающие задания произносят свой текст.", -- draft
	["Repair, innkeeper, flight master: one click routes there."] = "Ремонт, хозяин таверны, распорядитель полётов: щелчок прокладывает маршрут.", -- draft
	["Every dungeon and raid on the map: its bosses, their loot, your wish list."] = "Каждое подземелье и рейд на карте: боссы, их добыча, ваш список желаний.", -- draft
	["Enemy plates: names, debuffs, crowd control, threat."] = "Индикаторы противников: имена, эффекты, контроль, угроза.", -- draft
	["Your hits and heals, easy to read."] = "Ваши удары и исцеления, легко читаются.", -- draft
	["Damage and healing, for you and your group."] = "Урон и исцеление, ваши и группы.", -- draft
	["Heal And Cooldown Effects"] = "Эффекты исцеления и восстановлений", -- draft
	["Heals fly to the frame and land on it; cooldowns show on it."] = "Исцеления летят к рамке и опускаются на неё; восстановления видны на ней.", -- draft
	["Your health, power and cooldowns under your character."] = "Здоровье, ресурс и восстановления под персонажем.", -- draft
	["Channel tabs, readable lines, a whisper window."] = "Вкладки каналов, читаемые строки, окно шёпота.", -- draft
	["The Plain Chat"] = "Простой чат", -- draft
	["The chat windows as the game has them."] = "Окна чата, как в игре.", -- draft
	["Map Column"] = "Колонка карты", -- draft
	["The minimap as wide as the tracker, its buttons in groups."] = "Мини-карта шириной с отслеживание, её кнопки в группах.", -- draft
	["A buff or food running out: a quiet card."] = "Заканчивается эффект или еда: тихая карточка.", -- draft
	["Small cards: your quest's step, a timer, a count."] = "Маленькие карточки: шаг задания, таймер, счётчик.", -- draft
	["Bags By Kind"] = "Сумки по видам", -- draft
	["One window, sorted by kind, with search."] = "Одно окно, по видам, с поиском.", -- draft
	["Separate Bags"] = "Отдельные сумки", -- draft
	["One window a bag, as the game has them."] = "Окно на каждую сумку, как в игре.", -- draft
	["Short lines beside you: what you loot, receive and buy."] = "Короткие строки рядом: что вы добываете, получаете и покупаете.", -- draft
	["Drink, food, ammunition and reagents: a list to buy at the shop, bought on a click."] = "Питьё, еда, боеприпасы и реагенты: список для магазина, покупка одним щелчком.", -- draft
	["A button that sells or throws away your cheapest junk to free a slot."] = "Кнопка, продающая или выбрасывающая самый дешёвый хлам, чтобы освободить ячейку.", -- draft
	["MelloUI Sounds"] = "Звуки MelloUI", -- draft
