	["Which frames show your group, in your skin. Both can be clicked to heal."] = "Какие рамки показывают вашу группу, в вашем облике. По обоим можно щёлкать для исцеления.", -- draft
	["Your chat window, in your skin."] = "Ваше окно чата, в вашем облике.", -- draft
	["Your bags, in your skin."] = "Ваши сумки, в вашем облике.", -- draft
