-- stale: ["A backdrop round the experience bar (the reputation bar in its place at the top level), merged into one with the other switched-on elements placed next to it (this bar then takes their width, within a limit). Off: no backdrop, and it joins none."] = "Подложка вокруг индикатора опыта (на максимальном уровне на его месте индикатор репутации), сливающаяся в одну с другими включёнными элементами рядом (тогда эта полоса берёт их ширину, в пределах). Выкл.: без подложки, и она ни к чему не присоединяется.", -- draft
-- stale: ["A backdrop round the micro menu, merged into one with the other switched-on elements placed next to it. Off: no backdrop, and it joins none."] = "Подложка вокруг микроменю, сливающаяся в одну с другими включёнными элементами рядом. Выкл.: без подложки, и оно ни к чему не присоединяется.", -- draft
