-- stale: ["A backdrop round the player, target and focus frames: stone behind the portrait, the name and the bars, framed by the red or iron gems of the action bars' backdrops or by one of the border styles of Look > Borders (its inner corners mitred)."] = "Подложка вокруг рамок игрока, цели и фокуса: камень за портретом, именем и полосами в обрамлении красных или железных самоцветов подложек панелей команд или одного из стилей рамок из Облик > Рамки (внутренние углы скошены).", -- draft
-- stale: ["A backdrop round the possess bar, merged into one with the other switched-on elements placed next to it. Off: no backdrop, and it joins none."] = "Подложка вокруг панели контроля разума, сливающаяся в одну с другими включёнными элементами рядом. Выкл.: без подложки, и она ни к чему не присоединяется.", -- draft
-- stale: ["A backdrop round the second status bar (a watched reputation while you level), merged into one with the other switched-on elements placed next to it (this bar then takes their width, within a limit). Off: no backdrop, and it joins none."] = "Подложка вокруг второй полосы состояния (отслеживаемая репутация, пока вы растёте в уровнях), сливающаяся в одну с другими включёнными элементами рядом (тогда эта полоса берёт их ширину, в пределах). Выкл.: без подложки, и она ни к чему не присоединяется.", -- draft
-- stale: ["A backdrop round the stance bar, merged into one with the other switched-on elements placed next to it. Off: no backdrop, and it joins none."] = "Подложка вокруг панели стоек, сливающаяся в одну с другими включёнными элементами рядом. Выкл.: без подложки, и она ни к чему не присоединяется.", -- draft
-- stale: ["A backdrop round the totem bar, merged into one with the other switched-on elements placed next to it. Off: no backdrop, and it joins none."] = "Подложка вокруг панели тотемов, сливающаяся в одну с другими включёнными элементами рядом. Выкл.: без подложки, и она ни к чему не присоединяется.", -- draft
-- stale: ["A batch you craft: which one of how many, a ring for each item, and Stop on hover."] = "Серия, которую вы изготавливаете: какой из скольких, кольцо на каждый предмет и «Стоп» при наведении.", -- draft
-- stale: ["A button on the bag window that frees a slot: it throws away the grey or white junk item worth least (at a vendor it sells it). Never food, drink, potions, scrolls, conjured items, crafting materials, quest items, reagents, ammunition, keys, white gear or anything on your Restock list. A white item asks first."] = "Кнопка на окне сумок, освобождающая ячейку: выбрасывает самый дешёвый серый или белый хлам (у торговца продаёт). Никогда еду, питьё, зелья, свитки, сотворённые предметы, материалы для изготовления, предметы для заданий, реагенты, боеприпасы, ключи, белое снаряжение и ничего из «Списка пополнения». Белый предмет сначала спрашивает.", -- draft
-- stale: ["A class medallion above every party member's friendly nameplate, with a ring in their role's colour. In the open world; inside instances the game keeps friendly nameplates to itself."] = "Медальон класса над дружественным индикатором здоровья каждого участника группы, с кольцом цвета его роли. В открытом мире; в подземельях игра оставляет дружественные индикаторы себе.", -- draft
-- stale: ["A coloured ring around the medallion for the member's assigned role: green healer, blue tank, red damage. Only when the group has roles set (the group finder sets them; a party can set them by hand)."] = "Цветное кольцо вокруг медальона по назначенной участнику роли: зелёный — лекарь, синий — танк, красный — урон. Только если в группе заданы роли (их задаёт поиск группы; группа может задать их вручную).", -- draft
-- stale: ["A cooldown's icon lights up while you press the action button with its spell, as the button does (Action Buttons)."] = "Значок способности светится, пока вы нажимаете кнопку действия с её заклинанием, как и сама кнопка («Кнопки действий»).", -- draft
-- stale: ["A count going up rolls over to its new number as a soft light runs along its line; a finished objective gets a tick drawn in its dash's place; a finished quest's last count rolls first, then a light runs over its title, its mark turns over to the hand-in ? and its turn-in line comes in. Off: the lines change at once, with their dashes. Not with Reduce Motion."] = "Растущий счётчик перекатывается на новое число, пока по строке пробегает мягкий свет; выполненная цель получает галочку на месте тире; у выполненного задания сначала перекатывается последний счётчик, затем свет пробегает по названию, его метка переворачивается в «?» сдачи и появляется строка сдачи. Выкл.: строки меняются сразу, с тире. Не при «Меньше движения».", -- draft
-- stale: ["A critical or crushing blow on you flashes the bars' rim red and dips them a hair, once."] = "Критический или сокрушительный удар по вам один раз вспыхивает красным на ободке полос и чуть опускает их.", -- draft
-- stale: ["A font style is a preset: it changes every font at once. Each card shows its title face and its reading face."] = "Стиль шрифтов — это набор: он меняет все шрифты сразу. Каждая карточка показывает шрифт заголовков и шрифт для чтения.", -- draft
-- stale: ["A group's list slides out from the minimap column like a drawer when you click its button, its rows one after another, and slides back in as it closes. Not with Reduce Motion: then it shows at once."] = "Список группы выезжает из колонки мини-карты, как ящик, когда вы нажимаете её кнопку, строки одна за другой, и заезжает обратно при закрытии. Не при «Меньше движения»: тогда он появляется сразу.", -- draft
-- stale: ["A heal bursts, a heal over time seals onto the portrait, a shield closes round the frame, a resurrection unfolds wings, a group heal runs through the group."] = "Исцеление взрывается, периодическое исцеление запечатывается на портрете, щит смыкается вокруг рамки, воскрешение раскрывает крылья, групповое исцеление проходит по группе.", -- draft
-- stale: ["A heal lights the health it gives at once; the bar then grows into it."] = "Исцеление сразу подсвечивает здоровье, которое даёт; затем полоса дорастает до него.", -- draft
-- stale: ["A line for each item that comes into your bags: loot, quest rewards, crafted items, mail and trades. Moving items between your bags, the bank and your gear never counts."] = "Строка для каждого предмета, попавшего в сумки: добыча, награды за задания, изготовленные предметы, почта и обмен. Перемещение предметов между сумками, банком и снаряжением не считается.", -- draft
-- stale: ["A line for the other currencies you gain (honor, tokens, marks), with the currency's own icon."] = "Строка для других получаемых валют (честь, жетоны, знаки) с собственным значком валюты.", -- draft
-- stale: ["A line for what you buy from a merchant, buybacks too, marked as bought."] = "Строка для купленного у торговца, выкуп тоже, с пометкой «куплено».", -- draft
-- stale: ["A line not translated yet shows in English. Corrections are welcome on MelloUI's CurseForge translation page."] = "Ещё не переведённая строка показывается по-английски. Исправления приветствуются на странице перевода MelloUI на CurseForge.", -- draft
-- stale: ["A line when one of your skills goes up: weapon skills, Defense, professions, secondary skills and languages."] = "Строка, когда растёт один из ваших навыков: владение оружием, защита, профессии, вторичные навыки и языки.", -- draft
-- stale: ["A line when your money goes up: loot, quest rewards, sales, mail and trades, with the game's coins. Several gains in a row add up on one line. Spending makes no line."] = "Строка, когда ваших денег становится больше: добыча, награды за задания, продажи, почта и обмен, с монетами игры. Несколько получений подряд суммируются в одну строку. Траты строку не создают.", -- draft
-- stale: ["A muted knock for the game's red error messages (\"You can't do that yet\"), at most one every half second; none for a message Error Messages hides."] = "Глухой стук для красных сообщений игры об ошибках («Вы пока не можете это сделать.»), не чаще раза в полсекунды; ни одного для сообщения, которое скрывают «Сообщения об ошибках».", -- draft
-- stale: ["A new icon set, sharp at every size, map pins glowing and marks shaded; MelloUI Frames on buttons, XP bars and unit frames; Heal Flight and Frame Effects in soft light."] = "Новый набор значков, чёткий в любом размере, светящиеся метки карты и метки с тенью; рамки MelloUI на кнопках, полосах опыта и рамках; «Эффекты исцеления» и «Эффекты рамок» в мягком свете.", -- draft
-- stale: ["A new installer: your skin first, then each part of the UI step by step, with a picture of every choice."] = "Новый установщик: сначала облик, затем каждая часть интерфейса по шагам, с картинкой каждого выбора.", -- draft
-- stale: ["A new installer: your skin first, then each part; one setup for every skin, fitted to your screen's shape, reloaded when you keep it. Preview: Solo, Party and Raid Fight."] = "Новый установщик: сначала облик, затем каждая часть; одна настройка для всех обликов, подогнанная под форму вашего экрана, перезагрузка при сохранении. Предпросмотр: бой в одиночку, в группе и в рейде.", -- draft
-- stale: ["A new installer: your skin first, then each part; one setup for every skin, reloaded when you keep it. Preview: Solo, Party and Raid Fight."] = "Новый установщик: сначала облик, затем каждая часть; одна настройка для всех обликов, перезагрузка при сохранении. Предпросмотр: бой в одиночку, в группе и в рейде.", -- draft
-- stale: ["A new route grows from you to the destination in about a second instead of appearing whole, on the world map and the minimap at once: the beads pop in one after another, the line and the dashes are drawn with a small light at their head, and the destination's flag pops in as the trail reaches it. A re-plan of the same route (you strayed off it) swaps at once. Not with Reduce Motion."] = "Новый маршрут вырастает от вас до цели примерно за секунду, а не появляется целиком, на карте мира и мини-карте одновременно: бусины появляются одна за другой, линия и штрихи рисуются с маленьким светом впереди, а флаг цели появляется, когда след до него доходит. Перерасчёт того же маршрута (вы сошли с пути) сменяется сразу. Не при «Меньше движения».", -- draft
-- stale: ["A new whisper: the sender in their class colour, the last line and how many are unread. Reply opens their whisper window. Needs Chat's Whisper Popup Window."] = "Новый шёпот: отправитель в цвете класса, последняя строка и сколько непрочитанных. «Ответить» открывает его окно шёпота. Нужно «Всплывающее окно шёпота» чата.", -- draft
-- stale: ["A note under the door for a whisper, two knocks for a group invite."] = "Записка под дверью для шёпота, два стука для приглашения в группу.", -- draft
-- stale: ["A page in the world map's quest log listing the quests of a zone, how many you have completed, and where each one is picked up."] = "Страница в журнале заданий карты мира со списком заданий зоны, сколько вы выполнили и где берётся каждое.", -- draft
-- stale: ["A page lifting when a spell, macro or ability is dragged, the slot latching when it is placed."] = "Поднимающаяся страница, когда перетаскивается заклинание, макрос или способность, защёлкивающаяся ячейка, когда он положен.", -- draft
-- stale: ["A page turn when the character sheet, spell book, quest log or main menu opens, a latch when they close; the spell book's page turns; a quest giver's list and Decline; the bags as a leather pouch opening and closing."] = "Перелистывание страницы при открытии окна персонажа, книги заклинаний, журнала заданий или главного меню, защёлка при закрытии; страницы книги заклинаний; список того, кто даёт задания, и «Отказаться»; сумки как кожаный кошель, который открывается и закрывается.", -- draft
-- stale: ["A pin into parchment for a minimap ping."] = "Булавка в пергамент для сигнала на мини-карте.", -- draft
-- stale: ["A preset: choosing a style changes every font at once -- the titles, the interface text, the chat and numbers, the chat text and the chat on parchment, the sizes back to 100% (each face brings its own size correction) -- each pairing themed with readability first. Fine-tune any of them afterwards (the style then shows Custom). The damage numbers keep their own choice, but for Fredoka's: one face for everything.\nFredoka: MelloUI's own face: Fredoka's round letters for the titles, the text and the damage numbers, to fit MelloUI's icons. The default.\nScriptorium: Cinzel's carved capitals over Alegreya, a warm book face.\nChronicle: Alegreya SC's small capitals over Source Serif 4, the most readable serif.\nOld Tome: IM Fell English's aged print over Spectral.\nWarband: Pirata One's blackletter over Crimson Pro SemiBold: the boldest look.\nClarity: Cinzel titles, Noto Sans everywhere else: the easiest to read at small sizes.\nGothic: Enchanted Land's gothic titles kept, over Alegreya."] = "Набор: выбор стиля меняет все шрифты сразу -- заголовки, текст интерфейса, чат и числа, текст чата и чат на пергаменте, размеры обратно на 100% (каждое начертание несёт свою поправку размера) -- каждая пара подобрана прежде всего для читаемости. Потом настройте любой (стиль тогда покажет «Свой»). Числа урона сохраняют свой выбор, кроме Fredoka: одно начертание для всего.\nFredoka: собственное начертание MelloUI: круглые буквы Fredoka для заголовков, текста и чисел урона, под стать значкам MelloUI. По умолчанию.\nScriptorium: резные прописные Cinzel над Alegreya, тёплым книжным шрифтом.\nChronicle: капитель Alegreya SC над Source Serif 4, самой читаемой антиквой.\nOld Tome: состаренная печать IM Fell English над Spectral.\nWarband: готический шрифт Pirata One над Crimson Pro SemiBold: самый смелый облик.\nClarity: заголовки Cinzel, Noto Sans во всём остальном: легче всего читать в мелком размере.\nGothic: готические заголовки Enchanted Land над Alegreya.", -- draft
-- stale: ["A preview of the bar's layout. Changes show after a /reload."] = "Предпросмотр раскладки панели. Изменения видны после /reload.", -- draft
-- stale: ["A profession cooldown ready again (a transmute, mooncloth, the salt shaker). MelloUI learns it when you open that profession."] = "Время восстановления профессии снова готово (трансмутация, луноткань, солонка). MelloUI узнаёт его, когда вы открываете эту профессию.", -- draft
-- stale: ["A quest ready to turn in says who takes it and where, for example: Turn in: Gryan Stoutmantle, Sentinel Hill."] = "Задание, готовое к сдаче, говорит, кто его примет и где, например: Сдать: Гриан Стаутмантл, Сторожевой холм.", -- draft
-- stale: ["A quest tracker in the game's tracker's place that scrolls with the mouse wheel, so every watched quest can be reached."] = "Отслеживание заданий на месте игрового, прокручиваемое колёсиком мыши, чтобы можно было добраться до каждого отслеживаемого задания.", -- draft
-- stale: ["A quest with a time limit: a ring for its whole time and the time left."] = "Задание с ограничением по времени: кольцо всего времени и оставшееся время.", -- draft
-- stale: ["A rare or rare elite nearby, seen on the minimap, as a nameplate, as your target or under the mouse: its face, its name and how far it is, glowing as it comes up. Click its face to target it (out of combat); Lead Me There shows the way to where the minimap has it."] = "Редкий или редкий элитный враг рядом, замеченный на мини-карте, как индикатор здоровья, как ваша цель или под мышью: его лицо, имя и расстояние, светящиеся при появлении. Нажмите на лицо, чтобы взять его в цель (вне боя); «Отведи меня» показывает путь туда, где его отмечает мини-карта.", -- draft
-- stale: ["A roll in a group: the item in its quality colour, a ring for the time left, and Need, Greed and Pass on hover. The count is the rolls waiting. The game's own roll window stays out of sight meanwhile (with the Gamepad UI it stays)."] = "Розыгрыш в группе: предмет в цвете качества, кольцо оставшегося времени и «Мне это нужно», «Не откажусь» и «Отказаться» при наведении. Число — ожидающие розыгрыши. Окно розыгрыша игры тем временем скрыто (с интерфейсом контроллера остаётся).", -- draft
-- stale: ["A round button by your portrait for errands: supplies low (Restock), new mail, gear to repair, a trainer with something new. Click it to route there. Off, none of the four shows; the Widgets' portrait reminders keep their own switches."] = "Круглая кнопка у вашего портрета для поручений: мало припасов («Пополнение»), новая почта, снаряжение в ремонт, наставник с чем-то новым. Нажмите, чтобы проложить путь. Выкл.: ни одно из четырёх не показывается; напоминания у портрета из «Виджетов» сохраняют свои переключатели.", -- draft
-- stale: ["A row with fewer icons than the others sits centred under them, so the icons grow from the middle. The essential and utility cooldowns and the buff icons."] = "Ряд с меньшим числом значков, чем у других, встаёт по центру под ними, так что значки растут от середины. Основные и вспомогательные способности и значки положительных эффектов.", -- draft
-- stale: ["A seal stamped when you level up."] = "Удар печати при новом уровне.", -- draft
-- stale: ["A seal struck into the record when you level."] = "Печать, оттиснутая в книге, когда вы получаете уровень.", -- draft
-- stale: ["A seamless world map of MelloUI's own (M): zoom from Azeroth to a village, ground and caves up close; your party, Route, flights, dungeons, quests and objectives on it."] = "Собственная бесшовная карта мира MelloUI (M): приближайте от Азерота до деревни, земля и пещеры вблизи; ваша группа, маршрут, полёты, подземелья, задания и цели на ней.", -- draft
-- stale: ["A short chime with each notice: the map's tracking sound for a new destination (left out while the World Marker's own sound plays for it), a softer one when you arrive."] = "Короткий звон с каждым оповещением: звук отслеживания карты для новой цели (пропускается, пока звучит собственный звук мирового маркера), более мягкий, когда вы прибыли.", -- draft
-- stale: ["A short line when a fight starts and when it ends."] = "Короткая строка, когда бой начинается и когда заканчивается.", -- draft
-- stale: ["A shot bar and a melee bar in MelloUI's look in place of the game's swing timers: each swing and shot counted down beside your weapon's icon, the off hand under the main hand, a wand's shots on the melee bar. The game's own swing timers are switched off while this is on, and come back as you had them when it is off. While the Personal Display shows your swing on its rails (Swing On The Rails), these bars step aside."] = "Полоса выстрела и полоса ближнего боя в облике MelloUI вместо таймеров удара игры: каждый удар и выстрел отсчитывается рядом со значком оружия, левая рука под правой, выстрелы жезла на полосе ближнего боя. Таймеры удара игры выключены, пока включено это, и возвращаются в прежнем виде при выключении. Пока личный дисплей показывает ваши удары на своих планках («Удары на планках»), эти полосы уступают место.", -- draft
-- stale: ["A slim beam of light rising from the destination, so the place can be seen from far away, with a small glow on the ground at its foot, red with Red Beads and gold with the other Trail Looks. It fades as you come near and is gone once the marker rises above the place, and hides while the place is off screen. Part of the World Marker."] = "Тонкий луч света, поднимающийся от цели, чтобы место было видно издалека, с небольшим свечением на земле у его основания — красным с «Красными бусинами» и золотым с другими видами следа. Гаснет по мере приближения и исчезает, как только маркер поднимается над местом, и прячется, пока место за пределами экрана. Часть мирового маркера.", -- draft
-- stale: ["A small DPS or healing number on the right of each raid-style or raid frame, beside the health. In a fight, players MelloUI cannot tell apart stay empty until it ends. Point at a frame for all three numbers."] = "Небольшое число DPS или исцеления справа от каждой рамки в стиле рейда или рамки рейда, рядом со здоровьем. В бою игроки, которых MelloUI не может различить, остаются пустыми до конца боя. Наведите на рамку, чтобы увидеть все три числа.", -- draft
-- stale: ["A small coloured FPS and latency readout in the bottom right corner."] = "Небольшой цветной показатель FPS и задержки в правом нижнем углу.", -- draft
-- stale: ["A small flag mark over the destination itself, with the distance and the travel time, that stays on it as you move the camera. Far away it is a beacon, smaller the farther the place, faint while it stands in the middle of the screen; within 100 yards it rises above the place, the distance and the name over it and a gold chevron pointing down to it, so it never covers what you are looking for. Inside a quest's objective area it hides, and comes back when you leave. When the place is off screen, an arrow beside your character points the way to turn. Takes the place of the game's own destination marker while it is on."] = "Небольшая метка-флаг над самой целью с расстоянием и временем в пути, остающаяся на ней при движении камеры. Издалека это маяк, тем меньше, чем дальше место, бледный, пока он в центре экрана; ближе 100 метров он поднимается над местом, с расстоянием и названием над ним и золотым шевроном, указывающим вниз, чтобы никогда не закрывать то, что вы ищете. В области цели задания прячется и возвращается, когда вы выходите. Когда место за пределами экрана, стрелка рядом с персонажем показывает, куда повернуть. Заменяет собственный маркер цели игры, пока включено.", -- draft
-- stale: ["A small gem in the top-left corner of every item in your bags, the bank and the guild bank, in the colour of the item's quality: grey for junk, white for common, then green, blue, purple and orange. Junk and better items stand out at a glance. While the game shows its own mark in that corner (the junk coin at a merchant, the upgrade arrow, the exclamation mark on an item that starts a quest, the quality badge on a crafting reagent), the gem moves to the top-right corner. One switch for all three windows."] = "Маленький самоцвет в левом верхнем углу каждого предмета в ваших сумках, банке и банке гильдии, цвета качества предмета: серый для хлама, белый для обычных, затем зелёный, синий, фиолетовый и оранжевый. Хлам и лучшие предметы видны с первого взгляда. Пока игра показывает в этом углу свою метку (монету хлама у торговца, стрелку улучшения, восклицательный знак на предмете, начинающем задание, значок качества реагента), самоцвет переходит в правый верхний угол. Один переключатель для всех трёх окон.", -- draft
-- stale: ["A soft breath of air as the World Marker changes: when it comes up for a new destination, as it rises above the place you are near, and as it turns back into the beacon when you walk away. For a new destination it is the one sound: the tracking notice leaves its chime out then. Plays on the Sound Effects channel. Part of the World Marker."] = "Мягкий выдох воздуха, когда меняется мировой маркер: когда он появляется для новой цели, когда поднимается над местом, рядом с которым вы, и когда снова становится маяком, когда вы уходите. Для новой цели это единственный звук: оповещение об отслеживании тогда не звенит. Играет в канале «Звуковые эффекты». Часть мирового маркера.", -- draft
-- stale: ["A soft dark shade behind the text MelloUI shows on the world, so it reads on bright ground: the zone name when you enter a new area (with its subzone and PvP lines), the game's messages in the middle of the screen (red errors, yellow quest progress, raid warnings and boss emotes), the Route's World Marker, the names on the unit frames (yours, your pet's, your targets' targets' and the party's) and on the nameplates, and the channel tags and links on the chat's parchment. No outline on the zone name and the messages (Outlined Text adds it back); the game's colours stay. Off: the game's own look, and no shade behind any of them."] = "Мягкая тёмная тень за текстом, который MelloUI показывает поверх мира, чтобы он читался на светлом фоне: название зоны при входе в новую область (со строками подзоны и PvP), сообщения игры в центре экрана (красные ошибки, жёлтый ход заданий, предупреждения рейда и эмоции боссов), мировой маркер маршрута, имена на рамках (ваше, питомца, целей ваших целей и группы) и на индикаторах здоровья, а также метки каналов и ссылки на пергаменте чата. Без контура на названии зоны и сообщениях («Текст с контуром» возвращает его); цвета игры остаются. Выкл.: облик игры и никакой тени ни за чем.", -- draft
-- stale: ["A soft dark shade round the kit's outlines, so windows, bars and frames stand out from the world. Each area has its own switch under it."] = "Мягкая тёмная тень вокруг контуров набора, чтобы окна, полосы и рамки выделялись на фоне мира. У каждой области свой переключатель ниже.", -- draft
-- stale: ["A soft glow in the debuff's colour (Magic blue, Curse purple, Disease brown, Poison green) round a friend's frame while they have a debuff that can be removed. On the raid frames the border takes the colour too."] = "Мягкое свечение цвета эффекта (магия — синий, проклятие — фиолетовый, болезнь — коричневый, яд — зелёный) вокруг рамки союзника, пока на нём эффект, который можно снять. На рамках рейда цвет принимает и рамка.", -- draft
-- stale: ["A soft gold glow bursts round your target's bar on a critical hit."] = "Мягкое золотое сияние вспыхивает вокруг полосы вашей цели при критическом ударе.", -- draft
-- stale: ["A thinner bar under the melee bar for your off-hand weapon's swings, while you carry one."] = "Более тонкая полоса под полосой ближнего боя для ударов оружием в левой руке, пока оно у вас есть.", -- draft
-- stale: ["A tiny tick when the mouse reaches a button. The game has no hover sound; this is an addition."] = "Крохотный тик, когда мышь доходит до кнопки. У игры нет звука наведения; это дополнение.", -- draft
-- stale: ["A unit's tooltip in colours that tell you at a glance: the guild green, Alliance blue and Horde red, the level line in the colour of how hard the unit is for you, a quest's title gold and its objectives cream while still to do, green once done."] = "Подсказка юнита в цветах, понятных с одного взгляда: гильдия зелёным, Альянс синим, Орда красным, строка уровня в цвете того, насколько юнит для вас сложен, название задания золотом, а его цели кремовым, пока не выполнены, и зелёным после.", -- draft
-- stale: ["A whisper opens a small window of its own, one per person, with the conversation and a box to answer in, instead of a new chat tab. Whispers still show in the main chat. Switching it off puts the game's own whisper setting back."] = "Шёпот открывает маленькое собственное окно, по одному на человека, с разговором и полем для ответа, вместо новой вкладки чата. Шёпот по-прежнему виден в основном чате. Выключение возвращает собственный параметр шёпота игры.", -- draft
-- stale: ["A ½ button at the left end of the split box's amount: click it and the amount is half the stack (191 makes 95). Buying in bundles at a merchant, it rounds down to whole bundles."] = "Кнопка ½ у левого края количества в окне разделения: нажмите её, и количество станет половиной стопки (191 даёт 95). При покупке пачками у торговца округляет вниз до целых пачек.", -- draft
-- stale: ["Abilities that light up (Overpower!), auras you gain or lose, interrupts and dispels."] = "Загорающиеся способности («Превосходство!»), получаемые и теряемые эффекты, прерывания и рассеивания.", -- draft
