-- stale: ["Accept a quest as soon as its giver shows it, and open a giver's only quest from its list. Grey, repeatable, daily and ignored quests are left to you, and so is an escort's or a shared quest's question."] = "Принимает задание, как только его показывает тот, кто его даёт, и открывает единственное задание из его списка. Серые, повторяемые, ежедневные и игнорируемые задания остаются за вами, как и вопрос сопровождения или общего задания.", -- draft
-- stale: ["Action Bar 1 without the game's bar art (its frame, dividers and the art of empty slots), like the other bars: MelloUI ticks Edit Mode's own Hide Bar Art for it. Only on your own Edit Mode layouts: a preset such as Modern can't be changed. Shows after a /reload. Off: the art back on the layouts MelloUI changed (or set it yourself in Edit Mode)."] = "Панель команд 1 без оформления игры (рамка, разделители и оформление пустых ячеек), как и другие панели: MelloUI ставит для неё флажок «Скрыть оформление панели» режима редактирования. Только в ваших собственных раскладках режима редактирования: готовую раскладку вроде «Современной» изменить нельзя. Видно после /reload. Выкл.: оформление возвращается в раскладках, которые изменил MelloUI (или задайте это сами в режиме редактирования).", -- draft
-- stale: ["Action Bar 1. Its keys work while it is faded. Always: never faded. In Combat: faded out of combat, back in a fight. On Mouseover: faded all the time, shown while you point at it."] = "Панель команд 1. Её клавиши работают, пока она погашена. «Всегда»: никогда не гаснет. «В бою»: гаснет вне боя, возвращается в бою. «При наведении»: погашена всё время, видна, пока вы на неё указываете.", -- draft
-- stale: ["Action bars and minimap: backdrops and MelloUI's square minimap for everyone, no painted skin needed; the round painted map is Oldschool's."] = "Панели команд и мини-карта: подложки и квадратная мини-карта MelloUI для всех, без рисованного облика; круглая рисованная карта — в Oldschool.", -- draft
-- stale: ["Action bars, stance and pet bars, micro menu, bag bar, experience and reputation bars in the kit."] = "Панели команд, стоек и питомца, микроменю, панель сумок, индикаторы опыта и репутации в наборе.", -- draft
-- stale: ["Action, pet, stance and flyout buttons."] = "Кнопки действий, питомца, стоек и выпадающих меню.", -- draft
-- stale: ["After a fight, for a few seconds in the widget column (longer while you point at it): won or lost and its length, your damage, DPS and rank, the ring your share of the group. The pointer on it shows the top five; a click opens the fight in the Fight History."] = "После боя, на несколько секунд в колонке виджетов (дольше, пока вы на него указываете): победа или поражение и длительность, ваш урон, DPS и место, кольцо — ваша доля в группе. Указатель на нём показывает пятёрку лучших; щелчок открывает бой в «Истории боёв».", -- draft
-- stale: ["After a quest offer, and after the description the quest log's Read button reads, play the quest's objectives when the voice pack (MelloUI_VoicePack) has them recorded: the Forever Narrator reads them. Text-to-speech never reads the objectives or their counts."] = "После предложения задания и после описания, которое читает кнопка «Читать» журнала заданий, проигрывает цели задания, если пакет голосов (MelloUI_VoicePack) их записал: их читает Forever Narrator. Синтез речи никогда не читает цели и их счётчики.", -- draft
-- stale: ["All action bar buttons, the stance bar, pet bar, possess bar and extra action button."] = "Все кнопки панелей команд, панель стоек, панель питомца, панель контроля разума и дополнительная кнопка действия.", -- draft
-- stale: ["All features"] = "Все функции", -- draft
-- stale: ["All set"] = "Всё готово", -- draft
-- stale: ["All your empty slots as one slot with their count (drop an item on it to put it in a free slot). Off: every empty slot shows."] = "Все пустые ячейки как одна с их числом (бросьте на неё предмет, чтобы положить его в свободную ячейку). Выкл.: видна каждая пустая ячейка.", -- draft
-- stale: ["Also darken the gryphons / end caps and border art of the main action bar."] = "Затемняет также грифонов / края и оформление рамки главной панели команд.", -- draft
-- stale: ["Also list quests only the other faction can take."] = "Показывает и задания, которые может взять только другая фракция.", -- draft
-- stale: ["Also list quests restricted to classes other than yours."] = "Показывает и задания только для других классов.", -- draft
-- stale: ["Also mark givers whose quests you have all completed, with a grey tick."] = "Отмечает и тех, чьи задания вы выполнили все, серой галочкой.", -- draft
-- stale: ["Also remove the square brackets around the short channel tags."] = "Убирает и квадратные скобки вокруг коротких меток каналов.", -- draft
-- stale: ["Also show a round button on the minimap's edge that opens the list of the nearest services; drag it to move it, right-click it to stop the route. /services opens the same list."] = "Также показывает круглую кнопку на краю мини-карты, открывающую список ближайших услуг; перетащите её, чтобы переместить, правый щелчок останавливает маршрут. /services открывает тот же список.", -- draft
-- stale: ["Also show junk (grey) items. Off: they are left out."] = "Показывает и хлам (серый). Выкл.: он не показывается.", -- draft
-- stale: ["Also show the text being read under the line, page by page as the voice goes on."] = "Также показывает читаемый текст под строкой, страница за страницей по ходу голоса.", -- draft
-- stale: ["Also show the world server latency next to the home latency."] = "Показывает задержку сервера мира рядом с домашней задержкой.", -- draft
-- stale: ["An action's icon turns red while your target is out of its range, deep blue while you lack the mana (or other resource) for it, and grey while it cannot be used. Its key already turns red out of range."] = "Значок действия краснеет, пока цель вне досягаемости, становится тёмно-синим, пока не хватает маны (или другого ресурса), и серым, пока действие нельзя использовать. Его клавиша и так краснеет вне досягаемости.", -- draft
-- stale: ["An arrow beside the backpack folds the bag slots away so only the backpack shows; click it again to bring them back. While you hold an item they come out by themselves, so a new bag can be dropped into a slot. The game remembers which way you left it."] = "Стрелка рядом с рюкзаком сворачивает ячейки сумок, оставляя только рюкзак; нажмите снова, чтобы вернуть их. Пока вы держите предмет, они выходят сами, чтобы новую сумку можно было положить в ячейку. Игра помнит, как вы её оставили.", -- draft
-- stale: ["An enemy's health bar turns purple once its health is below the percentage set here, on the target, focus, target-of-target and boss frames and on nameplates, so you see when finishing moves can be used. Works in combat, when the game hides the exact health, and with every health bar colour."] = "Полоса здоровья врага становится фиолетовой, когда его здоровье опускается ниже заданного здесь процента, на рамках цели, фокуса, цели цели и боссов и на индикаторах здоровья, чтобы вы видели, когда можно добивать. Работает в бою, когда игра скрывает точное здоровье, и с любым цветом полосы здоровья.", -- draft
-- stale: ["An iron pin into the parchment for a minimap ping."] = "Железная булавка в пергамент для сигнала на мини-карте.", -- draft
-- stale: ["An iron sight catching when a target is selected, a latch releasing when it is lost."] = "Защёлкивающийся железный прицел при выборе цели, отпущенная защёлка при её потере.", -- draft
-- stale: ["An item picked up, moved between slots, put down or looted; a rare or better item has its own sound. Silences the game's own pick-up and put-down sounds (the Equipment and Vendor sounds rely on that, and play only while this is on)."] = "Предмет поднят, перемещён между ячейками, положен или добыт; у редкого или лучше — свой звук. Глушит звуки игры при взятии и укладке (от этого зависят звуки «Снаряжения» и «Торговца», они играют только пока это включено).", -- draft
-- stale: ["An item you loot flies from where you picked it up into its slot in your bag window (with the bags closed, onto the bag button) and lands with a light across it. The rarer it is, the more it does: green leaves a streak, blue bursts into rays and lands in a ring, purple throws sparks and a shockwave, and a legendary rises in a pillar of light, flashes your bag window's border and says its name on the screen. Turning in a quest, its reward item flies the same way, and its money flies as coins into the bag window's money, which counts up as they land; coins you loot fly in the same way while the bag window is open. Only loot and quest rewards, never what you buy, craft or take from the mail. Not with Reduce Motion."] = "Добытый предмет летит оттуда, где вы его подняли, в свою ячейку в окне сумок (при закрытых сумках — на кнопку сумки) и приземляется со светом поперёк. Чем он реже, тем больше эффект: зелёный оставляет след, синий взрывается лучами и садится в кольцо, фиолетовый бросает искры и ударную волну, а легендарный поднимается в столбе света, заставляет вспыхнуть рамку окна сумок и называет своё имя на экране. При сдаче задания предмет награды летит так же, а деньги летят монетами в деньги окна сумок, которые прибавляются по мере приземления; добытые монеты летят так же, пока окно сумок открыто. Только добыча и награды за задания, никогда не купленное, изготовленное или взятое с почты. Не при «Меньше движения».", -- draft
-- stale: ["An upright bar beside your character for every shield on you added up, as the game counts them: spells (Power Word: Shield, Ice Barrier, Mana Shield, the wards), talents and items, the ones against one kind of damage too. Each shield is its own part, in its school's colour (Power Word: Shield gold, Ice Barrier frost, Mana Shield arcane, a Fire Protection Potion fire), stacked in the order they went up, its icon beside the column. It fills when one goes up, drains as it takes the hits, turns amber when low and breaks when the last one is gone; one ending while another holds only takes its part away. Edit Layout places it."] = "Вертикальная полоса рядом с персонажем для всех щитов на вас, сложенных так, как их считает игра: заклинания («Слово силы: Щит», «Ледяная преграда», «Щит маны», обереги), таланты и предметы, в том числе против одного вида урона. Каждый щит — своя часть в цвете своей школы («Слово силы: Щит» золотой, «Ледяная преграда» ледяной, «Щит маны» тайной магии, зелье защиты от огня огненный), сложенные в порядке появления, со значком рядом с колонкой. Заполняется, когда поднимается щит, убывает по мере принятия ударов, становится янтарной, когда его мало, и разбивается, когда исчезает последний; закончившийся щит, пока держится другой, убирает только свою часть. Место задаётся в «Изменить раскладку».", -- draft
-- stale: ["Another action is in progress, can't do that while moving, while stunned or while mounted."] = "Выполняется другое действие, нельзя в движении, под оглушением или верхом.", -- draft
-- stale: ["Anyone's"] = "Любые", -- draft
-- stale: ["As a ghost: how far your body is and which way, and a ring until you can come back. Click it for the way there; at your body, Resurrect. The game's own Resurrect popup is see-through and click-through meanwhile."] = "В облике духа: как далеко ваше тело и в какой стороне, и кольцо, пока нельзя вернуться. Нажмите, чтобы увидеть путь; у тела — «Воскрешение». Окно воскрешения игры тем временем прозрачно и пропускает щелчки.", -- draft
-- stale: ["As you arrive, the place is put out: the World Marker's mark sinks onto it in a ring of light with a few sparks. Not with Reduce Motion."] = "Когда вы прибываете, место гаснет: метка мирового маркера опускается на него в кольце света с парой искр. Не при «Меньше движения».", -- draft
-- stale: ["At a flight master: where your route flies to, on the flight map's title band, with a bead of your trail on that flight point. Pointing at a flight point also shows about how long the flight takes."] = "У распорядителя полётов: куда летит ваш маршрут, на полосе заголовка карты полётов, с бусиной следа на этой точке полёта. Наведение на точку полёта показывает и примерное время полёта.", -- draft
-- stale: ["At a merchant who sells what you are low on, a small list beside the shop window: each item, how many and the price, and the total. Nothing is bought until you click Buy."] = "У торговца, который продаёт то, чего у вас мало, небольшой список рядом с окном торговца: каждый предмет, сколько и цена, и итог. Ничего не покупается, пока вы не нажмёте «Купить».", -- draft
