-- stale: ["Chat tab names are invisible until the mouse is over the chat. Tabs flashing with new whispers stay visible. It adds to the Fader's Chat fade: both fade the tabs, so with both on the two fades multiply. Does nothing under the painted chat (its Painted Skin, the reskin on), which keeps its tabs shown."] = "Названия вкладок чата не видны, пока мышь не над чатом. Вкладки, мигающие от нового шёпота, остаются видимыми. Добавляется к угасанию чата в «Угасании»: оба гасят вкладки, так что при обоих включённых угасания перемножаются. Ничего не делает под рисованным чатом (его рисованный облик, облик включён), который держит вкладки видимыми.", -- draft
