-- stale: ["Draw the nearby part of the route on the minimap."] = "Рисует ближайшую часть маршрута на мини-карте.", -- draft
-- stale: ["Draw the route to the waypoint on the world map, and its destination as a flag in a gold ring. A stretch where no road is known is a paler, straight guess."] = "Рисует маршрут к путевой точке на карте мира и цель — флагом в золотом кольце. Участок без известной дороги — более бледная прямая догадка.", -- draft
-- stale: ["Draw the text MelloUI shows on the world with an outline: the on-screen notice's lines, Combat Text's lines and the Gains lines, and, while Text Shade is on, the zone text and the game's messages in the middle of the screen. Off: soft text on a dark shade."] = "Рисует с контуром текст, который MelloUI показывает поверх мира: строки оповещения на экране, строки «Текста боя» и строки получения, а пока включена «Тень текста» — ещё текст зоны и сообщения игры в центре экрана. Выкл.: мягкий текст на тёмной тени.", -- draft
-- stale: ["Draws the way to your map waypoint on the world map and the minimap, along roads you have walked before."] = "Рисует путь к путевой точке на карте мира и мини-карте по дорогам, по которым вы уже ходили.", -- draft
-- stale: ["Dungeon Info: every dungeon and raid, its bosses in order and what each one drops. Open it with the door button over the map, a dungeon's door on it, or /dungeoninfo."] = "Сведения о подземельях: каждое подземелье и рейд, боссы по порядку и их добыча. Открываются кнопкой двери над картой, дверью подземелья на ней или /dungeoninfo.", -- draft
-- stale: ["Each frame's height (the game's raid frame: 36)."] = "Высота каждой рамки (рамка рейда игры: 36).", -- draft
-- stale: ["Each frame's width (the game's raid frame: 72)."] = "Ширина каждой рамки (рамка рейда игры: 72).", -- draft
-- stale: ["Edit Layout, bags and groups: more windows move without the reskin; quality gems and junk on every slot; party and raid frames keep their own places and indicators."] = "«Изменить раскладку», сумки и группы: больше окон двигается без рисованного облика; самоцветы качества и хлам в каждой ячейке; рамки группы и рейда хранят свои места и индикаторы.", -- draft
-- stale: ["Edit Layout: a dock at the top, the Elements list to show, hide, lock or single out any part, and the game's Edit Mode settings in each part's box."] = "«Изменить раскладку»: док сверху, список элементов, чтобы показать, скрыть, закрепить или выделить любую часть, и настройки режима редактирования игры в окне каждой части.", -- draft
-- stale: ["Edit Layout: attach the game's elements to each other, as in Edit Mode."] = "Изменить раскладку: прикрепляйте элементы игры друг к другу, как в режиме редактирования.", -- draft
-- stale: ["Edit Mode already keeps %d account layouts, the most it can. Delete one in Edit Mode, or switch the layout off on the Screen step."] = "В режиме редактирования уже хранится %d раскладок учётной записи — максимум. Удалите одну в режиме редактирования или выключите раскладку на шаге «Экран».", -- draft
-- stale: ["Elites, rares, rare elites and bosses stand out: a metal line over the name with a crest on it. Gold with a crown and wings for an elite, silver with a star for a rare, silver with a gold star and wings for a rare elite, and red-bronze scrollwork with a skull, winged at both ends, for a boss. The plate itself keeps its look."] = "Элита, редкие, редкие элитные и боссы выделяются: металлическая линия над именем с гербом. Золото с короной и крыльями для элиты, серебро со звездой для редкого, серебро с золотой звездой и крыльями для редкого элитного и красно-бронзовые завитки с черепом, крылатые с обоих концов, для босса. Сама табличка сохраняет свой облик.", -- draft
-- stale: ["Every MelloUI animation ends at once: windows open without fading, the whisper popup appears in place, the quest tracker's lines do not flash, the configurator jumps instead of gliding. For anyone who finds moving interface parts distracting. Works with UI Modifications switched off as well."] = "Каждая анимация MelloUI заканчивается сразу: окна открываются без затухания, окно шёпота появляется на месте, строки отслеживания заданий не мигают, конфигуратор переключается без скольжения. Для тех, кого отвлекают движущиеся части интерфейса. Работает и при выключенных изменениях интерфейса.", -- draft
-- stale: ["Every action button in MelloUI's frame: a dark iron rim with a gold line, brighter under the pointer, bright gold while its aura or stance is on, red out of range, a dark slot when the button is empty. Off: the game's own frames. The painted skin's bars keep their own (Oldschool)."] = "Каждая кнопка действия в рамке MelloUI: тёмный железный ободок с золотой линией, светлее под указателем, ярко-золотой, пока её аура или стойка активна, красный вне досягаемости, тёмная ячейка, когда кнопка пуста. Выкл.: рамки игры. Полосы рисованного облика сохраняют своё (Oldschool).", -- draft
-- stale: ["Every element on the Frames, Bars and Chat & Map tabs on Always: nothing fades."] = "Каждый элемент вкладок «Рамки», «Панели» и «Чат и карта» на «Всегда»: ничего не гаснет.", -- draft
-- stale: ["Every element on the Frames, Bars and Chat & Map tabs on In Combat: the whole interface fades away out of combat and comes back in a fight."] = "Каждый элемент вкладок «Рамки», «Панели» и «Чат и карта» на «В бою»: весь интерфейс гаснет вне боя и возвращается в бою.", -- draft
-- stale: ["Every feature below on or off at once."] = "Все функции ниже включены или выключены сразу.", -- draft
-- stale: ["Every font drawn with the interface face, relative to its normal size; a Font Style puts it back to 100% (its faces bring their own correction). Not the text with a size of its own: the Quest Tracker, Combat Text, the chat (Chat & numbers size), FPS / Latency, Cooldown Timers, and the bar values while their size is set."] = "Каждый шрифт, нарисованный начертанием интерфейса, относительно его обычного размера; стиль шрифтов возвращает его на 100% (его начертания несут свою поправку). Не текст со своим размером: отслеживание заданий, «Текст боя», чат (размер «Чата и чисел»), FPS / задержка, таймеры восстановления и значения на полосах, пока их размер задан.", -- draft
-- stale: ["Every setting lives in /mello, and in the MelloUI button of the game menu."] = "Все настройки — в /mello и в кнопке MelloUI меню игры.", -- draft
-- stale: ["Every window and HUD area of the reskin back on, and every feature of UI Modifications that is on by default."] = "Снова включает каждую область окон и HUD облика и каждую функцию изменений интерфейса, включённую по умолчанию.", -- draft
-- stale: ["Every window fades in over a fifth of a second when it opens, instead of appearing at once: the character window, talents and spells, professions, the bags, social, guild, group finder, collections, the map, the game menu and the rest. Works with the reskin on or off. Reduce Motion: at once."] = "Каждое окно плавно появляется за пятую долю секунды при открытии, а не сразу: окно персонажа, таланты и заклинания, профессии, сумки, общение, гильдия, поиск группы, коллекции, карта, меню игры и остальные. Работает с включённым или выключенным обликом. «Меньше движения»: сразу.", -- draft
-- stale: ["Everything off. Set it up step by step."] = "Всё выключено. Настройте шаг за шагом.", -- draft
-- stale: ["Facing the wrong way, target needs to be in front of you, no target, invalid target, target not in line of sight."] = "Вы смотрите не туда, цель должна быть перед вами, нет цели, неверная цель, цель вне поля зрения.", -- draft
-- stale: ["Fade parts of the interface away while you do not need them: out of combat, or until you point at them. Pick for each frame, bar, the chat, the minimap and the trackers."] = "Скрывает части интерфейса, пока они вам не нужны: вне боя или пока вы на них не укажете. Выбирается для каждой рамки, панели, чата, мини-карты и отслеживания.", -- draft
