-- stale: ["Golden glints over the ore vein you walk up to (the game's soft targeting picks the nearest one, within about 15 yards): dim out of reach, bright once you can mine it, grey when your skill is too low."] = "Золотые блики на рудной жиле, к которой вы подходите (мягкий выбор цели игры берёт ближайшую, примерно в 15 метрах): тусклые вне досягаемости, яркие, как только её можно добыть, серые, если навык слишком низок.", -- draft
-- stale: ["Grey iron, bright red"] = "Серое железо, ярко-красный", -- draft
