-- stale: ["Hide the backpack and bag slot buttons. Still shown while Edit Mode is open. Bags can still be opened with their keybinds."] = "Скрывает кнопки рюкзака и ячеек сумок. По-прежнему видно, пока открыт режим редактирования. Сумки по-прежнему открываются своими клавишами.", -- draft
