-- stale: ["Hide the health bar under unit tooltips (on by default). Bar Texture and Class / Reaction Health Colour only matter while the bar is shown."] = "Скрывает полосу здоровья под подсказками юнитов (по умолчанию вкл.). «Текстура полос» и «Цвет здоровья по классу / отношению» важны, только пока полоса видна.", -- draft
