-- stale: ["Hide the red flash around the player, target, focus, pet and party frames while in combat or when a target attacks."] = "Скрывает красную вспышку вокруг рамок игрока, цели, фокуса, питомца и группы в бою или когда цель атакует.", -- draft
-- stale: ["Hide the row of menu buttons (character, spellbook, talents, ...). Still shown while Edit Mode is open."] = "Скрывает ряд кнопок меню (персонаж, книга заклинаний, таланты, ...). По-прежнему видно, пока открыт режим редактирования.", -- draft
-- stale: ["Hides the main bar's art, like the other bars. Only on your own Edit Mode layouts, not the presets; shows after a /reload."] = "Скрывает графику главной панели, как у других панелей. Только в ваших раскладках режима редактирования, не в готовых; видно после /reload.", -- draft
-- stale: ["Hides the red error messages you choose (not enough energy, not ready yet, out of range...) from the middle of the screen."] = "Скрывает из центра экрана выбранные вами красные сообщения об ошибках (недостаточно энергии, ещё не готово, слишком далеко...).", -- draft
-- stale: ["Hides the red flash around unit frames in combat."] = "Скрывает красную вспышку вокруг рамок юнитов в бою.", -- draft
-- stale: ["Hold it as you talk to a giver to see its dialog as usual: nothing is accepted or handed in there."] = "Удерживайте её, разговаривая с тем, кто даёт задание, чтобы увидеть диалог как обычно: там ничего не принимается и не сдаётся.", -- draft
-- stale: ["Home latency in milliseconds."] = "Домашняя задержка в миллисекундах.", -- draft
-- stale: ["How a character's name is written, everywhere at once: the player, target, focus, pet, party and raid frames, the nameplates, the chat and whisper windows, and the name over your own head (the game's own setting for it: only First name leaves out the surname there). A character with no surname shows the name it has; in the chat the name is still a link to the player. Names over other players' heads without a nameplate are the engine's and have no setting."] = "Как пишется имя персонажа, везде сразу: рамки игрока, цели, фокуса, питомца, группы и рейда, индикаторы здоровья, окна чата и шёпота и имя над вашей головой (собственная настройка игры: фамилию там опускает только «Имя»). Персонаж без фамилии показывает то имя, что есть; в чате имя по-прежнему ссылка на игрока. Имена над другими игроками без индикатора здоровья рисует движок, настройки для них нет.", -- draft
-- stale: ["How big the Big Cooldowns' icons above the health bar are. Their seconds keep the display's text size."] = "Насколько велики значки «Крупных способностей» над полосой здоровья. Их секунды сохраняют размер текста дисплея.", -- draft
-- stale: ["How big the item slots are (37 is the game's own size)."] = "Насколько велики ячейки предметов (37 — размер игры).", -- draft
-- stale: ["How big the route's beads, line or dashes are on the world map and the minimap."] = "Насколько велики бусины, линия или штрихи маршрута на карте мира и мини-карте.", -- draft
-- stale: ["How bright the game's own artwork is where Dark Mode darkens it (the parts the reskin does not cover, or everything with the reskin off). Lower values are darker. The reskin's own art has Reskin Brightness below."] = "Насколько ярко собственное оформление игры там, где его затемняет тёмный режим (части, которые облик не закрывает, или всё при выключенном облике). Меньшие значения темнее. У графики облика своя «Яркость облика» ниже.", -- draft
-- stale: ["How bright the game's own artwork is where Dark mode darkens it. Lower is darker."] = "Насколько ярко оформление игры там, где его затемняет тёмный режим. Меньше — темнее.", -- draft
-- stale: ["How bright the painted reskin is while Dark Mode is on: every kit piece (stone, iron, plates, brackets) is darkened by this much; the red gems keep their colour. The default art above is darkened where the reskin is off."] = "Насколько ярок рисованный облик при включённом тёмном режиме: каждая часть набора (камень, железо, таблички, скобы) затемняется на столько; красные самоцветы сохраняют цвет. Стандартное оформление выше затемняется там, где облик выключен.", -- draft
-- stale: ["How dark the UI Shade round the kit's outlines is, the nameplates' Whole plate shade too. The bands behind unit frame and nameplate names keep their own."] = "Насколько темна тень интерфейса вокруг контуров набора, также тень «Вся табличка» индикаторов здоровья. Полосы за именами на рамках и индикаторах здоровья сохраняют свою.", -- draft
-- stale: ["How far a member too far away for your heals fades. 100%: no fade."] = "Насколько гаснет участник, слишком далёкий для вашего исцеления. 100%: не гаснет.", -- draft
-- stale: ["How far each quest is, beside its name: its objectives, or the one who takes it once it is done. The quest you follow shows the way along its route. Needs Route."] = "Как далеко каждое задание, рядом с названием: его цели или тот, кто его примет, когда оно выполнено. Отслеживаемое вами задание показывает путь по своему маршруту. Нужен «Маршрут».", -- draft
-- stale: ["How far from your character the damage and healing lanes run, left and right. Move the whole text in Edit Layout."] = "Насколько далеко от персонажа идут дорожки урона и исцеления, влево и вправо. Весь текст двигается в «Изменить раскладку».", -- draft
-- stale: ["How far under the minimap the buttons sit. Not used while they are merged into the square minimap's frame."] = "Насколько ниже мини-карты стоят кнопки. Не используется, пока они слиты с рамкой квадратной мини-карты.", -- draft
-- stale: ["How fast text-to-speech reads; 0 is the voice's normal pace. Recorded lines always play at their own pace."] = "Насколько быстро читает синтез речи; 0 — обычный темп голоса. Записанные строки всегда играют в своём темпе.", -- draft
-- stale: ["How long a new reminder stays before it tucks itself away. It stays while your pointer is on it."] = "Сколько новое напоминание остаётся, прежде чем спрятаться. Остаётся, пока на нём указатель.", -- draft
-- stale: ["How long an element waits before it fades: after a fight ends, after you let go of your target or point away."] = "Сколько элемент ждёт, прежде чем погаснуть: после конца боя, после того как вы сбросили цель или отвели указатель.", -- draft
-- stale: ["How long an item stays under Recent: until you close your bags, only until you point at it (it moves to its own kind as the pointer leaves it), or for 5 minutes after you got it."] = "Сколько предмет остаётся в «Недавнем»: пока вы не закроете сумки, только пока вы на него не укажете (уходит в свой вид, когда указатель уходит), или 5 минут после получения.", -- draft
-- stale: ["How long each line stays before it fades. Gaining the same skill or item again adds to its line and starts it over."] = "Сколько каждая строка остаётся, прежде чем погаснуть. Повторное получение того же навыка или предмета добавляется к его строке и запускает её заново.", -- draft
-- stale: ["How long the fade itself takes. Coming back is always quick. Reduce Motion: at once."] = "Сколько длится само угасание. Возвращение всегда быстрое. «Меньше движения»: сразу.", -- draft
-- stale: ["How long the tooltip of a creature or an object stays fully visible after your cursor leaves it, before it fades out (the fade itself takes a quarter of a second)."] = "Сколько подсказка существа или объекта остаётся полностью видимой после ухода курсора, прежде чем погаснуть (само угасание занимает четверть секунды).", -- draft
-- stale: ["How loud text-to-speech reads. Recorded lines follow the Sound Channel's volume in the game's sound settings."] = "Насколько громко читает синтез речи. Записанные строки следуют громкости «Звукового канала» в параметрах звука игры.", -- draft
-- stale: ["How many buffs stand in a row before the next row starts. Your debuffs start a row of their own (the game's debuff bar takes at most 16 in a row)."] = "Сколько положительных эффектов помещается в ряд, прежде чем начнётся следующий. Ваши отрицательные эффекты начинают свой ряд (панель отрицательных эффектов игры вмещает не больше 16 в ряд).", -- draft
-- stale: ["How many fights the history keeps, the oldest dropped first. Kept over a /reload; a new login starts it empty."] = "Сколько боёв хранит история; старейший удаляется первым. Сохраняется после /reload; новый вход в игру начинает её пустой.", -- draft
-- stale: ["How many frames in a column (or a row) before the next one starts. 5 lines the raid up by its groups."] = "Сколько рамок в столбце (или ряду), прежде чем начнётся следующий. 5 выстраивает рейд по группам.", -- draft
-- stale: ["How many rows the bar's buttons stand in (columns, on a bar stood upright in Edit Mode)."] = "Во сколько рядов стоят кнопки панели (столбцов, если панель поставлена вертикально в режиме редактирования).", -- draft
-- stale: ["How many slots across the bag window is: more makes it wider and shorter."] = "Сколько ячеек в ширину у окна сумок: больше — шире и ниже.", -- draft
-- stale: ["How many widgets the column shows at once. The rest wait in a slim \"+2 more\" row on top; a click there lists them. Loot rolls, summons, resurrect offers and ready checks always show, and Voice Over keeps the bottom place."] = "Сколько виджетов колонка показывает одновременно. Остальные ждут в узкой строке «+2 ещё» сверху; щелчок по ней выводит их список. Розыгрыш добычи, призывы, предложения воскрешения и проверки готовности видны всегда, а Voice Over сохраняет нижнее место.", -- draft
-- stale: ["How much of an element stays while it is faded. At 0 % it is gone until it is needed (an On Mouseover bar at 0 % still shows when you point at it)."] = "Сколько остаётся от элемента, пока он погашен. При 0 % он исчезает, пока не понадобится (панель «При наведении» при 0 % всё равно видна, когда вы на неё указываете).", -- draft
-- stale: ["How names read in chat."] = "Как читаются имена в чате.", -- draft
-- stale: ["How solid the bars' background is: lower lets the world show through the empty part of a bar."] = "Насколько плотен фон полос: меньше — и мир просвечивает сквозь пустую часть полосы.", -- draft
-- stale: ["How solid the chat windows' background is. Moving the Background slider in a chat tab's menu changes this too."] = "Насколько плотен фон окон чата. Ползунок «Фон» в меню вкладки чата тоже меняет это.", -- draft
-- stale: ["How solid the painted border round the chat windows and their button column is, and its shade (the painted chat: its Painted Skin, the reskin on)."] = "Насколько плотна рисованная рамка вокруг окон чата и их колонки кнопок, и её тень (рисованный чат: его рисованный облик, облик включён).", -- draft
-- stale: ["How tall the bars are; the off hand's is 60 % of it, and the weapon's rim grows with them from 15 on. Also in Edit Layout."] = "Насколько высоки полосы; у левой руки — 60 % от этого, а ободок оружия растёт вместе с ними начиная с 15. Также в «Изменить раскладку».", -- draft
-- stale: ["How tall the health bar is; the power and cast bars are a little thinner, in step with it. Their frames grow and shrink with them."] = "Высота полосы здоровья; полосы ресурса и заклинаний чуть тоньше, в такт ей. Их рамки растут и сжимаются вместе с ними.", -- draft
-- stale: ["How tall the square map is (the round map takes its Width). The shorter side is at least half the longer one."] = "Насколько высока квадратная карта (круглая берёт свою «Ширину»). Короткая сторона не меньше половины длинной.", -- draft
-- stale: ["How tall the tracker may grow before it scrolls (at least 88, room for the title and a few lines). Edit Mode's: the height set for the game's tracker in Edit Mode. The grip in its bottom-left corner sets it by dragging."] = "Насколько высоким может стать отслеживание, прежде чем прокручиваться (не меньше 88 — место для заголовка и пары строк). «Из режима редактирования»: высота, заданная для отслеживания игры в режиме редактирования. Ручка в левом нижнем углу задаёт её перетаскиванием.", -- draft
-- stale: ["How the chat is shown. Game Windows: the game's chat windows and tabs. Minimal: one panel with a rail of round tabs on its left (one per chat window, a count of the lines you have not seen; Whispers last), each line under its sender's name, channel and time, and a row of round buttons under the lines: Say, Party, Raid, Instance, Guild, Yell, Whisper and Emote open the line you type in on that chat, then Channels, Friends, the fight history and these settings. A whisper puts a count on the Whispers tab and shows the Whispers widget; either opens one whisper window above the chat with every conversation in it, theirs left and yours right. Parchment (its own switch) puts both on the parchment sheet."] = "Как показывается чат. «Окна игры»: окна и вкладки чата игры. «Минимальный»: одна панель с полосой круглых вкладок слева (по одной на окно чата, со счётчиком непросмотренных строк; «Шёпот» последней), каждая строка под именем отправителя, каналом и временем, и ряд круглых кнопок под строками: «Сказать», «Группа», «Рейд», «Подземелье», «Гильдия», «Крикнуть», «Шепнуть» и «Эмоция» открывают строку ввода в этом чате, затем «Каналы», «Друзья», история боёв и эти настройки. Шёпот ставит счётчик на вкладку «Шёпот» и показывает виджет шёпота; любой из них открывает одно окно шёпота над чатом со всеми разговорами, их реплики слева, ваши справа. «Пергамент» (свой переключатель) кладёт оба на лист пергамента.", -- draft
-- stale: ["How the parchment looks wherever it shows: the sheets switched on below, and the quest log, quest and spell book pages. Burnt paper: warm paper with burnt edges, big pages with curled corners. Classic vellum: the vellum with painted brush-stroke edges from before 0.20.1."] = "Как выглядит пергамент везде, где он показан: листы, включённые ниже, и страницы журнала заданий, заданий и книги заклинаний. Обожжённая бумага: тёплая бумага с обожжёнными краями, большие страницы с загнутыми углами. Классический пергамент: пергамент с краями, нарисованными кистью, как до 0.20.1.", -- draft
-- stale: ["How the raid's frames are grouped: by raid group (1 to 8), by role, by class, or one list."] = "Как группируются рамки рейда: по группе рейда (1–8), по роли, по классу или одним списком.", -- draft
-- stale: ["How the route is drawn on the world map and the minimap: red beads in gold rings, one pale gold line, or short pale gold dashes. The destination is a flag in a gold ring either way."] = "Как рисуется маршрут на карте мира и мини-карте: красные бусины в золотых кольцах, одна бледно-золотая линия или короткие бледно-золотые штрихи. Цель в любом случае — флаг в золотом кольце.", -- draft
-- stale: ["How the value is written."] = "Как записывается значение.", -- draft
-- stale: ["How thick your share is on the race bar's line (its pins and labels keep their size). Also in Edit Layout: right-click the race bar."] = "Насколько толста ваша доля на линии полосы гонки (её метки и подписи сохраняют размер). Также в «Изменить раскладку»: правый щелчок по полосе гонки.", -- draft
-- stale: ["How wide the bars are; the weapon's rim hangs left of them and the seconds right of them. Also in Edit Layout (right-click a bar there)."] = "Насколько широки полосы; ободок оружия висит слева от них, секунды — справа. Также в «Изменить раскладку» (правый щелчок по полосе там).", -- draft
-- stale: ["How wide the health, power and cast bars are. Edit Layout sizes the whole display."] = "Ширина полос здоровья, ресурса и заклинаний. «Изменить раскладку» задаёт размер всего дисплея.", -- draft
-- stale: ["How wide the map is. The round map is as tall as it is wide, and its painted ring grows and shrinks with it. The square map's border and the zone name keep their size, the Services buttons too (smaller only on a map too narrow for them), and the Quest Tracker under the map follows its width. Edit Mode's minimap Size no longer sizes the map while the Minimap Kit is on."] = "Насколько широка карта. Круглая карта столь же высока, сколь широка, и её рисованное кольцо растёт и сжимается вместе с ней. Рамка квадратной карты и название зоны сохраняют размер, кнопки «Услуг» тоже (меньше только на слишком узкой для них карте), а отслеживание заданий под картой следует её ширине. «Размер» мини-карты в режиме редактирования больше не задаёт размер карты, пока включён набор мини-карты.", -- draft
-- stale: ["How wide the race bar is. Also in Edit Layout: right-click the race bar."] = "Насколько широка полоса гонки. Также в «Изменить раскладку»: правый щелчок по полосе гонки.", -- draft
-- stale: ["How wide the tracker is when it does not match the minimap's width (at least 60). Edit Mode's: as wide as the game's tracker. The grip in its bottom-left corner sets width and height by dragging (only the height while it matches the minimap)."] = "Ширина отслеживания, когда оно не повторяет ширину мини-карты (не меньше 60). «Из режима редактирования»: как ширина отслеживания игры. Ручка в левом нижнем углу задаёт ширину и высоту перетаскиванием (только высоту, пока оно повторяет мини-карту).", -- draft
-- stale: ["How your heals look. By Class: Holy for priests and paladins, Nature for druids, Water for shamans (Holy for anyone else). Water: water circles your cast bar, a winding stream throws off droplets, a splash lands; a shield is a water bubble, a heal to full a geyser. Holy: gold sparks spiral into your spell's icon, a gold comet flies, a white flash and a burst of rays land, rune marks linger round the frame. Nature: green and gold ribbons circle your cast bar, ribbons fly shedding leaves, leaves burst and rise. Quiet: your cast bar's fill glows, a thin thread of light flies, the frame's border flares. Each kind lands its own way in each look: a heal over time sinks in, a shield wraps the frame in a barrier, protection puts a crest over it, a heal to full raises a column of light, a resurrection lights the fallen one's frame."] = "Как выглядит ваше исцеление. «По классу»: «Свет» для жрецов и паладинов, «Природа» для друидов, «Вода» для шаманов («Свет» для остальных). «Вода»: вода кружит у индикатора заклинаний, извилистый поток роняет капли, приземляется всплеск; щит — водяной пузырь, полное исцеление — гейзер. «Свет»: золотые искры спиралью уходят в значок заклинания, летит золотая комета, приземляются белая вспышка и всплеск лучей, руны задерживаются вокруг рамки. «Природа»: зелёные и золотые ленты кружат у индикатора заклинаний, ленты летят, роняя листья, листья взрываются и поднимаются. «Тихо»: заливка индикатора заклинаний светится, летит тонкая нить света, рамка вспыхивает. Каждый вид приземляется по-своему в каждом облике: периодическое исцеление впитывается, щит окутывает рамку барьером, защита ставит над ней герб, полное исцеление поднимает столб света, воскрешение озаряет рамку павшего.", -- draft
-- stale: ["Icon frames and bar backgrounds of the Essential, Utility and Buff cooldown viewers."] = "Рамки значков и фон полос у окон основных, вспомогательных способностей и положительных эффектов.", -- draft
-- stale: ["Icons stay smooth and sharp at every size and UI scale: each one is drawn from a copy made for its size on your screen."] = "Значки остаются гладкими и чёткими при любом размере и масштабе: каждый рисуется из копии под его размер на экране.", -- draft
-- stale: ["In Combat elements come back while you have a target, a friend too."] = "Элементы «В бою» возвращаются, пока у вас есть цель, и дружественная тоже.", -- draft
-- stale: ["In Combat elements come back while you point at them, too. (On Mouseover elements always do.)"] = "Элементы «В бою» возвращаются и пока вы на них указываете. (Элементы «При наведении» — всегда.)", -- draft
-- stale: ["In Combat: a bar shows in a fight once it swings or shoots, and fades out when the fight ends (the shot bar also when Auto Shot stops). Always: each bar shows while you carry a weapon for it, at rest between swings."] = "«В бою»: полоса появляется в бою, как только бьёт или стреляет, и гаснет, когда бой заканчивается (полоса выстрела — также когда останавливается «Автоматическая стрельба»). «Всегда»: каждая полоса видна, пока у вас есть оружие для неё, в покое между ударами.", -- draft
-- stale: ["In a fight"] = "В бою", -- draft
-- stale: ["In a fight the widget shrinks to the speaker's face and its ring, and the reading goes on (a book too). The name and the line come back when the fight is over."] = "В бою виджет сжимается до лица говорящего и кольца, а чтение продолжается (книга тоже). Имя и строка возвращаются после боя.", -- draft
-- stale: ["In a fight, one line for the group: the top player at its right end with their value, everyone else a class icon at their share of the top, you the bigger icon with the line filled up to you in your class colour. It fades in when the fight starts and out when it ends. The pointer on it lists everyone. Move it in Edit Layout."] = "В бою одна линия для группы: лучший игрок на её правом конце со своим значением, все остальные — значок класса на своей доле от лучшего, вы — значок покрупнее, и линия заполнена до вас цветом вашего класса. Появляется в начале боя и гаснет в конце. Указатель на ней показывает всех. Переместите её в «Изменить раскладку».", -- draft
-- stale: ["In a group fight, a thin bar along the bottom of an enemy's health bar (in the Nameplate Kit's lower rail) fills to the point where it would turn on you: gold while safe, amber when close, red when it is on you. For a tank it turns red when a mob is not on you. Solo it stays away."] = "В групповом бою тонкая полоса вдоль низа полосы здоровья врага (в нижней планке набора индикаторов здоровья) заполняется до точки, где он повернётся к вам: золотая, пока безопасно, янтарная, когда близко, красная, когда он на вас. Для танка она краснеет, когда враг не на нём. В одиночку её нет.", -- draft
-- stale: ["In a group fight, only when it matters: close to pulling your target (\"Ease off\") or with it on you (\"Aggro\"), and for a tank the mobs not on you. The ring is your threat against the pull; point at it for the group's threat on your target."] = "В групповом бою, только когда это важно: близко к тому, чтобы сорвать цель («Полегче»), или она уже на вас («Агро»), а для танка — враги, которые не на нём. Кольцо — ваша угроза относительно срыва; наведите, чтобы увидеть угрозу группы по вашей цели.", -- draft
-- stale: ["In a party: these frames, or MelloUI's normal party frames (the game's party frames with their portraits, in the painted look). With the normal ones, you show as one of them while solo too (Show Yourself While Solo), so you can see your heals and indicators on it. In a raid these frames show. The normal party frames show as the game's Edit Mode sets them: with Raid-Style Party Frames on there, the game shows none of its normal ones."] = "В группе: эти рамки или обычные рамки группы MelloUI (рамки группы игры с портретами в рисованном облике). С обычными вы и в одиночку показываетесь как одна из них («Показывать себя в одиночку»), чтобы видеть на ней своё исцеление и индикаторы. В рейде видны эти рамки. Обычные рамки группы видны так, как их задаёт режим редактирования игры: с включёнными там «Рамками группы в стиле рейда» игра не показывает ни одной обычной.", -- draft
-- stale: ["In a party: these frames, or the classic party frames with portraits. In a raid, these frames always show."] = "В группе: эти рамки или классические рамки группы с портретами. В рейде всегда эти рамки.", -- draft
-- stale: ["In a quest's objective area, with the quest's item in your bags: the item, a ring for the objective's progress and how many you carry. Click it to use the item (out of combat: it folds away in a fight)."] = "В области цели задания, с предметом задания в сумках: предмет, кольцо хода цели и сколько у вас есть. Нажмите, чтобы использовать предмет (вне боя: в бою прячется).", -- draft
-- stale: ["In an inn or a city, and in a town like Sentinel Hill, every reminder stays until it is done (a mailbox opened, the spells or the rank learned ...) or you leave; Not now there waits until you next enter one."] = "В таверне или городе, а также в посёлке вроде Сторожевого холма, каждое напоминание остаётся, пока не выполнено (открыт почтовый ящик, изучены заклинания или ранг ...) или пока вы не уйдёте; «Не сейчас» там ждёт до следующего входа.", -- draft
-- stale: ["In silver: a stack worth this or more is never thrown away (selling it at a vendor still is). 100 silver = 1 gold."] = "В серебре: стопка стоимостью столько или больше никогда не выбрасывается (продаётся у торговца — да). 100 серебра = 1 золото.", -- draft
-- stale: ["In the box that splits a stack (Shift-click a stack), the mouse wheel changes the amount: up adds one, down takes one, ten at a time while you hold Shift."] = "В окне разделения стопки (Shift-щелчок по стопке) колёсико мыши меняет количество: вверх добавляет одну, вниз убирает одну, по десять при зажатом Shift.", -- draft
-- stale: ["Indicators for %s"] = "Индикаторы для %s", -- draft
-- stale: ["Interrupted casts show only on the Personal Display's cast bar, with their word."] = "Прерванные заклинания видны только на полосе заклинаний личного дисплея, со своим словом.", -- draft
-- stale: ["Into a fight the bars rise into place; a moment after it they settle a little lower, until the next one. (To fade them out of combat: the Fader.)"] = "В бою полосы поднимаются на место; через мгновение после него опускаются чуть ниже до следующего. (Чтобы гасить их вне боя: «Угасание».)", -- draft
