-- stale: ["Item names in their quality colour (green, blue, purple) beside the quality gem. Blue and purple read less well over bright ground. Off: the names in the text colour."] = "Названия предметов в цвете качества (зелёный, синий, фиолетовый) рядом с самоцветом качества. Синий и фиолетовый хуже читаются на светлом фоне. Выкл.: названия в цвете текста.", -- draft
-- stale: ["Its keys work while it is faded. Always: never faded. In Combat: faded out of combat, back in a fight. On Mouseover: faded all the time, shown while you point at it."] = "Её клавиши работают, пока она погашена. «Всегда»: никогда не гаснет. «В бою»: гаснет вне боя, возвращается в бою. «При наведении»: погашена всё время, видна, пока вы на неё указываете.", -- draft
