-- stale: ["Junk (grey quality) items show grey in your bags, the bank and the guild bank, so they stand apart from what you keep. One switch for all three windows."] = "Хлам (серое качество) выглядит серым в ваших сумках, банке и банке гильдии, чтобы отличаться от того, что вы храните. Один переключатель для всех трёх окон.", -- draft
-- stale: ["Keep the widget column (Voice Over, loot rolls, the corpse run and the rest) where it is: Edit Layout shows its plate but does not move it. Voice Over's padlock sets this too."] = "Держит колонку виджетов (Voice Over, розыгрыш добычи, путь к телу и остальные) на месте: «Изменить раскладку» показывает её табличку, но не двигает её. Замок Voice Over тоже задаёт это.", -- draft
-- stale: ["Keeps drink, food, ammunition and reagents in your bags: a reminder when one runs low (with Reminders on), and at a shop a list of what to buy, bought only when you click Buy."] = "Держит питьё, еду, боеприпасы и реагенты в ваших сумках: напоминание, когда что-то кончается (при включённых «Напоминаниях»), а у торговца — список покупок, покупаемых только по нажатию «Купить».", -- draft
-- stale: ["Keeps the game's sparkle on quest items you can loot. It needs the game's outline mode off, which its graphics presets switch back on: held while this is on, given back as you had it when off. Switching this off takes the sparkles away after the next game restart (the client's own; /reload is not enough)."] = "Сохраняет искру игры на предметах для заданий, которые можно забрать. Ей нужен выключенный режим контуров игры, который её графические наборы снова включают: удерживается, пока это включено, и возвращается в прежнем виде при выключении. После выключения искры пропадут после следующего перезапуска игры (клиента; /reload недостаточно).", -- draft
-- stale: ["Languages: the configurator and the installer in German, French, Spanish, Portuguese, Russian, Chinese and Korean. Pick one at the left of the top line."] = "Языки: конфигуратор и установщик на немецком, французском, испанском, португальском, русском, китайском и корейском. Выберите язык слева на верхней строке.", -- draft
-- stale: ["Leave out quests whose level is more than this many levels above your character. 0 shows everything."] = "Не показывает задания, чей уровень выше вашего более чем на столько. 0 показывает всё.", -- draft
-- stale: ["Leave out quests you have already completed instead of greying them."] = "Не показывает уже выполненные задания вместо того, чтобы делать их серыми.", -- draft
-- stale: ["Leave out the beta's \"Press F6 to submit an issue for this ...\" line, and the gap above it, from creature, item, spell and quest tooltips. The key still opens the issue report while the tooltip shows."] = "Убирает строку беты «Press F6 to submit an issue for this ...» и промежуток над ней из подсказок существ, предметов, заклинаний и заданий. Клавиша по-прежнему открывает отчёт, пока видна подсказка.", -- draft
-- stale: ["Leave quests that are grey for you (far below your level, as the game colours them) off the zone map until you take them. Quests in your log and the one you track still show."] = "Не показывает на карте зоны серые для вас задания (далеко ниже вашего уровня, как их окрашивает игра), пока вы их не возьмёте. Задания из журнала и отслеживаемое по-прежнему видны.", -- draft
-- stale: ["Leave the coloured magic / curse / poison / disease debuff borders untouched: on your buff and debuff icons (Buffs & Debuffs) and on the Cooldown Manager's icons (its Dark Mode)."] = "Не трогает цветные рамки отрицательных эффектов магии / проклятия / яда / болезни: на значках ваших эффектов («Баффы и дебаффы») и на значках менеджера восстановления (его тёмный режим).", -- draft
-- stale: ["Length"] = "Длина", -- draft
-- stale: ["Lines MelloUI writes to chat on its own: a learned dungeon entrance, settings restored from the backup, hints. Replies to slash commands, and the notices you send to the chat (Send To Chat Instead), always show."] = "Строки, которые MelloUI сам пишет в чат: изученный вход в подземелье, настройки, восстановленные из резервной копии, подсказки. Ответы на слеш-команды и оповещения, отправленные вами в чат («Отправлять в чат»), видны всегда.", -- draft
-- stale: ["List quests picked up from a quest giver or an object (the \"!\"). The gear button on the list switches these as well; they apply to the map pins too."] = "Показывает задания, взятые у того, кто их даёт, или у объекта («!»). Кнопка-шестерёнка списка тоже переключает это; это же действует на метки карты.", -- draft
-- stale: ["List quests that begin with an item dropped by creatures (crossed swords)."] = "Показывает задания, начинающиеся с предмета, выпавшего из существ (скрещённые мечи).", -- draft
-- stale: ["List quests that begin with an item picked up from the ground or a chest (treasure chest)."] = "Показывает задания, начинающиеся с предмета, поднятого с земли или из сундука (сундук с сокровищами).", -- draft
-- stale: ["List quests whose giver or starting item is not known yet."] = "Показывает задания, чей даритель или начальный предмет пока неизвестен.", -- draft
-- stale: ["List the quests you hid (Alt-click a quest giver's mark on the map, or a quest in the list), dimmed, so you can Alt-click them back. Hidden quests stay off the map either way. Hiding is kept per character."] = "Показывает скрытые вами задания (Alt-щелчок по метке того, кто даёт задания, на карте или по заданию в списке) приглушёнными, чтобы их можно было вернуть Alt-щелчком. Скрытые задания в любом случае не видны на карте. Скрытие хранится для каждого персонажа.", -- draft
-- stale: ["Load all of the reskin's artwork during the loading screen, so a window opened for the first time after a reload shows its art at once instead of a moment later. Keeps about 13 MB of artwork in memory for the whole session, including for windows you never open. Off: each piece loads the first time a window needs it."] = "Загружает всю графику облика во время экрана загрузки, чтобы окно, впервые открытое после перезагрузки, сразу показывало оформление, а не мгновением позже. Держит около 13 МБ графики в памяти всю сессию, в том числе для окон, которые вы никогда не открываете. Выкл.: каждая часть загружается, когда она впервые нужна окну.", -- draft
-- stale: ["Loading a profile made for another screen offers Fit to this screen."] = "Профиль, сделанный для другого экрана, при загрузке предлагает Подогнать под этот экран.", -- draft
