-- stale: ["Mark every known quest giver on the zone map with a ! or ? coloured by what you can do there. Hover for the quests, click to track the giver. The List tab's choices apply to the pins too: where quests start (for quests not taken yet), the other faction's and other classes' quests, the levels above yours, and Events (a holiday's givers show while the list shows Events or the quest is in your log)."] = "Отмечает каждого известного дающего задания на карте зоны знаком ! или ?, окрашенным по тому, что вы можете там сделать. Наведите, чтобы увидеть задания, щёлкните, чтобы отслеживать. Выбор на вкладке «Список» действует и на метки: где начинаются задания (для ещё не взятых), задания другой фракции и других классов, уровни выше вашего и «События» (дающие задания праздника видны, пока список показывает «События» или задание в журнале).", -- draft
-- stale: ["Mark instance entrances on the zone maps. Hover for the level range and your quest progress, click to list its quests. Entrances of new instances are learned the first time you walk in."] = "Отмечает входы в подземелья на картах зон. Наведите для диапазона уровней и прогресса заданий, щёлкните, чтобы перечислить задания. Входы в новые подземелья запоминаются при первом входе.", -- draft
-- stale: ["Mark on the zone map where the quests in your log are done: an outline round each objective's area with one mark for it (a sword to kill, a bag to collect, a cog to use, a flag to explore) and its progress, and the single places as small dots when you zoom in. Hover a mark for the quest, the objective and what drops it; click it for a waypoint. A done objective's marks go; a done quest shows only its hand-in ?."] = "Отмечает на карте зоны, где выполняются задания из журнала: контур вокруг области каждой цели с одной меткой (меч — убить, сумка — собрать, шестерня — использовать, флаг — исследовать) и её ходом, а отдельные места — маленькими точками при приближении. Наведите на метку, чтобы увидеть задание, цель и с кого она падает; щёлкните для путевой точки. Метки выполненной цели исчезают; выполненное задание показывает только «?» сдачи.", -- draft
