-- stale: ["MelloUI's damage meter in place of the game's: three numbers by every frame (this fight, this run, healing), a race bar for the group in a fight, a summary after it and a Fight History window. The game's own damage meter is switched off while it is on, and comes back as you had it when it is off."] = "Счетчик урона MelloUI вместо игрового: три числа у каждой рамки (этот бой, этот забег, исцеление), полоса гонки для группы в бою, итог после него и окно «История боёв». Счетчик урона игры выключен, пока этот включён, и возвращается в прежнем виде, когда этот выключен.", -- draft
