-- stale: ["On a quest's tooltip in the Quest List, name your other characters who have done the quest or have it in their quest log. A character is noted each time it logs out; /mello alts lists them and forgets a deleted one."] = "В подсказке задания в «Списке заданий» называет ваших других персонажей, выполнивших задание или имеющих его в журнале. Персонаж записывается при каждом выходе; /mello alts перечисляет их и забывает удалённого.", -- draft
-- stale: ["On the game's nameplates: the large crowd-control icon above the name, the quest marker on enemies you still need, the threat line, the combo points on your target's plate, the names' form (Show Names As) and the soft shade behind the names (Name Shade). Off: all six go. Works with or without the reskin."] = "На индикаторах здоровья игры: крупный значок контроля над именем, метка задания на врагах, которые вам ещё нужны, линия угрозы, приёмы серии на индикаторе цели, форма имён («Показывать имена как») и мягкая тень за именами («Тень имени»). Выкл.: пропадают все шесть. Работает с обликом и без.", -- draft
-- stale: ["On the target, show only the debuffs you put on it."] = "На цели показывает только отрицательные эффекты, наложенные вами.", -- draft
-- stale: ["On the tooltip of an NPC that takes back one of your quests: \"Turn in here\" once the quest is ready, a quieter \"Quest ends here\" while it is still in progress."] = "В подсказке NPC, принимающего одно из ваших заданий: «Сдать здесь», когда задание готово, и более тихое «Задание сдаётся здесь», пока оно ещё выполняется.", -- draft
-- stale: ["On the tooltip of an item one of your quests asks for, name the quest and how many you have, for example \"Quest: Red Linen Goods (4/6)\"."] = "В подсказке предмета, нужного для одного из ваших заданий, называет задание и сколько у вас есть, например «Задание: Red Linen Goods (4/6)».", -- draft
-- stale: ["One cog notch per mouse-wheel step on any list, window or the chat. The game has no wheel sound; this is an addition."] = "Один щелчок шестерни на шаг колёсика в любом списке, окне или чате. У игры нет звука колёсика; это дополнение.", -- draft
-- stale: ["One look: its own look, Gilded Slate colours, the Fredoka font and a new logo, reskin or not; the installer sets up the new layout. The painted reskin is MelloUI Oldschool."] = "Единый облик: собственный вид, цвета Gilded Slate, шрифт Fredoka и новый логотип, с рисованным обликом или без; установщик ставит новую раскладку. Рисованный облик — это MelloUI Oldschool.", -- draft
-- stale: ["One seamless map of the whole world: zoom from Azeroth down to a zone with the mouse wheel and drag to look around."] = "Одна бесшовная карта всего мира: приближайте от Азерота до зоны колёсиком мыши и перетаскивайте, чтобы оглядеться.", -- draft
-- stale: ["One short line in the upper third of the screen when MelloUI has news for you: a route set or finished, a service remembered, a dungeon's quests listed. It fades after a few seconds. Move it in Edit Layout."] = "Одна короткая строка в верхней трети экрана, когда у MelloUI есть для вас новости: маршрут задан или пройден, услуга запомнена, задания подземелья перечислены. Она гаснет через несколько секунд. Переместите её в «Изменить раскладку».", -- draft
