-- stale: ["Play the recorded lines of the voice pack, MelloUI_VoicePack (a separate download in two parts that replaces the old pack), when it has one for the quest, greeting or page; the rest is read with text-to-speech unless Read Unvoiced Lines is off. Tick the pack in the addon list; it loads when needed."] = "Проигрывает записанные строки пакета голосов MelloUI_VoicePack (отдельная загрузка из двух частей, заменяющая старый пакет), если у него есть запись для задания, приветствия или страницы; остальное читается синтезом речи, если не выключено «Читать неозвученные строки». Отметьте пакет в списке модификаций; он загружается, когда нужен.", -- draft
