-- stale: ["Quest areas: smooth gold areas that follow the spawns, on both maps and the minimap; their marks pop in, lift, ring on progress and tick off."] = "Области заданий: мягкие золотые области по местам появления, на обеих картах и мини-карте; их метки выскакивают, поднимаются, звенят при прогрессе и отмечаются.", -- draft
-- stale: ["Quests, travel and your group"] = "Задания, путешествия и ваша группа", -- draft
-- stale: ["Quests: the Quest Tracker in the chat's look with the game's clicks, round marks, one gem per title, short Quest List and map tips; Parchment is its own switch."] = "Задания: отслеживание заданий в облике чата со щелчками игры, круглые метки, по самоцвету на название, короткие подсказки «Списка заданий» и карты; у «Пергамента» свой переключатель.", -- draft
-- stale: ["Raid Frames: indicators for %s"] = "Рамки рейда: индикаторы для %s", -- draft
-- stale: ["Read NPC dialog and quest text aloud with the built in text-to-speech voices, picked by the NPC's race and gender."] = "Читает вслух диалоги NPC и текст заданий встроенными голосами синтеза речи, выбранными по расе и полу NPC.", -- draft
-- stale: ["Read a book, letter, note, plaque or sign aloud when you open it: the whole book, from the page you open to the last, with no page turning, and it goes on when you close it or walk away. Turning a page reads on from that page; Stop ends it. The narrator's recordings come from the voice pack (MelloUI_VoicePack); without it only the page you see is read, with text-to-speech when Read Unvoiced Lines is on."] = "Читает вслух книгу, письмо, записку, табличку или вывеску, когда вы её открываете: всю книгу, с открытой страницы до последней, без перелистывания, и продолжает, когда вы её закрываете или уходите. Перелистывание продолжает с этой страницы; «Стоп» заканчивает. Записи рассказчика берутся из пакета голосов (MelloUI_VoicePack); без него читается только видимая страница — синтезом речи, если включено «Читать неозвученные строки».", -- draft
-- stale: ["Read a quest or greeting the voice pack has no recording of with a text-to-speech voice. Off: only recorded lines are heard and the rest stay silent."] = "Читает голосом синтеза речи задание или приветствие, для которого в пакете голосов нет записи. Выкл.: слышны только записанные строки, остальное молчит.", -- draft
-- stale: ["Read lines one after another: a greeting finishes before the quest offer that follows it. Off makes every new dialog interrupt the previous one."] = "Читает строки одну за другой: приветствие заканчивается до следующего за ним предложения задания. Выкл.: каждый новый диалог прерывает предыдущий.", -- draft
-- stale: ["Red and larger under 5 s (1.3 times the Text Size), yellow under a minute, dim white and smaller for minutes (0.8 times), grey and smaller still for hours (0.75 times). Off: every timer is white at the Text Size."] = "Красный и крупнее меньше 5 с (в 1,3 раза больше «Размера текста»), жёлтый меньше минуты, тусклый белый и мельче для минут (0,8), серый и ещё мельче для часов (0,75). Выкл.: каждый таймер белый в «Размере текста».", -- draft
-- stale: ["Remember where you walk and fly so routes can follow real roads. What it learns is saved and kept from one session to the next. /route shows how much has been learned."] = "Запоминает, где вы ходите и летаете, чтобы маршруты шли по настоящим дорогам. Изученное сохраняется между сессиями. /route показывает, сколько изучено.", -- draft
-- stale: ["Remind you once this many free bag slots or fewer are left."] = "Напоминает, как только останется столько свободных ячеек или меньше.", -- draft
-- stale: ["Remind you once your most worn piece of gear is down to this much durability."] = "Напоминает, как только самый изношенный предмет снаряжения опустится до этой прочности.", -- draft
-- stale: ["Remind you when Well Fed has two minutes left."] = "Напоминает, когда «Сытости» осталось две минуты.", -- draft
-- stale: ["Remind you when a poison, an oil or a sharpening stone has run out on a weapon, or has two minutes left, while you carry one to put it back on. It stays until it is back on, in fights too; click it to put it back on (out of combat)."] = "Напоминает, когда яд, масло или точильный камень на оружии кончился или ему осталось две минуты, пока у вас есть чем обновить. Остаётся, пока не обновлено, и в бою тоже; нажмите, чтобы нанести снова (вне боя).", -- draft
-- stale: ["Remind you when a trainer has something new for you."] = "Напоминает, когда у наставника есть для вас что-то новое.", -- draft
-- stale: ["Remind you when mail is waiting for you. It goes once you open a mailbox, and comes back only for mail that arrives after."] = "Напоминает, когда вас ждёт почта. Исчезает, как только вы откроете почтовый ящик, и возвращается только ради почты, пришедшей позже.", -- draft
-- stale: ["Remind you when one of your own buffs is missing on you: Arcane Intellect and a mage's armor, Fortitude, Inner Fire and Divine Spirit, Mark of the Wild, a warlock's armor. Only buffs you can cast. It stays until the buff is back, in fights too (the game hides buffs in a fight, so one lost there shows after it); click it to cast (out of combat)."] = "Напоминает, когда на вас нет одного из ваших собственных эффектов: «Чародейский интеллект» и броня мага, «Стойкость», «Внутренний огонь» и «Божественный дух», «Знак дикой природы», броня чернокнижника. Только эффекты, которые вы можете наложить. Остаётся, пока эффект не вернётся, и в бою тоже (игра скрывает эффекты в бою, так что потерянный там появится после); нажмите, чтобы наложить (вне боя).", -- draft
-- stale: ["Remind you when people in your group are missing a buff you can cast (Arcane Intellect and Divine Spirit only on those who use mana); point at it for their names. It stays until they have it, in fights too; click it to cast it on them, one by one (out of combat)."] = "Напоминает, когда у участников группы нет эффекта, который вы можете наложить («Чародейский интеллект» и «Божественный дух» — только у тех, кто использует ману); наведите, чтобы увидеть имена. Остаётся, пока он у них не появится, и в бою тоже; нажмите, чтобы накладывать на них по одному (вне боя).", -- draft
-- stale: ["Remind you when you have talent points to spend."] = "Напоминает, когда у вас есть очки талантов.", -- draft
-- stale: ["Remind you when your bags are almost full; it stays, in a fight too, until you make room. Click it for the way to the nearest vendor."] = "Напоминает, когда сумки почти полны; остаётся, и в бою тоже, пока вы не освободите место. Нажмите, чтобы увидеть путь к ближайшему торговцу.", -- draft
-- stale: ["Remind you when your gear is wearing out. Broken gear goes to the top of the list."] = "Напоминает, когда снаряжение изнашивается. Сломанное снаряжение идёт в начало списка.", -- draft
