-- stale: ["Show the speaker in MelloUI's widget column while a line is read: their face, the line, a gold ring that fills as it plays and the lines waiting. Hover it for Pause, Skip, Lines and the padlock; right-click stops. Move and size the column in Edit Layout; /vo reset puts it back."] = "Показывает говорящего в колонке виджетов MelloUI, пока читается строка: лицо, строку, золотое кольцо, заполняющееся по ходу, и ожидающие строки. Наведите для «Пауза», «Пропустить», «Строки» и замка; правый щелчок останавливает. Двигайте и меняйте размер колонки в «Изменить раскладку»; /vo reset возвращает её на место.", -- draft
