-- stale: ["The bars under your character and the shield column beside it (Personal Display). In Combat, they also come back while you cast. (No On Mouseover: the pointer passes through them to the world.) Always: never faded. In Combat: faded out of combat, back in a fight."] = "Полосы под вашим персонажем и колонка щита рядом (личный дисплей). «В бою» они возвращаются и пока вы произносите заклинание. (Без «При наведении»: указатель проходит сквозь них в мир.) «Всегда»: никогда не гаснет. «В бою»: гаснет вне боя, возвращается в бою.", -- draft
-- stale: ["The border of the backdrop round the action bars (and the experience and reputation bars): the red or iron gems on its corners, or one of the border styles of Oldschool > Borders (drawn heavy, its inner corners mitred). Each element's backdrop is switched on on Bars (its Backdrop); switched-on elements placed together share one backdrop, in the look of the first of them: Action Bar 1, the other bars, the micro menu, the bag bar."] = "Рамка подложки вокруг панелей команд (и индикаторов опыта и репутации): красные или железные самоцветы по углам или один из стилей рамок из Oldschool > Рамки (толстый, внутренние углы скошены). Подложка каждого элемента включается в «Панелях» (её «Подложка»); включённые элементы, стоящие вместе, делят одну подложку в облике первого из них: панель команд 1, другие панели, микроменю, панель сумок.", -- draft
-- stale: ["The border of the backdrop round the bag bar: the red or iron gems on its corners, or one of the border styles of Oldschool > Borders (drawn heavy, its inner corners mitred). Each element's backdrop is switched on on Bars (its Backdrop); switched-on elements placed together share one backdrop, in the look of the first of them: Action Bar 1, the other bars, the micro menu, the bag bar."] = "Рамка подложки вокруг панели сумок: красные или железные самоцветы по углам или один из стилей рамок из Oldschool > Рамки (толстый, внутренние углы скошены). Подложка каждого элемента включается в «Панелях» (её «Подложка»); включённые элементы, стоящие вместе, делят одну подложку в облике первого из них: панель команд 1, другие панели, микроменю, панель сумок.", -- draft
-- stale: ["The border of the backdrop round the micro menu: the red or iron gems on its corners, or one of the border styles of Oldschool > Borders (drawn heavy, its inner corners mitred). Each element's backdrop is switched on on Bars (its Backdrop); switched-on elements placed together share one backdrop, in the look of the first of them: Action Bar 1, the other bars, the micro menu, the bag bar."] = "Рамка подложки вокруг микроменю: красные или железные самоцветы по углам или один из стилей рамок из Oldschool > Рамки (толстый, внутренние углы скошены). Подложка каждого элемента включается в «Панелях» (её «Подложка»); включённые элементы, стоящие вместе, делят одну подложку в облике первого из них: панель команд 1, другие панели, микроменю, панель сумок.", -- draft
-- stale: ["The border on each raid frame and raid-style party frame: the Single rail they wear today, one of the thin rims the buttons wear, or the Backdrop, its corner gems in the colour of the action bars' Backdrop."] = "Рамка каждой рамки рейда и рамки группы в стиле рейда: одинарная планка (сейчас), одна из тонких окантовок кнопок или подложка с самоцветами в углах цвета подложки панелей команд.", -- draft
-- stale: ["The border round the square map: the windows' frame with its gem corners, a single iron rail, the action bars' heavy frame with red or iron gems, one of the thin rims the buttons wear (drawn heavier, at the map's size), or none. Picked with pictures on the Minimap page, its Border part. The painted borders need the painted Minimap skin (Oldschool); without it the map wears the Chat panel."] = "Рамка вокруг квадратной карты: рамка окон с самоцветами в углах, одинарная железная планка, тяжёлая рамка панелей команд с красными или железными самоцветами, одна из тонких окантовок кнопок (толще, в размер карты) или нет. Выбирается по картинкам на странице «Мини-карта», в части «Рамка». Рисованным рамкам нужен рисованный облик мини-карты (Oldschool); без него карта носит панель чата.", -- draft
-- stale: ["The buffs you give yourself on a cooldown -- Shield Wall, Shield Block, Last Stand, Evasion, Ice Block, Recklessness, a trinket's -- as icons above the health bar, their time sweeping round them and their seconds on them, the most important first: an immunity, then damage taken down, more health, block, evasion, the rest. From the game's own spell data, for every class."] = "Эффекты, которые вы накладываете на себя со временем восстановления, — «Глухая оборона», «Блок щитом», «Ни шагу назад», «Ускользание», «Ледяная глыба», «Безрассудство», эффект аксессуара — значками над полосой здоровья, время обегает их, секунды на них, самые важные первыми: неуязвимость, затем снижение урона, больше здоровья, блок, уклонение, остальное. По данным заклинаний игры, для каждого класса.", -- draft
-- stale: ["The character window on a parchment sheet, its text in dark ink: Right pane lays it under the right pane (the stats, reputation, skills and the other lists); Whole window over the whole window inside its frame, the window's own stone round its edge. Off: no parchment; the window shows its Window Background (Windows > Character window)."] = "Окно персонажа на листе пергамента, текст тёмными чернилами: «Правая панель» кладёт его под правую панель (характеристики, репутация, навыки и другие списки); «Всё окно» — на всё окно внутри рамки, собственный камень окна по краю. Выкл.: без пергамента; окно показывает свой фон (Окна > Окно персонажа).", -- draft
-- stale: ["The chat and whisper windows' text on their parchment sheet, relative to the chat's own size."] = "Текст окон чата и шёпота на листе пергамента относительно собственного размера чата.", -- draft
-- stale: ["The chat input box shows only while you type: Enter (or /) brings it up, and it goes again once you send the line or press Escape. It sets the game's Chat Style to Classic while on, and gives your own back when off. The change shows from the next line you type."] = "Поле ввода чата видно только пока вы пишете: Enter (или /) вызывает его, и оно исчезает после отправки строки или нажатия Esc. Пока включено, ставит «Стиль чата» игры на «Классический» и возвращает ваш при выключении. Изменение видно со следующей строки.", -- draft
-- stale: ["The chat on a parchment sheet, its text in dark ink: the Minimal Chat View and its whisper window with the reskin on or off; the game's chat windows with the painted chat (its Painted Skin, the reskin on)."] = "Чат на листе пергамента, текст тёмными чернилами: минимальный вид чата и его окно шёпота с обликом или без; окна чата игры с рисованным чатом (его рисованный облик, облик включён).", -- draft
-- stale: ["The chat windows (on top of the game's own chat font size) and every number."] = "Окна чата (поверх собственного размера шрифта чата в игре) и все числа.", -- draft
-- stale: ["The chat windows and whisper windows while they lie on their parchment sheet (Oldschool > Parchment). By default the chat text's face in its semibold cut where it has one, heavier so the dark ink reads on the paper; each Font Style sets that cut of its reading face."] = "Окна чата и шёпота, пока они лежат на листе пергамента (Oldschool > Пергамент). По умолчанию шрифт текста чата в полужирном начертании, если оно есть, плотнее, чтобы тёмные чернила читались на бумаге; каждый стиль шрифтов задаёт это начертание своего шрифта для чтения.", -- draft
-- stale: ["The chat windows with their tabs, buttons, the Friends button and the line you type in. They come back while you type. Always: never faded. In Combat: faded out of combat, back in a fight. On Mouseover: faded all the time, shown while you point at it."] = "Окна чата с вкладками, кнопками, кнопкой «Друзья» и строкой ввода. Возвращаются, пока вы пишете. «Всегда»: никогда не гаснет. «В бою»: гаснет вне боя, возвращается в бою. «При наведении»: погашена всё время, видна, пока вы на неё указываете.", -- draft
-- stale: ["The chat windows' background: a dark panel of the palette behind the window, its tabs and its input box (Dark), the game's own (Game), or none at all (None). Under the painted chat (its Painted Skin, the reskin on) its stone instead. With the Minimal Chat View: None leaves its panel clear, Dark and Game keep its dark panel; Parchment lays the parchment sheet over it."] = "Фон окон чата: тёмная панель палитры за окном, его вкладками и полем ввода («Тёмный»), фон игры («Игра») или никакого («Нет»). Под рисованным чатом (его рисованный облик, облик включён) — вместо этого его камень. С «Минимальным» видом чата: «Нет» оставляет его панель чистой, «Тёмный» и «Игра» сохраняют тёмную панель; «Пергамент» кладёт поверх лист пергамента.", -- draft
-- stale: ["The chat windows' messages, the chat's input box and the whisper windows. The same face as the Interface text unless you choose otherwise (the Chat & numbers face while that is the game's), so the chat follows the Font Styles and your own choice of reading face. The size stays the chat's own (Chat & numbers size)."] = "Сообщения окон чата, поле ввода чата и окна шёпота. Тот же шрифт, что «Текст интерфейса», если не выбрать другой (шрифт «Чат и числа», пока он игровой), чтобы чат следовал стилям шрифтов и вашему выбору шрифта для чтения. Размер остаётся размером чата (размер «Чата и чисел»).", -- draft
-- stale: ["The chosen health bar colour wins over the game's own recolouring of health bars (the aggro / threat display on nameplates and unit frames): whenever the game sets its colour, yours is put back. Off: the game's threat colours show."] = "Выбранный цвет полосы здоровья побеждает собственную перекраску игры (показ агро / угрозы на индикаторах здоровья и рамках): всякий раз, когда игра ставит свой цвет, ваш возвращается. Выкл.: видны цвета угрозы игры.", -- draft
