-- stale: ["The colours of all the painted art (frames, headers, rows, buttons, slots, bars). With the Ember and Ember Vibrant palettes: Warm iron (the metal in warm browns), Bronze (warm browns with gold bevels), or the Original painted grey iron and bright red. With any other palette: that palette's own colours, or the Original. Pictures keep their own colours."] = "Цвета всей рисованной графики (рамки, заголовки, строки, кнопки, ячейки, полосы). С палитрами Ember и Ember Vibrant: тёплое железо (металл в тёплых коричневых тонах), бронза (тёплые коричневые с золотыми фасками) или оригинальное рисованное серое железо с ярко-красным. С любой другой палитрой: её собственные цвета или оригинал. Изображения сохраняют свои цвета.", -- draft
-- stale: ["The column of widgets: loot rolls, summons, Voice Over, whispers and the rest. A new one does not bring the column back: In Combat keeps a loot roll, a summons or a whisper faded out of combat, On Mouseover until you point at the column. Always: never faded. In Combat: faded out of combat, back in a fight. On Mouseover: faded all the time, shown while you point at it."] = "Колонка виджетов: розыгрыш добычи, призывы, Voice Over, шёпот и остальное. Новый виджет не возвращает колонку: «В бою» держит розыгрыш добычи, призыв или шёпот погашенными вне боя, «При наведении» — пока вы не укажете на колонку. «Всегда»: никогда не гаснет. «В бою»: гаснет вне боя, возвращается в бою. «При наведении»: погашена всё время, видна, пока вы на неё указываете.", -- draft
-- stale: ["The configurator: one painted window per skin that moves a little while open (Oldschool's in ink on parchment); Quality of Life holds Automation, Screen Text, Reminders and Tooltip."] = "Конфигуратор: одно рисованное окно на облик, слегка оживающее при открытии (у Oldschool — чернила на пергаменте); «Удобство» объединяет автоматизацию, экранный текст, напоминания и подсказку.", -- draft
