-- stale: ["The display keeps its place by your character as you zoom the camera: closer under your feet when you zoom out, further down when you zoom in, so it never covers your character. Place it in Edit Layout at the zoom you play at; it follows from there. Turning the camera up or down is not followed (the game does not tell)."] = "Дисплей держит своё место у персонажа при зуме камеры: ближе к ногам при отдалении, ниже при приближении, чтобы никогда не закрывать персонажа. Поставьте его в «Изменить раскладку» на том зуме, с которым играете; дальше он следует. Наклон камеры вверх-вниз не отслеживается (игра его не сообщает).", -- draft
