-- stale: ["The frame round every progress bar: reputation and skills, the professions' ranks, legacy, guild, experience, the tracker's, the tooltip's and the damage meter's. The unit frames, the nameplates, the cast bar, the swing timers and the Personal Display have a border of their own."] = "Рамка вокруг каждой полосы прогресса: репутация и навыки, ранги профессий, наследие, гильдия, опыт, полосы отслеживания, подсказки и счётчика урона. У рамок, индикаторов здоровья, индикатора заклинаний, таймеров удара и личного дисплея своя рамка.", -- draft
