-- stale: ["The frame round the Personal Display's bars and its shield column (the bars under your character): the Ornate bracket the unit frames wear (the default), the cast bar's, a thin rim, the Single rail, the Stone rail, the Backdrop or none. The game's own personal resource display, while the Personal Display is off and the unit frames wear their Painted Skin, takes one frame round its bars: a thin rim or one of the library's styles."] = "Рамка вокруг полос личного дисплея и его колонки щита (полосы под вашим персонажем): узорная скоба рамок (по умолчанию), скоба индикатора заклинаний, тонкая окантовка, одинарная планка, каменная планка, подложка или нет. Собственный личный индикатор ресурсов игры, пока личный дисплей выключен, а рамки в рисованном облике, получает одну рамку вокруг полос: тонкую окантовку или один из стилей библиотеки.", -- draft
