-- stale: ["The frame round your cast bar: the Cast bar bracket with its gem clusters (today's), a thin rim, the Single rail or the Backdrop. A frame laid round the bar leaves it its whole width."] = "Рамка вокруг вашего индикатора заклинаний: скоба индикатора заклинаний с группами самоцветов (текущая), тонкая окантовка, одинарная планка или подложка. Рамка вокруг полосы оставляет ей всю ширину.", -- draft
