-- stale: ["The game's chat buttons in their column left of the chat: Friends at the top, Channels, the chat menu (Say, Party, Guild, Yell, whisper and reply, emotes, and the language you speak). While you speak more than one language, the one you speak shows at the right end of the line you type in. Off: the column is hidden."] = "Кнопки чата игры в колонке слева от чата: «Друзья» сверху, «Каналы», меню чата («Сказать», «Группа», «Гильдия», «Крикнуть», шёпот и ответ, эмоции и язык, на котором вы говорите). Если вы говорите на нескольких языках, текущий виден на правом конце строки ввода. Выкл.: колонка скрыта.", -- draft
