-- stale: ["The game's sparkle on quest items you can loot, kept on through its graphics presets, and golden glints over the ore veins and herbs you walk up to: dim out of reach, bright in reach, grey when your skill is too low. The game settings it needs come back as you had them when it is off."] = "Искра игры на предметах для заданий, которые можно забрать, сохраняемая вопреки её графическим наборам, и золотые блики на рудных жилах и травах, к которым вы подходите: тусклые вне досягаемости, яркие в досягаемости, серые, если навык слишком низок. Нужные параметры игры возвращаются в прежнем виде при выключении.", -- draft
-- stale: ["The game's windows and HUD dressed in the painted kit, and the frame of MelloUI's own windows. Off: the game's windows and HUD keep the game's own art; MelloUI's own parts (the Quest Tracker, the widget column, the reminders, the race bar ...) keep MelloUI's look either way, and every feature keeps working. Switching it on also switches Custom Sounds on, and the first time puts in the Edit Mode layout the reskin is drawn for, fitted to your screen. Switching it off leaves Custom Sounds on."] = "Окна и HUD игры в рисованном наборе и рамка собственных окон MelloUI. Выкл.: окна и HUD игры сохраняют её оформление; собственные части MelloUI (отслеживание заданий, колонка виджетов, напоминания, полоса гонки...) в любом случае сохраняют облик MelloUI, и все функции продолжают работать. При включении также включаются «Свои звуки», а в первый раз ставится раскладка режима редактирования, под которую нарисован облик, подогнанная под ваш экран. При выключении «Свои звуки» остаются включены.", -- draft
