-- stale: ["The numbers of the damage you deal, over the enemies. Game: the game's own numbers, as always. Rise, Beside, Fan or Stack: drawn by MelloUI at each enemy's nameplate in its soft look, the game's numbers switched off meanwhile: crits gold and bigger, spells violet, a dodge or parry as a word, about a second and a half each, only on enemies you or your pet are fighting. Beside starts them at the plate's right end, so the name stays readable. Rise, Beside, Fan and Stack draw your hits while you play solo. In a group, or where the game keeps threat hidden, the game's own numbers show, because only they know whose hit it is. With enemy nameplates off, the game's own numbers show too (the plates are where MelloUI draws)."] = "Числа наносимого вами урона над врагами. «Игра»: числа игры, как всегда. «Подъём», «Сбоку», «Веер» или «Стопка»: рисуются MelloUI у индикатора здоровья каждого врага в мягком облике, а числа игры тем временем выключены: криты золотые и крупнее, заклинания фиолетовые, уклонение или парирование словом, около полутора секунд каждое, только на врагах, с которыми сражаетесь вы или питомец. «Сбоку» начинает их у правого края индикатора, чтобы имя читалось. «Подъём», «Сбоку», «Веер» и «Стопка» рисуют ваши удары, пока вы играете в одиночку. В группе или там, где игра скрывает угрозу, видны числа игры: только они знают, чей это удар. При выключенных индикаторах здоровья врагов тоже видны числа игры (MelloUI рисует на индикаторах).", -- draft
-- stale: ["The numbers of your damage over the enemies (the game's own setting: drawn by the game in the Game Numbers Font, at Numbers Over Enemies' size)."] = "Числа вашего урона над врагами (собственный параметр игры: рисуются игрой «Шрифтом чисел игры» в размере «Чисел над врагами»).", -- draft
-- stale: ["The numbers of your healing over the ones you heal (the game's own setting)."] = "Числа вашего исцеления над теми, кого вы лечите (собственный параметр игры).", -- draft
-- stale: ["The numbers over the enemies: the game's own (after /reload) and Your Damage's (at once); and the hit numbers on the unit frames' portraits. The game's text around you (Combat Text's Game style) and MelloUI's are drawn in the Interface text face."] = "Числа над врагами: собственные игры (после /reload) и «Вашего урона» (сразу); и числа ударов на портретах рамок. Текст игры вокруг вас (стиль «Игра» в «Тексте боя») и текст MelloUI рисуются шрифтом «Текста интерфейса».", -- draft
-- stale: ["The numbers: cooldown counts, stack counts; and the chat windows while Chat text and Interface text both keep the game's. The value text on the unit frames' bars follows the Interface text, the hit numbers on the portraits the Game Numbers Font."] = "Числа: отсчёт времени восстановления, число зарядов; и окна чата, пока «Текст чата» и «Текст интерфейса» оба оставляют игровой. Текст значений на полосах рамок следует «Тексту интерфейса», числа ударов на портретах — «Шрифту чисел игры».", -- draft
