-- stale: ["The painted kit reskin, area by area, and the interface's features: buffs and debuffs, error messages, cooldowns, unit frames, chat, tooltips, fonts, dark mode and more. The look is chosen on the Look page and on each element's own page."] = "Рисованный облик набора, область за областью, и функции интерфейса: положительные и отрицательные эффекты, сообщения об ошибках, время восстановления, рамки, чат, подсказки, шрифты, тёмный режим и многое другое. Облик выбирается на странице «Облик» и на странице каждого элемента.", -- draft
