-- stale: ["The painted look and layout. Features stay off."] = "Рисованный облик и раскладка. Функции остаются выключены.", -- draft
-- stale: ["The painted reskin AND every feature of UI Modifications: Vendor, Error Messages, Cooldown Timers, Nameplate Tweaks, Chat, Tooltip, Fonts, Dark Mode, Bar Textures, Buffs & Debuffs, Unit Frame Tweaks, FPS / Latency, Class Icons, Bar Values, the game windows' skins, hiding the micro menu, the bag bar and the minimap coordinates, and the world text scale. Off: all of them are off, Edit Layout lets go of the game's windows (they go back to the game's own places), Windows Fade In stops, names are shown in full and Class Coloured Names stops. The palette, the UI Shade, Reduce Motion and MelloUI's notices keep working."] = "Рисованный облик И каждая функция «Изменений интерфейса»: «Торговец», «Сообщения об ошибках», «Таймеры восстановления», «Доработки индикаторов здоровья», «Чат», «Подсказка», «Шрифты», «Тёмный режим», «Текстуры полос», «Баффы и дебаффы», «Доработки рамок», «FPS / задержка», «Значки классов», «Значения полос», облики окон игры, скрытие микроменю, панели сумок и координат мини-карты, и масштаб текста в мире. Выкл.: всё это выключено, «Изменить раскладку» отпускает окна игры (они возвращаются на свои места игры), «Плавное появление окон» прекращается, имена показываются полностью, а «Имена в цвете класса» прекращаются. Палитра, «Тень интерфейса», «Меньше движения» и оповещения MelloUI продолжают работать.", -- draft
