-- stale: ["The party frames, the game's and the raid-style ones. Always: never faded. In Combat: faded out of combat, back in a fight. On Mouseover: faded all the time, shown while you point at it."] = "Рамки группы, игровые и в стиле рейда. «Всегда»: никогда не гаснет. «В бою»: гаснет вне боя, возвращается в бою. «При наведении»: погашена всё время, видна, пока вы на неё указываете.", -- draft
-- stale: ["The player, target, focus, target of target, pet and party frames in MelloUI's look, exactly as the game lays them out: a gold ring round the portrait, a dark level badge, and gold-lined iron borders round the name, health and power; the elite's and boss's golden dragon and the rare's silver one round the target. Off: the game's own frame art. The painted skin's frames keep their own (Oldschool)."] = "Рамки игрока, цели, фокуса, цели цели, питомца и группы в облике MelloUI, ровно в раскладке игры: золотое кольцо вокруг портрета, тёмный значок уровня и железные рамки с золотой линией вокруг имени, здоровья и ресурса; золотой дракон элиты и босса и серебряный дракон редкого вокруг цели. Выкл.: оформление рамок игры. Рамки рисованного облика сохраняют своё (Oldschool).", -- draft
