-- stale: ["The rim round your buffs and debuffs, the target's and the nameplates' (Buffs & Debuffs): a plain black edge or one of the thin rims the buttons wear. The debuff colour stays round the icon. Only MelloUI's own aura rows wear it (Buffs & Debuffs, off by default): the game's own buff and debuff icons keep their edge, which Dark Mode's Buffs & Debuffs darkens."] = "Окантовка ваших положительных и отрицательных эффектов, эффектов цели и индикаторов здоровья («Баффы и дебаффы»): простой чёрный край или одна из тонких окантовок кнопок. Цвет отрицательного эффекта остаётся вокруг значка. Её носят только собственные ряды эффектов MelloUI («Баффы и дебаффы», по умолчанию выкл.): собственные значки игры сохраняют свой край, который затемняет пункт «Баффы и дебаффы» тёмного режима.", -- draft
-- stale: ["The ring round the portraits of the unit frames: the player, target, focus, pet, target of target and party. The gem ring, a ring with four diamond studs, a plain heavy ring, or the winged border the windows wear. An elite, rare or boss shows the ring in its metal with its crest (Elite and Rare Marks)."] = "Кольцо вокруг портретов на рамках: игрок, цель, фокус, питомец, цель цели и группа. Кольцо с самоцветами, кольцо с четырьмя ромбовидными заклёпками, простое толстое кольцо или крылатая рамка окон. Элитный, редкий или босс показывает кольцо в своём металле со своим гербом (метки элиты и редких).", -- draft
