-- stale: ["The target's and focus's portrait ring and level circle in gold for an elite, silver for a rare or rare elite and red-bronze for a boss, with a small crest on the ring's top gem: a crown, a silver star, a gold star or a skull. Their target's ring too."] = "Кольцо портрета и круг уровня цели и фокуса золотые для элиты, серебряные для редкого или редкого элитного и красно-бронзовые для босса, с маленьким гербом на верхнем самоцвете кольца: корона, серебряная звезда, золотая звезда или череп. И кольцо их цели тоже.", -- draft
-- stale: ["The text an NPC greets you with when you talk to them."] = "Текст, которым NPC приветствует вас, когда вы с ним говорите.", -- draft
