-- stale: ["The title bar of every window, at the game's own size: a red ribbon, or a plain band with a rail line under it. The red plate riding the rail goes with the double rail. Windows already opened change after a /reload."] = "Полоса заголовка каждого окна в размере игры: красная лента или простая полоса с линией планки под ней. Красная табличка на планке подходит к двойной планке. Уже открытые окна изменятся после /reload.", -- draft
-- stale: ["The tooltips on a parchment sheet, their text in dark ink."] = "Подсказки на листе пергамента, текст тёмными чернилами.", -- draft
-- stale: ["The tooltips' background: the painted kit (Painted), the kit with a parchment sheet whose text is dark ink (Parchment), a flat near-black box with a dark border in your palette's colours (Dark), or the game's own. Painted and Parchment need the reskin on (Oldschool)."] = "Фон подсказок: рисованный набор («Рисованный»), набор с листом пергамента и текстом тёмными чернилами («Пергамент»), плоское почти чёрное поле с тёмной рамкой в цветах вашей палитры («Тёмный») или фон игры. «Рисованный» и «Пергамент» требуют включённого облика (Oldschool).", -- draft
-- stale: ["The tooltips: their backdrop, the unit lines, where they sit, and the quest lines on them."] = "Подсказки: их фон, строки юнитов, где они стоят и строки заданий на них.", -- draft
-- stale: ["The tracker as wide on the screen as the minimap (the round map's width, or the square map's frame) and, unless you moved it yourself, right under it: it moves and changes size with the map (the Minimap Kit's Width and Height). Needs the Minimap Kit. Off: the Width below, under the game's tracker's place."] = "Отслеживание такой же ширины на экране, как мини-карта (ширина круглой карты или рамки квадратной) и, если вы не двигали его сами, прямо под ней: двигается и меняет размер вместе с картой («Ширина» и «Высота» набора мини-карты). Нужен набор мини-карты. Выкл.: «Ширина» ниже, на месте отслеживания игры.", -- draft
-- stale: ["The tracker's headers and backdrop in the kit."] = "Заголовки и фон отслеживания в наборе.", -- draft
