-- stale: ["What an empty bag slot shows inside its rim. Both are chosen with pictures on Windows > Bags. The slots' rim is the Button Border (Oldschool > Borders, every window's)."] = "Что пустая ячейка сумки показывает внутри ободка. Оба выбираются по картинкам в Окна > Сумки. Ободок ячеек — «Рамка кнопок» (Oldschool > Рамки, каждого окна).", -- draft
