-- stale: ["What lies behind the health and power bars, under the fill, the heals coming in and the bars' borders: the painted dark trough, a flat dark, the Bar Texture's finish in the dark, or nothing. Every unit frame: the player, target, focus, pet, target of target and party."] = "Что лежит за полосами здоровья и ресурса, под заливкой, входящим исцелением и рамками полос: рисованный тёмный жёлоб, плоская тьма, отделка «Текстуры полос» в тёмном или ничего. Каждая рамка: игрок, цель, фокус, питомец, цель цели и группа.", -- draft
-- stale: ["What lies behind the health bar: a flat colour (Background Colour), one of MelloUI's backgrounds (stone, concrete, parchment, the dark gradients...), or none."] = "Что лежит за полосой здоровья: сплошной цвет («Цвет фона»), один из фонов MelloUI (камень, бетон, пергамент, тёмные градиенты...) или ничего.", -- draft
-- stale: ["What lies behind the player, target and focus frames inside their backdrop."] = "Что лежит за рамками игрока, цели и фокуса внутри их подложки.", -- draft
