-- stale: ["What the bag windows show behind the items (Bags by Kind's window too, and the bank): cracked concrete (the window's own), stone, iron plate, parchment, leather or dark."] = "Что окна сумок показывают за предметами (окно «Сумок по видам» тоже, и банк): потрескавшийся бетон (собственный фон окна), камень, железную пластину, пергамент, кожу или тьму.", -- draft
-- stale: ["What the character window shows behind everything: its own stone, or stone, cracked concrete, iron plate, leather or dark. Parchment is Oldschool > Parchment's Character Window: under the right pane, or over the whole window (on its own stone, whatever this shows). The equipment slots, the progress bars and the side tabs wear the borders of Oldschool > Borders (every window's)."] = "Что окно персонажа показывает позади всего: свой камень или камень, потрескавшийся бетон, железную пластину, кожу или тьму. Пергамент — это «Окно персонажа» в Oldschool > Пергамент: под правой панелью или на всё окно (на своём камне, что бы ни показывало это). Ячейки экипировки, полосы прогресса и боковые вкладки носят рамки из Oldschool > Рамки (каждого окна).", -- draft
-- stale: ["What the crafting page shows behind the recipe list and the recipe: cracked concrete, stone, iron plate, parchment, leather or dark."] = "Что страница изготовления показывает за списком рецептов и рецептом: потрескавшийся бетон, камень, железную пластину, пергамент, кожу или тьму.", -- draft
-- stale: ["What the professions' book page shows behind the profession cards: cracked concrete, stone, iron plate, parchment, leather or dark. The spells' rims wear the Button Border, the rank bars the Progress Bar Border (Oldschool > Borders)."] = "Что страница книги профессий показывает за карточками профессий: потрескавшийся бетон, камень, железную пластину, пергамент, кожу или тьму. Ободки заклинаний носят «Рамку кнопок», полосы рангов — «Рамку полос прогресса» (Oldschool > Рамки).", -- draft
-- stale: ["What the race bar races. Auto: healing while your group role is healer, else damage."] = "Что соревнуется на полосе гонки. «Авто»: исцеление, пока ваша роль в группе — лекарь, иначе урон.", -- draft
-- stale: ["What the recipe list shows behind its rows: its darker list stone, or one of the other backgrounds. All three are chosen with pictures on Windows > Professions. The reagent slots wear the Button Border, the rank bar the Progress Bar Border, the finished item the Round Border (Oldschool > Borders, every window's)."] = "Что список рецептов показывает за своими строками: свой более тёмный камень списка или один из других фонов. Все три выбираются по картинкам в Окна > Профессии. Ячейки реагентов носят «Рамку кнопок», полоса ранга — «Рамку полос прогресса», готовый предмет — «Круглую рамку» (Oldschool > Рамки, каждого окна).", -- draft
-- stale: ["What to keep in your bags and how many. Each character has its own list; a new one starts with suggestions for its class. Also /restock."] = "Что держать в сумках и сколько. У каждого персонажа свой список; новый начинается с предложений для его класса. Также /restock.", -- draft
-- stale: ["When an NPC's greeting text was changed but the pack has exactly one recorded greeting for that NPC, play the recording anyway instead of reading the new text aloud. The words will not match what is on screen."] = "Если текст приветствия NPC изменился, но в пакете есть ровно одно записанное приветствие этого NPC, всё равно проигрывает запись вместо чтения нового текста. Слова не совпадут с тем, что на экране.", -- draft
-- stale: ["When an action's cooldown runs out, a golden light runs once round its button, so you see it is ready again. Never for the global cooldown."] = "Когда время восстановления действия истекает, золотой свет один раз обегает его кнопку, чтобы было видно, что оно снова готово. Никогда для общего времени восстановления.", -- draft
-- stale: ["When an item comes into your bag window or leaves it, the others glide to their new slots instead of jumping there; one that moves to the next row slides in at its start, and a new one fades in. Switching between the Backpack and the Reagent Bag fades the window's items over. Not while you hold an item (its + slots come and go at once), not with Reduce Motion."] = "Когда предмет появляется в окне сумок или покидает его, остальные плавно перемещаются в новые ячейки, а не прыгают; переходящий на следующий ряд въезжает в его начало, а новый проявляется. Переключение между рюкзаком и сумкой для реагентов плавно сменяет предметы окна. Не пока вы держите предмет (его ячейки + появляются и исчезают сразу) и не при «Меньше движения».", -- draft
-- stale: ["When no map pin is set, route to the quest you are tracking (the one with the arrow): to the nearest place for an objective you have not finished yet (a creature to kill, an object to use, where the item drops or is sold, a place to explore), and to its turn-in once it is complete. An objective that needs an item in your bags first (remains to bury, a key for a cage) is routed to where that item comes from until you have it."] = "Когда метка на карте не задана, ведёт к заданию, которое вы отслеживаете (со стрелкой): к ближайшему месту для невыполненной цели (существо для убийства, объект для использования, где выпадает или продаётся предмет, место для исследования), а после выполнения — к сдаче. Цель, которой сначала нужен предмет в сумках (останки для захоронения, ключ от клетки), ведёт туда, откуда этот предмет берётся, пока он у вас не появится.", -- draft
-- stale: ["When nothing is super-tracked, follow the first quest on the game's watch list instead of showing nothing. That is the game's own order of the quests you watch, not the Quest Tracker's Nearest Quest First order."] = "Когда ничего не выделено, следует первому заданию в списке наблюдения игры вместо того, чтобы ничего не показывать. Это собственный порядок игры для отслеживаемых заданий, а не порядок «Ближайшее задание первым» отслеживания заданий.", -- draft
-- stale: ["When one of your professions can learn its next rank at a trainer: Journeyman, Expert or Artisan."] = "Когда одна из ваших профессий может изучить следующий ранг у наставника: Подмастерье, Умелец или Искусник.", -- draft
-- stale: ["When something does not fit because your bags are full, the bag window's Empty slot (it shows 0 then) gives one short shake and a red flash; with the bags closed, the backpack button flashes red. Once each time, as the game's own \"Inventory is full.\" line comes. Not with Reduce Motion."] = "Когда что-то не помещается, потому что сумки полны, ячейка «Пусто» окна сумок (тогда она показывает 0) коротко вздрагивает и вспыхивает красным; при закрытых сумках красным вспыхивает кнопка рюкзака. По разу каждый раз, когда приходит строка игры «Нет места.». Не при «Меньше движения».", -- draft
-- stale: ["When the World Marker comes up for a new destination, a small light flies from your character to the place and lights it: the beam rises and the mark pops in as it lands. It follows the place as you turn the camera; while the place is off the screen it settles into the arrow beside your character. Firefly: a bright point with a short streak. Embers: a smaller glow shedding sparks. Not with Reduce Motion. Part of the World Marker."] = "Когда мировой маркер появляется для новой цели, маленький свет летит от персонажа к месту и зажигает его: поднимается луч, и метка появляется при приземлении. Следует за местом при повороте камеры; пока место за экраном, устраивается в стрелке рядом с персонажем. «Светлячок»: яркая точка с коротким хвостом. «Угольки»: свечение поменьше, роняющее искры. Не при «Меньше движения». Часть мирового маркера.", -- draft
-- stale: ["When you enter a dungeon or raid, list in chat the quests for it you could have picked up but have not."] = "При входе в подземелье или рейд перечисляет в чате задания для него, которые вы могли взять, но не взяли.", -- draft
-- stale: ["When you gain a level, a light runs along the experience bar and the on-screen notice says your new level and, with the Quest List, how many quests it opened in your zone (their givers pop onto the world map the next time it shows them). With the painted reskin, the number in your player frame's level circle also turns over with a ring of light. Not with Reduce Motion: then only the notice."] = "Когда вы получаете уровень, по индикатору опыта пробегает свет, а оповещение на экране называет ваш новый уровень и, со «Списком заданий», сколько заданий он открыл в вашей зоне (те, кто их даёт, появятся на карте мира, когда она их покажет в следующий раз). С рисованным обликом число в круге уровня вашей рамки игрока тоже переворачивается с кольцом света. Не при «Меньше движения»: тогда только оповещение.", -- draft
-- stale: ["When you gain experience, the stretch of the experience bar just gained lights up while a light runs along it to the new end. Not with Reduce Motion."] = "Когда вы получаете опыт, только что полученный отрезок индикатора опыта загорается, пока по нему пробегает свет до нового конца. Не при «Меньше движения».", -- draft
-- stale: ["When you reach a level with new spells at your class trainer. It stays until you have learned them; each visit to your class trainer tells MelloUI when the next ones come, and before your first visit it goes by the levels trainers teach at."] = "Когда вы достигаете уровня с новыми заклинаниями у наставника класса. Остаётся, пока вы их не изучите; каждый визит к наставнику класса сообщает MelloUI, когда придут следующие, а до первого визита он ориентируется по уровням, на которых учат наставники.", -- draft
-- stale: ["When you tank a group, between pulls: a healer of your group is drinking, so wait before the next pull. It goes when they stop or a fight starts. The game keeps party mana hidden from addons, so it shows their drinking, not their mana."] = "Когда вы танкуете группу, между пулами: лекарь вашей группы пьёт, так что подождите со следующим. Исчезает, когда он перестаёт или начинается бой. Игра скрывает ману группы от модификаций, поэтому показывается, что он пьёт, а не его мана.", -- draft
-- stale: ["When your target dodges, parries or is missed, the word flicks off the side of its plate."] = "Когда ваша цель уклоняется, парирует или вы промахиваетесь, слово слетает с края её индикатора.", -- draft
-- stale: ["Where Raid Frame Border goes: on each raid frame, round each raid group, or both. A group's border shows while Edit Mode's Display Border is on for the raid frames."] = "Где проходит рамка рейда: на каждой рамке рейда, вокруг каждой группы рейда или и там, и там. Рамка группы видна, пока в режиме редактирования для рамок рейда включено «Показывать рамку».", -- draft
-- stale: ["Where the next row of buffs goes: under the first, or over it."] = "Куда идёт следующий ряд эффектов: под первый или над ним.", -- draft
-- stale: ["Where the reminder button sits beside your portrait. With the player frame hidden it keeps a place of its own, which you can move in Edit Layout."] = "Где стоит кнопка напоминания у вашего портрета. При скрытой рамке игрока у неё своё место, которое можно сдвинуть в «Изменить раскладку».", -- draft
-- stale: ["Where the text sits on the bar."] = "Где текст стоит на полосе.", -- draft
