-- stale: ["While a heal over time of yours runs (Renew, Rejuvenation, Regrowth's), each of its ticks plays a small pulse on the frame: a ring and three motes (Holy), a leaf (Nature), a drop and a ripple (Water), the border's breath (Quiet, and in a raid). Timed from the game's spell data: Renew ticks five times in 15 seconds."] = "Пока действует ваше периодическое исцеление («Обновление», «Омоложение», у «Восстановления»), каждый тик играет на рамке маленький импульс: кольцо и три искры («Свет»), лист («Природа»), капля и рябь («Вода»), дыхание рамки («Тихо», и в рейде). Время по данным заклинаний игры: «Обновление» тикает пять раз за 15 секунд.", -- draft
-- stale: ["While the bag bar is hidden, show the bag slots under the open bag window so bags can still be equipped and removed. Works with and without the Combine Bags option."] = "Пока панель сумок скрыта, показывает ячейки сумок под открытым окном сумки, чтобы сумки по-прежнему можно было надевать и снимать. Работает и с параметром «Объединить сумки», и без него.", -- draft
-- stale: ["While the objective marks are on, the game's own blue quest areas and quest markers on the world map are switched off, through the game's own Quest Objectives setting (the quest buttons in the game's quest tracker go with it). Turning this or the marks off gives the game's setting back as you had it."] = "Пока включены метки целей, синие области заданий и маркеры заданий игры на карте мира выключены через собственный параметр игры «Цели заданий» (кнопки заданий в отслеживании игры уходят вместе с ним). Выключение этого или меток возвращает параметр игры в прежнем виде.", -- draft
-- stale: ["While you are not in a group, your own frame stands where your party's will, with your indicators on it. Move it in Edit Layout. With In A Party set to Party Frames, it is a normal party frame where the game's party frames stand (move those in Edit Mode)."] = "Пока вы не в группе, ваша рамка стоит там, где будут рамки группы, с вашими индикаторами. Переместите её в «Изменить раскладку». Если «В группе» = «Рамки группы», это обычная рамка группы там, где стоят рамки группы игры (их двигают в режиме редактирования).", -- draft
-- stale: ["While you are stunned, feared, silenced or locked out of a school, the bars' rim turns red and a line under them runs down its time, its name under it. The game's own banner over your character is off while this is on, and comes back as you had it when it is off."] = "Пока вы оглушены, напуганы, немы или заблокирована школа, ободок полос краснеет, а линия под ними отсчитывает время, с названием под ней. Собственное табло игры над персонажем выключено, пока это включено, и возвращается в прежнем виде при выключении.", -- draft
-- stale: ["While you hold an action button's key, or press it with the mouse, the whole button lights up in the colour scheme's highlight colour, so you can see which button you are pressing."] = "Пока вы держите клавишу кнопки действия или нажимаете её мышью, вся кнопка светится цветом выделения схемы, чтобы было видно, какую кнопку вы нажимаете.", -- draft
-- stale: ["While you hold an item, every kind in your bag window shows a + slot: drop the item there and it always goes under that kind (drop it on its own kind's + to put it back). Forget puts every item you placed back under its own kind."] = "Пока вы держите предмет, каждый вид в окне сумок показывает ячейку +: бросьте предмет туда, и он всегда будет под этим видом (бросьте на + его собственного вида, чтобы вернуть). «Забыть» возвращает каждый размещённый предмет под его собственный вид.", -- draft
-- stale: ["Who draws the text over your character. Game: the game's own, as it always was. Lanes: damage taken falls on your left, healing rises on your right, procs and Dodge / Parry above your head, resources under your feet. Feed: one column over your portrait, the newest on top. Classic: one stream over your head, like the game's, in MelloUI's font and soft shade."] = "Кто рисует текст над вашим персонажем. «Игра»: текст игры, как всегда. «Дорожки»: полученный урон падает слева, исцеление поднимается справа, срабатывания и уклонение / парирование над головой, ресурсы у ног. «Лента»: одна колонка над портретом, новое сверху. «Классика»: один поток над головой, как у игры, шрифтом и мягкой тенью MelloUI.", -- draft
-- stale: ["Who shows a power bar (mana, rage, energy) under their health."] = "Кто показывает полосу ресурса (мана, ярость, энергия) под здоровьем.", -- draft
-- stale: ["Whose big moments play on the frames. Yours: when you use one (Challenging Shout, Shield Wall, Last Stand, Divine Shield, Evasion ...), your own frame in your party or raid frames plays its effect for as long as it lasts (a roar: 2 seconds). Your group's: when someone of your party or raid uses one, their frame plays it -- you see at a glance who just used Shield Wall or Divine Shield, and whose roar just pulled."] = "Чьи громкие моменты играют на рамках. «Ваши»: когда вы используете способность («Вызывающий крик», «Глухая оборона», «Ни шагу назад», «Божественный щит», «Ускользание» ...), ваша рамка в рамках группы или рейда играет её эффект, пока она длится (крик — 2 секунды). «Группы»: когда кто-то из вашей группы или рейда использует такую способность, его рамка играет её — с одного взгляда видно, кто только что применил «Глухую оборону» или «Божественный щит» и чей крик только что притянул врагов.", -- draft
-- stale: ["Whose nameplate gets the class medallion above the name."] = "Чьи индикаторы здоровья получают медальон класса над именем.", -- draft
-- stale: ["Window text, buttons, tooltips, the quest log, nameplate names and the names above characters in the world (those after /reload)."] = "Текст окон, кнопки, подсказки, журнал заданий, имена на индикаторах здоровья и имена над персонажами в мире (они после /reload).", -- draft
-- stale: ["Window titles, quest and item names in dialogs, mail and book text, and the kit's title plates and headers while the reskin is on. Enchanted Land unless you choose otherwise. Keep the game's leaves each string in the game's own face: Morpheus where the game uses it, the interface face on the strings that start in it (the Quest Tracker's headers, Combat Text's notices)."] = "Заголовки окон, названия заданий и предметов в диалогах, текст писем и книг, а также таблички заголовков и шапки набора, пока облик включён. Enchanted Land, если не выбрать другой. «Оставить игровой» оставляет каждую строку в шрифте игры: Morpheus там, где его использует игра, шрифт интерфейса в строках, которые начинаются в нём (заголовки отслеживания заданий, оповещения «Текста боя»).", -- draft
-- stale: ["Windows framed in gold, snapped ones sharing one rim; the widget column's rows on gold cards, in motion; new class portraits; the Personal Display in gold and in motion."] = "Окна в золотых рамках, пристыкованные делят одну; строки колонки виджетов на золотых карточках, в движении; новые портреты классов; Личная панель в золоте и в движении.", -- draft
-- stale: ["With Heal Effects on (Frame Effects > Heals): the light of a heal you cast gathers at your character's middle instead of on the cast bar, and flies from there to the party or raid frame of the one you heal. It follows the display's place and the camera's zoom."] = "При включённых «Эффектах исцеления» (Эффекты рамок > Исцеление): свет произносимого вами исцеления собирается в середине персонажа, а не на индикаторе заклинаний, и летит оттуда к рамке группы или рейда того, кого вы лечите. Он следует месту дисплея и зуму камеры.", -- draft
-- stale: ["With a choice of rewards: take the one with the highest item level over what you wear in its slot, among those you can use; when none is better, the one that sells for the most."] = "При выборе награды: берёт ту, у которой уровень предмета выше всего над тем, что у вас в этой ячейке, среди тех, что вы можете использовать; если лучше нет — самую дорогую при продаже.", -- draft
-- stale: ["Write these lines in the chat instead of showing them on the screen. They show there even while Chat Notices is off."] = "Пишет эти строки в чат вместо показа на экране. Там они видны, даже если «Оповещения в чате» выключены.", -- draft
-- stale: ["X / Y"] = "X / Y", -- draft
-- stale: ["You are reminded when a line drops below this share of its amount: at 50 %, a line of 20 water reminds you at 9. At a shop it is bought back up to the full amount. The reminder needs Reminders on; the Restock List marks the low lines either way."] = "Напоминание приходит, когда строка опускается ниже этой доли своего количества: при 50 % строка из 20 воды напомнит на 9. У торговца она докупается до полного количества. Напоминанию нужны включённые «Напоминания»; «Список пополнения» в любом случае отмечает строки, где мало.", -- draft
-- stale: ["Your UI and bars stay. MelloUI's features switch on."] = "Ваш интерфейс и панели остаются. Функции MelloUI включаются.", -- draft
-- stale: ["Your addons' minimap buttons (Questie and the others that put a round button on the minimap's edge) taken off the minimap and gathered into one more group in the Services row, AddOns: click it for a list of them. A click on an addon there is that addon's own (left, right or middle), and pointing at it shows its own tooltip. Only with Button Layout's Groups. Off: the buttons go back on the minimap."] = "Кнопки мини-карты ваших модификаций (Questie и другие, что ставят круглую кнопку на край мини-карты) снимаются с мини-карты и собираются в ещё одну группу ряда услуг, «Модификации»: нажмите её, чтобы увидеть их список. Щелчок по модификации там — щелчок самой модификации (левый, правый или средний), а наведение показывает её собственную подсказку. Только с «Группами» в «Раскладке кнопок». Выкл.: кнопки возвращаются на мини-карту.", -- draft
-- stale: ["Your aura indicators on the frames. Off: the frames show none."] = "Ваши индикаторы эффектов на рамках. Выкл.: рамки их не показывают.", -- draft
-- stale: ["Your bag window's kinds in the order they show, the top first: drag a row to move it. A line draws a line across the window between the kinds over and under it; a group puts the kinds under it, to the next line, under one heading you can fold. Untick a kind and its items go to their own type, or to Other. Add kind makes one of your own: it takes the items you drop on its + slot and the ones its rule matches (an item type, a word in the name, a quality), before the game's kinds. Double-click a name to rename it; a kind's cog opens its settings: its name, Split By Type (a heading for each item type, in its place) and an own kind's rule."] = "Виды вашего окна сумок в порядке показа, верхний первым: перетащите строку, чтобы переместить её. «Линия» проводит линию через окно между видами над и под ней; «Группа» собирает виды под ней, до следующей линии, под одним сворачиваемым заголовком. Снимите флажок с вида — и его предметы уйдут в свой тип или в «Прочее». «Добавить вид» создаёт ваш собственный: он берёт предметы, брошенные на его ячейку +, и подходящие под его правило (тип предмета, слово в названии, качество) раньше видов игры. Двойной щелчок по названию переименовывает; шестерёнка вида открывает его настройки: название, «Разделить по типу» (заголовок для каждого типа предмета на его месте) и правило собственного вида.", -- draft
-- stale: ["Your bags in one window of MelloUI's own, sorted by kind: what you picked up lately, gear, quest items, consumables, junk, trade goods and the rest, each under its own heading. The empty slots fold into one slot with their count."] = "Ваши сумки в одном собственном окне MelloUI, отсортированные по видам: недавно поднятое, снаряжение, предметы для заданий, расходуемые, хлам, хозяйственные товары и остальное, каждое под своим заголовком. Пустые ячейки сворачиваются в одну с их числом.", -- draft
-- stale: ["Your bags' buttons. Always: never faded. In Combat: faded out of combat, back in a fight. On Mouseover: faded all the time, shown while you point at it."] = "Кнопки ваших сумок. «Всегда»: никогда не гаснет. «В бою»: гаснет вне боя, возвращается в бою. «При наведении»: погашена всё время, видна, пока вы на неё указываете.", -- draft
-- stale: ["Your bank in the same kinds as your bags, inside the game's bank window: its items under their headings, the lines and groups of the Kinds list, the empty slots folded into one, a + slot in every kind while you hold an item. Deposit and take out as always (right-click, drag). Off: the game's own grid."] = "Ваш банк в тех же видах, что и сумки, внутри окна банка игры: предметы под заголовками, линии и группы списка «Виды», пустые ячейки свёрнуты в одну, ячейка + в каждом виде, пока вы держите предмет. Кладите и забирайте как всегда (правый щелчок, перетаскивание). Выкл.: собственная сетка игры.", -- draft
-- stale: ["Your buffs in a line beside the minimap, level with the map's top and growing away from it, your debuffs on the line under them. They follow the minimap when it moves or changes size. Needs the Minimap Kit; off, they stand where the game's buff bar is."] = "Ваши положительные эффекты в линию рядом с мини-картой, на уровне верха карты и растущие от неё, отрицательные — на линии под ними. Следуют за мини-картой, когда она двигается или меняет размер. Нужен набор мини-карты; выкл. — стоят там, где панель эффектов игры.", -- draft
-- stale: ["Your buffs, then your debuffs on a row of their own. Right-click a buff to cancel it. Beside the minimap, or where the game's buff bar is: that bar comes back while Edit Mode is open, so it can still be moved, and these follow it."] = "Ваши положительные эффекты, затем отрицательные в своём ряду. Правый щелчок по эффекту отменяет его. Рядом с мини-картой или там, где панель эффектов игры: эта панель возвращается, пока открыт режим редактирования, чтобы её можно было двигать, а эти ряды следуют за ней.", -- draft
-- stale: ["Your character"] = "Ваш персонаж", -- draft
