-- stale: ["Your debuffs on enemy nameplates, in place of the game's row. Crowd control stays with the game (and the Nameplates module)."] = "Ваши отрицательные эффекты на индикаторах здоровья врагов вместо ряда игры. Контроль остаётся за игрой (и модулем «Индикаторы здоровья»).", -- draft
-- stale: ["Your debuffs, then your buffs and weapon buffs, under your player frame, as the target's are under the target frame: the same icons, spiral and timers. Right-click a buff to cancel it. They move with the player frame. Off, they stand beside the minimap or where the game's buff bar is."] = "Ваши отрицательные эффекты, затем положительные и эффекты на оружии под рамкой игрока, как у цели под её рамкой: те же значки, спираль и таймеры. Правый щелчок по эффекту отменяет его. Двигаются вместе с рамкой игрока. Выкл.: стоят рядом с мини-картой или там, где панель эффектов игры.", -- draft
-- stale: ["Your dodge, parry or block flicks its word off the health bar's end: your Revenge window, on the bars you watch."] = "Ваше уклонение, парирование или блок слетает словом с конца полосы здоровья: ваше окно «Реванша» на полосах, за которыми вы следите.", -- draft
-- stale: ["Your group's frames show their big moments: a roar's square ripples, a taunt, Shield Wall's steel, Last Stand's heartbeat, an immunity's barrier, an evasion's afterimages -- on your own frame when you use one, on a group mate's when they do."] = "Рамки вашей группы показывают их громкие моменты: квадратные волны крика, провокацию, сталь «Глухой обороны», сердцебиение «Ни шагу назад», барьер неуязвимости, остаточные образы ускользания — на вашей рамке, когда используете вы, на рамке товарища, когда он.", -- draft
-- stale: ["Your heals on your group as light: a cast heal gathers on your cast bar and flies to the frame of the one you heal; an instant one lands on their frame at once. Each kind lands its own way: heals over time, shields, protection, a heal to full, a resurrection."] = "Ваше исцеление группы светом: заклинание исцеления собирается на вашем индикаторе заклинаний и летит к рамке того, кого вы лечите; мгновенное сразу ложится на рамку. Каждый вид приземляется по-своему: периодическое исцеление, щиты, защита, полное исцеление, воскрешение.", -- draft
-- stale: ["Your health and power in percent beside their bars, the spell and its seconds on the cast bar, the shield's amount under its column, and what took your control under the bars."] = "Здоровье и ресурс в процентах рядом с полосами, заклинание и его секунды на индикаторе заклинаний, размер щита под колонкой и то, что лишило вас контроля, под полосами.", -- draft
-- stale: ["Your health, power and cast bar under your character, as Legion's resource display had them, and a shield column beside your character: it fills when a shield goes up, drains as it takes the hits, turns amber when low and breaks when it is gone. The game's own Personal Resource Display is switched off while this is on, and comes back as you had it when it is off; Hide The Game's Cast Bar (on) hides the game's cast bar too, and Swing On The Rails (on) stands in for Swing Timers. This client cannot tell an addon where your character stands, so the display stays where you put it in Edit Layout (under your character to begin with) and hops when you jump."] = "Здоровье, ресурс и индикатор заклинаний под вашим персонажем, как у индикатора ресурсов в Legion, и колонка щита рядом с персонажем: заполняется, когда поднимается щит, убывает по мере принятия ударов, становится янтарной, когда его мало, и разбивается, когда он исчезает. Собственный личный индикатор ресурсов игры выключен, пока включено это, и возвращается в прежнем виде при выключении; «Скрыть индикатор заклинаний игры» (вкл.) скрывает и индикатор заклинаний игры, а «Удары на планках» (вкл.) заменяет «Таймеры удара». Этот клиент не может сообщить модификации, где стоит ваш персонаж, поэтому дисплей остаётся там, где вы поставили его в «Изменить раскладку» (сначала под персонажем), и подпрыгивает, когда вы прыгаете.", -- draft
-- stale: ["Your indicators for the spec you play, and the one you picked: its look, place, size, colour and text. Drag it on the frame above to move it."] = "Ваши индикаторы для специализации, которой вы играете, и выбранный: его облик, место, размер, цвет и текст. Перетащите его по рамке выше, чтобы переместить.", -- draft
-- stale: ["Your layout was fitted to this screen."] = "Ваша раскладка подогнана под этот экран.", -- draft
-- stale: ["Your own buffs and debuffs, the game's or MelloUI's rows by the minimap. Always: never faded. In Combat: faded out of combat, back in a fight. On Mouseover: faded all the time, shown while you point at it."] = "Ваши собственные положительные и отрицательные эффекты, ряды игры или MelloUI у мини-карты. «Всегда»: никогда не гаснет. «В бою»: гаснет вне боя, возвращается в бою. «При наведении»: погашена всё время, видна, пока вы на неё указываете.", -- draft
-- stale: ["Your own frame. In Combat, it also comes back while your health or mana is below full and when you are dead; On Mouseover, it stays faded until you point at it. Always: never faded. In Combat: faded out of combat, back in a fight. On Mouseover: faded all the time, shown while you point at it."] = "Ваша собственная рамка. «В бою» она возвращается ещё и пока здоровье или мана не полные и когда вы мертвы; «При наведении» остаётся погашенной, пока вы на неё не укажете. «Всегда»: никогда не гаснет. «В бою»: гаснет вне боя, возвращается в бою. «При наведении»: погашена всё время, видна, пока вы на неё указываете.", -- draft
