-- stale: ["Your swing timer without a bar of its own: in a fight, two sparks run out from the middle of the health bar's top rail to its ends, and your swing lands as they reach them. An off hand's swings run along the bottom of the power bar. Your shots run on the seam between the health and power bars: cream sparks out while you reload, then a red line grows back from the ends while you aim (stand still: moving holds it), and the shot flies as it meets in the middle. A wand's shots run out once, with no aim. While it is on, MelloUI's Swing Timers step aside and the game's own swing timers stay off."] = "Таймер удара без своей полосы: в бою две искры бегут от середины верхней планки полосы здоровья к её концам, и удар приходится, когда они их достигают. Удары левой рукой бегут по низу полосы ресурса. Выстрелы бегут по шву между полосами здоровья и ресурса: кремовые искры бегут наружу при перезарядке, затем красная линия растёт обратно от концов, пока вы целитесь (стойте: движение её задерживает), и выстрел летит, когда она сходится в середине. Выстрелы жезла бегут один раз, без прицеливания. Пока это включено, «Таймеры удара» MelloUI уступают место, а таймеры игры остаются выключены.", -- draft
